import {
  AUTH_REQUEST_TTL_MS,
  AUTH_TOKEN_TTL_DAYS,
  parseAuthFragment,
  type AuthStatus as ProtocolAuthStatus,
} from '@filedrop/shared';
import { create } from 'zustand';
import { deviceName, platformTag } from '../lib/ids';
import * as api from '../net/api';
import { mintAuthRequest, scrubAuthFragment } from '../net/authRequest';
import {
  clearStandaloneConfig,
  getDeployMode,
  loadStandaloneConfig,
  resolveDeployMode,
  saveStandaloneConfig,
  type DeployMode,
} from '../net/mode';
import { clearSession, loadSession, saveSession, type DeviceSession } from '../net/session';
import { standalone, type NasInfo } from '../net/standalone';
import { transport } from '../net/transport';

/**
 * `setup`, `discovering` and `approving` exist only in standalone mode:
 *
 *   setup        No Agora App ID / channel in this browser yet (public builds).
 *                Private builds bake both, so this screen is skipped.
 *   unpaired     Waiting device: show QR first. Signaling join + NAS contact
 *                happen inside `startAuthRequest` so the user never sits on a
 *                separate "looking for NAS" screen before authorisation.
 *   discovering  Reconnect path only — a device that *already* holds a token
 *                re-finds the NAS before opening the DataChannel. That is the
 *                post-approval P2P step, not a gate on the QR.
 *   approving    This page was opened from a scanned QR. It is acting for
 *                *another* device's authorisation request and must not try to
 *                get itself paired.
 */
export type ScreenStatus = 'booting' | 'setup' | 'discovering' | 'unpaired' | 'approving' | 'paired';

/**
 * Said whenever a stored token stops working, whatever the reason.
 *
 * Access granted through Telegram is deliberately time-boxed and never renews
 * itself, so "it stopped working" is the normal end of a week rather than a
 * fault. Saying so up front is the difference between a user re-scanning a QR
 * and a user filing a bug.
 */
const TOKEN_LAPSED_TEXT = `Access to this NAS lasts ${String(AUTH_TOKEN_TTL_DAYS)} days and does not renew itself. Ask for it again below — the owner just has to approve it in Telegram.`;

/** Poll Telegram approval status often — feels instant on the waiting device. */
const POLL_INTERVAL_MS = 500;
const POLL_MAX_INTERVAL_MS = 5_000;

/** Protocol states that will never change again, so polling should stop. */
function isTerminal(status: ProtocolAuthStatus): boolean {
  return status === 'approved' || status === 'rejected' || status === 'expired' || status === 'blocked';
}

export interface PendingAuthRequest {
  requestId: string;
  /** Kept in memory only, so the QR can be re-rendered on a resize or re-mount. */
  secret: string;
  url: string;
  /** Epoch ms, from the NAS's `auth-registered`. */
  expiresAt: number;
}

interface AuthStore {
  mode: DeployMode;
  status: ScreenStatus;
  session: DeviceSession | null;
  /** Standalone only: what discovery learned about the NAS. */
  nas: NasInfo | null;
  discoverError: string | null;
  pairing: boolean;
  pairError: string | null;

  // --- QR authorisation, waiting device ------------------------------------
  authRequest: PendingAuthRequest | null;
  /** Where the request currently stands, as far as the NAS is concerned. */
  authState: ProtocolAuthStatus | null;
  authAttemptsLeft: number | null;
  /** A transport-level problem (channel down), not a decision by the owner. */
  authError: string | null;
  /** Free text from the NAS, e.g. why a request was blocked. */
  authMessage: string | null;
  authBusy: boolean;
  /** Explains a token that stopped working. Shown above the fresh QR. */
  lapsedNote: string | null;

  // --- QR authorisation, scanning device -----------------------------------
  approval: { requestId: string; secret: string } | null;
  approvalState: 'sending' | 'sent' | 'error';
  approvalError: string | null;

  boot(): void;
  /** Standalone: persist App ID + channel and start discovery. */
  saveSetup(appId: string, channel: string): void;
  retryDiscovery(): void;
  /** Hosted only: the six-digit LAN code. */
  pair(code: string): Promise<void>;
  /** Mint + register a fresh authorisation request and start polling. */
  startAuthRequest(): void;
  /** Scanning device: (re)send `auth-notify`. */
  sendApproval(): void;
  /** Scanning device: stop acting for someone else's request. */
  dismissApproval(): void;
  unpair(): void;
  /** Standalone: drop credentials *and* the App ID/channel, back to setup. */
  forget(): void;
}

/**
 * Poll bookkeeping lives outside the store: it is machinery, not state the UI
 * renders, and keeping it here means a restart can invalidate an in-flight
 * loop without a render pass having to observe the change.
 */
let pollTimer: ReturnType<typeof setTimeout> | null = null;
let pollGeneration = 0;
/** Guards against sending the same `auth-notify` twice. */
let approvalInFlight = false;

function stopPolling(): void {
  pollGeneration += 1;
  if (pollTimer) clearTimeout(pollTimer);
  pollTimer = null;
}

export const useAuth = create<AuthStore>((set, get) => ({
  mode: 'hosted',
  status: 'booting',
  session: null,
  nas: null,
  discoverError: null,
  pairing: false,
  pairError: null,

  authRequest: null,
  authState: null,
  authAttemptsLeft: null,
  authError: null,
  authMessage: null,
  authBusy: false,
  lapsedNote: null,

  approval: null,
  approvalState: 'sending',
  approvalError: null,

  boot: () => {
    void (async () => {
      // Read the fragment before anything else touches the URL. A scanned link
      // carries a one-shot secret, so it is consumed and scrubbed immediately —
      // it has no business surviving into history, screenshots or tab sync.
      //
      // An already-held approval wins, because the scrub means a second `boot()`
      // (StrictMode re-runs the mount effect in development) would otherwise
      // find an empty hash and route the page away from the approval screen.
      const held = get().approval;
      const fragment = held ?? parseAuthFragment(window.location.hash);
      if (!held && fragment) scrubAuthFragment();

      // Decide the mode before anything issues a request: in standalone an
      // `/api/*` call from an https page towards the http NAS is blocked as
      // mixed content and produces nothing but a confusing console error.
      const mode = await resolveDeployMode();
      set({ mode });

      if (fragment) {
        if (mode === 'hosted') {
          set({
            approval: fragment,
            status: 'approving',
            approvalState: 'error',
            approvalError:
              '请用独立 UI（例如 :8421）打开扫码链接，不要用 NAS 本机 /app 页打开。',
          });
          return;
        }
        if (!loadStandaloneConfig()) {
          set({ approval: fragment, status: 'setup', approvalState: 'sending', approvalError: null });
          return;
        }

        // Opening #auth=… always notifies Telegram, then THIS browser polls for
        // the token. That covers:
        //   • same phone opened its own 复制链接 / 扫了自己的码
        //   • waiting tab still open (peer id matches the registrar)
        // A pure messenger (other phone) will not receive a token; it stays on
        // the approve screen until the user taps “申请本机访问”.
        set({
          approval: fragment,
          approvalState: 'sending',
          approvalError: null,
          status: 'approving',
        });
        get().sendApproval();
        return;
      }

      if (mode === 'hosted') {
        const session = loadSession();
        if (!session) {
          set({ status: 'unpaired', session: null });
          return;
        }
        api.setAuthToken(session.token);
        set({ status: 'paired', session });
        void transport.start(session);
        return;
      }

      if (!loadStandaloneConfig()) {
        set({ status: 'setup' });
        return;
      }

      // QR-first for new devices. Do NOT run discover as its own full-screen
      // step before authorisation — that is what made the page look like a
      // networking console instead of "scan this QR". Signaling + finding the
      // NAS happen inside startAuthRequest when the QR is minted; full P2P
      // (bootstrap / DataChannel) starts only after Telegram approves.
      const session = loadSession();
      if (!session) {
        set({ status: 'unpaired', session: null });
        return;
      }
      if (session.tokenExpiresAt && session.tokenExpiresAt <= Date.now()) {
        clearSession();
        api.setAuthToken(null);
        set({ status: 'unpaired', session: null, lapsedNote: TOKEN_LAPSED_TEXT });
        return;
      }
      // Already authorised: re-find the NAS, then open the DataChannel.
      get().retryDiscovery();
    })();
  },

  saveSetup: (appId, channel) => {
    saveStandaloneConfig({ appId, channel });
    // A different channel or App ID invalidates any NAS we found before.
    standalone.disconnect();
    set({ nas: null, discoverError: null });
    const session = loadSession();
    if (session) get().retryDiscovery();
    else set({ status: 'unpaired', session: null });
  },

  retryDiscovery: () => {
    // Reconnect / scanner path only. Unpaired devices mint a QR instead.
    set({ status: 'discovering', discoverError: null });
    void (async () => {
      try {
        const nas = await standalone.discover(true);
        set({ nas, discoverError: null });

        // A held approval outranks everything: this page is acting for another
        // device and must not try to pair itself, even if it has credentials.
        if (get().approval) {
          set({ status: 'approving' });
          get().sendApproval();
          return;
        }

        const session = loadSession();
        if (!session) {
          set({ status: 'unpaired' });
          return;
        }
        if (session.tokenExpiresAt && session.tokenExpiresAt <= Date.now()) {
          // Hard expiry, checked locally so the user is told why rather than
          // watching a connection attempt fail for no visible reason.
          clearSession();
          api.setAuthToken(null);
          set({ status: 'unpaired', session: null, lapsedNote: TOKEN_LAPSED_TEXT });
          return;
        }
        // The agent may have restarted with a different peer id; discovery is
        // authoritative and the stored value is only a hint.
        const refreshed: DeviceSession = {
          ...session,
          nasPeerId: nas.nasPeerId,
          nasName: nas.nasName,
        };
        saveSession(refreshed);
        api.setAuthToken(refreshed.token);
        set({ status: 'paired', session: refreshed });
        void transport.start(refreshed);
      } catch (error) {
        const detail = error instanceof Error ? error.message : String(error);
        // No session yet: surface the failure on the QR screen, not Discover.
        if (!loadSession() && !get().approval) {
          set({ status: 'unpaired', discoverError: null, authError: detail, authBusy: false });
          return;
        }
        set({ status: 'discovering', discoverError: detail });
      }
    })();
  },

  // -------------------------------------------------------------------------
  // QR authorisation — the waiting device
  // -------------------------------------------------------------------------

  startAuthRequest: () => {
    if (get().authBusy) return;
    stopPolling();
    set({
      authBusy: true,
      authRequest: null,
      authState: null,
      authAttemptsLeft: null,
      authError: null,
      authMessage: null,
    });

    void (async () => {
      const generation = pollGeneration;
      try {
        // Mint locally first so the QR payload is ready; only then join
        // signaling and register with the NAS (discover is inside registerAuth).
        const seed = await mintAuthRequest();
        const { expiresAt } = await standalone.registerAuth(seed.requestId, seed.secretHash);
        if (generation !== pollGeneration) return;
        set({
          authBusy: false,
          nas: standalone.nas ?? get().nas,
          authRequest: {
            requestId: seed.requestId,
            secret: seed.secret,
            url: seed.url,
            // The NAS's expiry is authoritative, but a device with a badly wrong
            // clock would otherwise render a countdown that is already at zero
            // and expire a request nobody has even seen. Fall back to the
            // protocol TTL measured locally whenever it is not in the future.
            expiresAt: expiresAt > Date.now() ? expiresAt : Date.now() + AUTH_REQUEST_TTL_MS,
          },
          authState: 'pending',
          authError: null,
        });
        schedulePoll(seed.requestId, POLL_INTERVAL_MS, generation);
      } catch (error) {
        if (generation !== pollGeneration) return;
        const message =
          error instanceof Error ? error.message : 'Could not reach the NAS to ask for access.';
        set({ authBusy: false, authError: message, nas: standalone.nas ?? get().nas });
      }
    })();
  },

  // -------------------------------------------------------------------------
  // QR authorisation — the scanning device
  // -------------------------------------------------------------------------

  sendApproval: () => {
    const approval = get().approval;
    // One notify at a time: `boot()` and `retryDiscovery()` can both reach here
    // for the same held request, and each extra send is another buzz on the
    // owner's phone for a decision they have already been asked to make.
    if (!approval || approvalInFlight) return;
    approvalInFlight = true;
    set({ approvalState: 'sending', approvalError: null });
    void (async () => {
      try {
        await standalone.notifyAuth(approval.requestId, approval.secret);
        set({
          approvalState: 'sent',
          approvalError: null,
          nas: standalone.nas ?? get().nas,
          // Keep a pending request shell so the UI can show "waiting for TG"
          // and so pollAuth has a requestId even if we never showed a QR here.
          authRequest: get().authRequest ?? {
            requestId: approval.requestId,
            secret: approval.secret,
            url: '',
            expiresAt: Date.now() + AUTH_REQUEST_TTL_MS,
          },
          authState: 'notified',
        });
        // Poll every 0.5s: same phone that registered gets the token after TG.
        schedulePoll(approval.requestId, POLL_INTERVAL_MS, pollGeneration);
      } catch (error) {
        const message =
          error instanceof Error ? error.message :
          '无法联系 NAS 转发请求。';
        set({ approvalState: 'error', approvalError: message, nas: standalone.nas ?? get().nas });
      } finally {
        approvalInFlight = false;
      }
    })();
  },

  dismissApproval: () => {
    approvalInFlight = false;
    // Do NOT stopPolling if we're about to keep waiting — only clear messenger
    // state. stopPolling when leaving to a fresh self-QR.
    set({ approval: null, approvalState: 'sending', approvalError: null });
    if (get().mode === 'standalone') {
      const session = loadSession() ?? get().session;
      if (session) {
        stopPolling();
        get().retryDiscovery();
      } else {
        stopPolling();
        set({
          status: 'unpaired',
          session: null,
          authRequest: null,
          authState: null,
          authError: null,
        });
        get().startAuthRequest();
      }
    } else {
      stopPolling();
      get().boot();
    }
  },

  // -------------------------------------------------------------------------
  // Hosted: six-digit LAN pairing over REST. Unchanged.
  // -------------------------------------------------------------------------

  pair: async (code) => {
    set({ pairing: true, pairError: null });
    try {
      const response = await api.pair({
        code: code.trim(),
        deviceName: deviceName(),
        platform: platformTag(),
      });
      const session: DeviceSession = {
        deviceId: response.deviceId,
        token: response.token,
        nasName: response.nasName,
        nasPeerId: response.nasPeerId,
      };
      saveSession(session);
      api.setAuthToken(session.token);
      set({ status: 'paired', session, pairing: false, pairError: null, lapsedNote: null });
      void transport.start(session);
    } catch (error) {
      const message =
        error instanceof api.ApiError && error.status === 400 ?
          'That code is not valid. Check `docker logs filedrop` for the current one.'
        : error instanceof api.ApiError && error.status === 429 ?
          'Too many attempts. Wait a minute and try again.'
        : error instanceof api.ApiError && error.status === 0 ? 'Cannot reach the NAS.'
        : error instanceof Error ? error.message
        : 'Pairing failed.';
      set({ pairing: false, pairError: message });
    }
  },

  unpair: () => {
    transport.stop();
    stopPolling();
    clearSession();
    api.setAuthToken(null);
    // The signaling connection stays up in standalone: the authorisation screen
    // needs it to register the next request.
    set({
      status: 'unpaired',
      session: null,
      pairError: null,
      lapsedNote: null,
      authRequest: null,
      authState: null,
      authAttemptsLeft: null,
      authError: null,
      authMessage: null,
      authBusy: false,
    });
  },

  forget: () => {
    transport.stop();
    stopPolling();
    clearSession();
    clearStandaloneConfig();
    standalone.disconnect();
    api.setAuthToken(null);
    set({
      status: getDeployMode() === 'standalone' ? 'setup' : 'unpaired',
      session: null,
      nas: null,
      discoverError: null,
      pairError: null,
      lapsedNote: null,
      approval: null,
      authRequest: null,
      authState: null,
      authAttemptsLeft: null,
      authError: null,
      authMessage: null,
      authBusy: false,
    });
  },
}));

// ---------------------------------------------------------------------------
// Polling
// ---------------------------------------------------------------------------

/**
 * Ask the NAS where the request stands, on a civil schedule.
 *
 * Two seconds is fast enough that an approval feels immediate and slow enough
 * that a QR left on screen over lunch costs the signaling channel ~300 messages
 * rather than tens of thousands. Transport errors back off geometrically —
 * a NAS that has gone offline should not be hammered — and any terminal status
 * stops the loop outright, because nothing about it can change again.
 */
function schedulePoll(requestId: string, delay: number, generation: number): void {
  if (pollTimer) clearTimeout(pollTimer);
  pollTimer = setTimeout(() => {
    void runPoll(requestId, delay, generation);
  }, delay);
}

async function runPoll(requestId: string, delay: number, generation: number): Promise<void> {
  if (generation !== pollGeneration) return;

  const state = useAuth.getState();
  // Allow poll from either the QR waiting UI or the post-notify approve UI.
  const tracking =
    state.authRequest?.requestId === requestId ||
    state.approval?.requestId === requestId;
  if (!tracking) return;

  const expiresAt = state.authRequest?.expiresAt ?? Date.now() + AUTH_REQUEST_TTL_MS;
  if (Date.now() >= expiresAt) {
    stopPolling();
    useAuth.setState({ authState: 'expired', approvalState: state.approval ? 'error' : state.approvalState });
    return;
  }

  try {
    const result = await standalone.pollAuth(requestId);
    if (generation !== pollGeneration) return;

    useAuth.setState({
      authState: result.status,
      authAttemptsLeft: result.attemptsLeft ?? null,
      authMessage: result.message ?? null,
      authError: null,
    });

    if (result.status === 'approved' && result.token && result.deviceId) {
      stopPolling();
      adoptGrantedToken(result.token, result.deviceId, result.tokenExpiresAt);
      return;
    }
    // Approved but token already collected (double-tab): reload session if any.
    if (result.status === 'approved') {
      const existing = loadSession();
      if (existing) {
        stopPolling();
        api.setAuthToken(existing.token);
        useAuth.setState({
          status: 'paired',
          session: existing,
          approval: null,
          authRequest: null,
        });
        void transport.start(existing);
        return;
      }
      // Keep polling briefly — another tab may not have finished writing; then stop.
      schedulePoll(requestId, POLL_INTERVAL_MS, generation);
      return;
    }
    if (isTerminal(result.status)) {
      stopPolling();
      return;
    }
    schedulePoll(requestId, POLL_INTERVAL_MS, generation);
  } catch (error) {
    if (generation !== pollGeneration) return;
    const message = error instanceof Error ? error.message : String(error);
    useAuth.setState({ authError: message });
    schedulePoll(requestId, Math.min(delay * 2, POLL_MAX_INTERVAL_MS), generation);
  }
}

/** Approved: store the credentials and go straight into the app. */
function adoptGrantedToken(token: string, deviceId: string, tokenExpiresAt?: number): void {
  const state = useAuth.getState();
  const session: DeviceSession = {
    deviceId,
    token,
    nasName: state.nas?.nasName ?? 'your NAS',
    nasPeerId: state.nas?.nasPeerId ?? '',
    ...(tokenExpiresAt !== undefined ? { tokenExpiresAt } : {}),
  };
  saveSession(session);
  api.setAuthToken(token);
  useAuth.setState({
    status: 'paired',
    session,
    lapsedNote: null,
    authRequest: null,
    authState: 'approved',
    // Leave messenger screen if we were on it.
    approval: null,
    approvalState: 'sending',
    approvalError: null,
  });
  void transport.start(session);
}

// ---------------------------------------------------------------------------
// Credential rejection
// ---------------------------------------------------------------------------

/**
 * The NAS stopped honouring this device's token — the 7 days ran out, or the
 * owner revoked it. There is nothing to retry, so drop the credentials and send
 * the user back to the authorisation screen with a fresh QR.
 */
function handleRejection(): void {
  if (useAuth.getState().status !== 'paired') return;
  transport.stop();
  stopPolling();
  clearSession();
  api.setAuthToken(null);
  useAuth.setState({
    status: 'unpaired',
    session: null,
    // Standalone shows `lapsedNote` above a fresh QR; hosted has no QR, so it
    // gets the same explanation phrased for the six-digit code screen.
    lapsedNote: TOKEN_LAPSED_TEXT,
    pairError:
      getDeployMode() === 'hosted' ?
        'This device is no longer authorised by the NAS. Enter a new code to reconnect.'
      : null,
    authRequest: null,
    authState: null,
    authAttemptsLeft: null,
    authError: null,
    authMessage: null,
    authBusy: false,
  });
}

/** Hosted mode: any 401 from the REST API. */
api.onUnauthorized(handleRejection);
/** Standalone mode: `hello-reject` with `unpaired` / `bad-token`. */
transport.onRejected(handleRejection);
