import {
  BROADCAST,
  PROTOCOL_VERSION,
  type AuthStatus,
  type BootstrapResponse,
  type SignalEnvelope,
  type SignalPayload,
} from '@filedrop/shared';
import { deviceName, platformTag, randomId } from '../lib/ids';
import { loadStandaloneConfig, standalonePeerId, type StandaloneConfig } from './mode';
import { AgoraSignaling, type SignalingChannel } from './signaling';
import { TransportError } from './types';

/**
 * Standalone bootstrap — everything the REST API would have done, done over
 * the signaling channel instead.
 *
 * Why this file exists: a page served from GitHub Pages is `https://`, and an
 * `https://` page may not fetch `http://10.0.0.2:8420` — browsers block it as
 * active mixed content with no override, even on the same LAN. So `/api/pair`
 * and `/api/bootstrap` are simply unreachable. WebRTC is exempt from that
 * rule, and Agora RTM is reachable over wss://, so every pre-flight exchange
 * (`discover`, the `auth-*` authorisation handshake, `bootstrap-request`) rides
 * the signaling channel and the DataChannel takes over from there.
 *
 * One RTM connection is kept alive for the whole app session: discovery,
 * authorisation, bootstrap and the WebRTC handshake all share it. Logging in
 * again per attempt would cost a second or two on every reconnect and churn the
 * peer's presence.
 */

/**
 * Ask the private standalone server for a short-lived RTM token.
 *
 * Returns undefined when the endpoint is missing (static host / App-ID-only) or
 * fails — the caller then logs in without a token.
 */
async function fetchSameOriginRtmToken(uid: string): Promise<string | undefined> {
  try {
    const base = import.meta.env.BASE_URL || '/';
    const root = base.endsWith('/') ? base : `${base}/`;
    const url = `${root}api/rtm-token?uid=${encodeURIComponent(uid)}`;
    const res = await fetch(url, { method: 'GET', cache: 'no-store' });
    if (res.status === 204 || res.status === 404) return undefined;
    if (!res.ok) return undefined;
    const body = (await res.json()) as { token?: unknown };
    return typeof body.token === 'string' && body.token.trim() ? body.token.trim() : undefined;
  } catch {
    return undefined;
  }
}

const DISCOVER_TIMEOUT_MS = 14_000;
/**
 * When to re-send `discover`, in ms from the first attempt.
 *
 * Deliberately only two retries on a widening schedule rather than a tight
 * interval: `discover` is a pre-auth message and the NAS rate-limits those per
 * peer id, so a client that machine-guns the channel would lock itself out of
 * the very handshake it is trying to complete.
 */
const DISCOVER_RETRY_DELAYS_MS = [3_000, 8_000];
const BOOTSTRAP_TIMEOUT_MS = 15_000;
const AUTH_TIMEOUT_MS = 15_000;

export interface NasInfo {
  nasName: string;
  nasPeerId: string;
  pairingOpen: boolean;
  protocolVersion: number;
}

export interface AuthPollResult {
  status: AuthStatus;
  token?: string;
  deviceId?: string;
  tokenExpiresAt?: number;
  attemptsLeft?: number;
  message?: string;
}

interface Waiter {
  match: (payload: SignalPayload) => boolean;
  resolve: (payload: SignalPayload) => void;
  reject: (error: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

/**
 * A `SignalingChannel` view over a connection somebody else owns.
 *
 * `PeerLink` expects to connect and close a channel it owns. Here the RTM
 * connection outlives any single peer link, so `connect()` is idempotent and
 * `close()` only *detaches* the consumer's handlers — it never logs out.
 * Requests issued by this module are dispatched before the consumer's handler
 * runs, so both can share the socket.
 */
class SharedChannel implements SignalingChannel {
  readonly name = 'agora' as const;
  onEnvelope: ((envelope: SignalEnvelope) => void) | null = null;
  onClosed: ((reason: string) => void) | null = null;

  private readonly waiters = new Set<Waiter>();
  /** Set once RTM reports the connection gone; the owner rebuilds rather than reuse. */
  dead = false;

  constructor(
    private readonly inner: AgoraSignaling,
    private readonly connected: Promise<void>,
  ) {
    inner.onEnvelope = (envelope) => {
      for (const waiter of [...this.waiters]) {
        if (!waiter.match(envelope.payload)) continue;
        clearTimeout(waiter.timer);
        this.waiters.delete(waiter);
        waiter.resolve(envelope.payload);
      }
      this.onEnvelope?.(envelope);
    };
    inner.onClosed = (reason) => {
      this.dead = true;
      this.failWaiters(new TransportError(`Signaling closed: ${reason}`, 'unreachable'));
      this.onClosed?.(reason);
    };
  }

  connect(): Promise<void> {
    return this.connected;
  }

  send(payload: SignalPayload, to?: string): Promise<void> {
    return this.inner.send(payload, to);
  }

  retarget(peerId: string, session: string): void {
    this.inner.retarget(peerId, session);
  }

  addSelfAlias(id: string): void {
    this.inner.addSelfAlias(id);
  }

  /** Detach the current consumer. The RTM connection stays up on purpose. */
  close(): void {
    this.onEnvelope = null;
    this.onClosed = null;
  }

  /** Really tear the RTM connection down. Only the owning session calls this. */
  destroy(): void {
    this.close();
    this.failWaiters(new TransportError('Signaling shut down', 'unreachable'));
    this.inner.close();
  }

  waitFor(match: (payload: SignalPayload) => boolean, timeoutMs: number, what: string): Promise<SignalPayload> {
    return new Promise((resolve, reject) => {
      const waiter: Waiter = {
        match,
        resolve,
        reject,
        timer: setTimeout(() => {
          this.waiters.delete(waiter);
          reject(new TransportError(what, 'unreachable'));
        }, timeoutMs),
      };
      this.waiters.add(waiter);
    });
  }

  private failWaiters(error: Error): void {
    for (const waiter of [...this.waiters]) {
      clearTimeout(waiter.timer);
      this.waiters.delete(waiter);
      waiter.reject(error);
    }
  }
}

export class StandaloneSession {
  private channel: SharedChannel | null = null;
  private connecting: Promise<SharedChannel> | null = null;
  private config: StandaloneConfig | null = null;
  private info: NasInfo | null = null;

  /** Cleared discovery result, e.g. after a channel change. */
  get nas(): NasInfo | null {
    return this.info;
  }

  isConnected(): boolean {
    return this.channel !== null;
  }

  // -------------------------------------------------------------------------
  // Connection
  // -------------------------------------------------------------------------

  private async ensureChannel(): Promise<SharedChannel> {
    const config = loadStandaloneConfig();
    if (!config) {
      throw new TransportError('This browser has no Agora App ID or channel configured', 'unauthorized');
    }
    // A changed App ID/channel invalidates everything we learned before, and a
    // channel RTM has declared gone cannot be revived — rebuild in both cases.
    const reconfigured =
      this.config !== null &&
      (this.config.appId !== config.appId || this.config.channel !== config.channel);
    if (reconfigured || this.channel?.dead) this.disconnect();
    this.config = config;

    if (this.channel) return this.channel;
    if (this.connecting) return this.connecting;

    const uid = standalonePeerId();
    // Prefer an explicit token (fragment / localStorage). Otherwise ask the
    // same-origin private UI server (`serve-standalone.mjs`) to mint one when
    // the Agora project has an App Certificate. Pure static hosts (GitHub
    // Pages) have no such endpoint and fall back to App-ID-only login.
    this.connecting = (async () => {
      let token = config.token?.trim() || undefined;
      if (!token) {
        token = (await fetchSameOriginRtmToken(uid)) ?? undefined;
      }

      const inner = new AgoraSignaling(
        { selfId: uid, peerId: BROADCAST, session: randomId('b') },
        { appId: config.appId, channel: config.channel, token, uid },
      );
      const shared = new SharedChannel(inner, inner.connect());
      try {
        await shared.connect();
        this.channel = shared;
        return shared;
      } catch (error: unknown) {
        inner.close();
        const message = error instanceof Error ? error.message : String(error);
        throw new TransportError(
          `Could not join the signaling channel — check the App ID (${message})`,
          'unreachable',
        );
      } finally {
        this.connecting = null;
      }
    })();

    return this.connecting;
  }

  disconnect(): void {
    this.channel?.destroy();
    this.channel = null;
    this.connecting = null;
    this.info = null;
  }

  /** The channel `PeerLink` should negotiate on. Throws if not connected yet. */
  signalingChannel(): SignalingChannel {
    if (!this.channel) throw new TransportError('Signaling is not connected', 'unreachable');
    return this.channel;
  }

  // -------------------------------------------------------------------------
  // discover
  // -------------------------------------------------------------------------

  /**
   * Ask "is there a NAS on this channel?" and learn its peer id.
   *
   * Single-active-NAS model: agent + web share one fixed Agora channel from
   * config. Only one agent process should be online at a time (Agora UID =
   * nasPeerId); if several answer briefly, we keep the discover-ack with the
   * latest `startedAt` (most recently started agent — e.g. local debug after
   * stopping the home NAS, or the reverse).
   */
  async discover(force = false): Promise<NasInfo> {
    if (this.info && !force) return this.info;
    const channel = await this.ensureChannel();
    const requestId = randomId('d');

    /** Collect acks for a short window after the first so dual-NAS races settle. */
    const COLLECT_MS = 900;
    const candidates: Array<{
      nasName: string;
      nasPeerId: string;
      pairingOpen: boolean;
      protocolVersion: number;
      startedAt: number;
    }> = [];

    const first = channel.waitFor(
      (payload) => payload.type === 'discover-ack' && payload.requestId === requestId,
      DISCOVER_TIMEOUT_MS,
      'No NAS answered on this channel',
    );

    const retryTimers: Array<ReturnType<typeof setTimeout>> = [];
    try {
      const emit = (): void => {
        void channel.send({ type: 'discover', requestId }, BROADCAST).catch(() => undefined);
      };
      emit();
      for (const delay of DISCOVER_RETRY_DELAYS_MS) retryTimers.push(setTimeout(emit, delay));

      const firstPayload = await first;
      if (firstPayload.type !== 'discover-ack') {
        throw new TransportError('Malformed discovery reply', 'io-error');
      }
      const pushAck = (payload: typeof firstPayload): void => {
        if (payload.type !== 'discover-ack' || payload.requestId !== requestId) return;
        candidates.push({
          nasName: payload.nasName,
          nasPeerId: payload.nasPeerId,
          pairingOpen: payload.pairingOpen,
          protocolVersion: payload.protocolVersion,
          startedAt: typeof payload.startedAt === 'number' ? payload.startedAt : 0,
        });
      };
      pushAck(firstPayload);

      // Keep listening briefly for competing acks (rare dual-agent window).
      const collectUntil = Date.now() + COLLECT_MS;
      while (Date.now() < collectUntil) {
        const remaining = collectUntil - Date.now();
        if (remaining <= 0) break;
        try {
          const more = await channel.waitFor(
            (payload) => payload.type === 'discover-ack' && payload.requestId === requestId,
            remaining,
            'collect-done',
          );
          if (more.type === 'discover-ack') pushAck(more);
        } catch {
          break; // timeout — collection window closed
        }
      }

      // Prefer most recently started agent on this channel.
      candidates.sort((a, b) => b.startedAt - a.startedAt || a.nasPeerId.localeCompare(b.nasPeerId));
      const best = candidates[0]!;
      const info: NasInfo = {
        nasName: best.nasName,
        nasPeerId: best.nasPeerId,
        pairingOpen: best.pairingOpen,
        protocolVersion: best.protocolVersion,
      };
      this.info = info;
      channel.retarget(info.nasPeerId, randomId('b'));
      return info;
    } finally {
      for (const timer of retryTimers) clearTimeout(timer);
    }
  }

  // -------------------------------------------------------------------------
  // QR + Telegram authorisation
  // -------------------------------------------------------------------------

  /**
   * Announce a pending authorisation request. Carries only the SHA-256 of the
   * secret; the secret itself lives in the QR and never on this channel.
   *
   * Returns when the NAS has acknowledged, so the screen can show a real expiry
   * rather than one it guessed locally.
   */
  async registerAuth(requestId: string, secretHash: string): Promise<{ expiresAt: number }> {
    const info = await this.discover();
    const channel = await this.ensureChannel();

    const answered = channel.waitFor(
      (payload) => payload.type === 'auth-registered' && payload.requestId === requestId,
      AUTH_TIMEOUT_MS,
      'The NAS did not acknowledge the authorisation request',
    );

    await channel.send(
      {
        type: 'auth-register',
        requestId,
        secretHash,
        deviceName: deviceName(),
        platform: platformTag(),
      },
      info.nasPeerId,
    );

    const payload = await answered;
    if (payload.type !== 'auth-registered') {
      throw new TransportError('Malformed authorisation reply', 'io-error');
    }
    return { expiresAt: payload.expiresAt };
  }

  /**
   * The scanning device's single message: "I have the secret from this QR."
   *
   * Separate from `auth-register` so that merely loading the page cannot make
   * the owner's phone buzz — the notification is triggered by a deliberate scan
   * presenting a value only the QR contained.
   */
  async notifyAuth(requestId: string, secret: string): Promise<void> {
    const info = await this.discover();
    const channel = await this.ensureChannel();

    const answered = channel.waitFor(
      (payload) => payload.type === 'auth-notified' && payload.requestId === requestId,
      AUTH_TIMEOUT_MS,
      'The NAS did not acknowledge the scan',
    );

    await channel.send({ type: 'auth-notify', requestId, secret }, info.nasPeerId);
    await answered;
  }

  /** One poll. The NAS answers only to the peer id that registered. */
  async pollAuth(requestId: string): Promise<AuthPollResult> {
    const info = await this.discover();
    const channel = await this.ensureChannel();

    const answered = channel.waitFor(
      (payload) => payload.type === 'auth-status' && payload.requestId === requestId,
      AUTH_TIMEOUT_MS,
      'The NAS did not answer the authorisation poll',
    );

    await channel.send({ type: 'auth-poll', requestId }, info.nasPeerId);

    const payload = await answered;
    if (payload.type !== 'auth-status') {
      throw new TransportError('Malformed authorisation status', 'io-error');
    }
    // The NAS may address us by the id it just assigned; keep answering to both.
    if (payload.deviceId) channel.addSelfAlias(payload.deviceId);
    return {
      status: payload.status,
      ...(payload.token !== undefined ? { token: payload.token } : {}),
      ...(payload.deviceId !== undefined ? { deviceId: payload.deviceId } : {}),
      ...(payload.tokenExpiresAt !== undefined ? { tokenExpiresAt: payload.tokenExpiresAt } : {}),
      ...(payload.attemptsLeft !== undefined ? { attemptsLeft: payload.attemptsLeft } : {}),
      ...(payload.message !== undefined ? { message: payload.message } : {}),
    };
  }

  // -------------------------------------------------------------------------
  // bootstrap
  // -------------------------------------------------------------------------

  /**
   * The signaling-channel equivalent of `GET /api/bootstrap`: fetch ICE servers
   * and NAS metadata, shaped as the same `BootstrapResponse` the rest of the
   * client already understands.
   *
   * `signaling.ws` is deliberately empty — there is no reachable NAS WebSocket
   * in this mode, and `PeerLink` is handed the live Agora channel directly
   * rather than being asked to build one from this object.
   */
  async bootstrap(token: string, deviceId: string): Promise<BootstrapResponse> {
    const info = await this.discover();
    const channel = await this.ensureChannel();
    channel.addSelfAlias(deviceId);
    const requestId = randomId('t');

    const answered = channel.waitFor(
      (payload) => payload.type === 'bootstrap-response' && payload.requestId === requestId,
      BOOTSTRAP_TIMEOUT_MS,
      'The NAS did not answer the bootstrap request',
    );

    let payload: SignalPayload;
    try {
      await channel.send({ type: 'bootstrap-request', requestId, token }, info.nasPeerId);
      payload = await answered;
    } catch (error) {
      // Silence here usually means the cached `nasPeerId` is stale — the agent
      // restarted and came back under a new id. Drop it so the next attempt
      // re-broadcasts `discover` instead of retrying a dead address forever.
      this.info = null;
      throw error;
    }
    if (payload.type !== 'bootstrap-response') throw new TransportError('Malformed bootstrap reply', 'io-error');

    this.info = { ...info, nasName: payload.nasName, protocolVersion: payload.protocolVersion };

    return {
      nasName: payload.nasName,
      nasPeerId: info.nasPeerId,
      protocolVersion: payload.protocolVersion || PROTOCOL_VERSION,
      signaling: { ws: '' },
      iceServers: payload.iceServers,
    };
  }
}

/** Single instance, mirroring the `transport` singleton. */
export const standalone = new StandaloneSession();
