import { create } from 'zustand';

export type TransferStatus =
  | 'queued'
  | 'preparing' // streaming SHA-256
  | 'negotiating' // upload-init → upload-ready
  | 'uploading'
  | 'paused'
  | 'verifying' // bytes sent, waiting for the NAS checksum
  | 'done'
  | 'deduped' // the NAS already had this sha256
  | 'error'
  | 'cancelled';

export interface TransferRecord {
  id: string;
  seq: number;
  name: string;
  size: number;
  mime: string;
  status: TransferStatus;
  /** Bytes confirmed on the wire. */
  bytesDone: number;
  /** Bytes hashed so far, for the "preparing" bar. */
  hashedBytes: number;
  /** Smoothed bytes/second. */
  rate: number;
  etaMs: number | null;
  /** > 0 when an interrupted upload picked up where it left off. */
  resumedFromBytes: number;
  attempts: number;
  itemId: string | null;
  error: string | null;
  startedAt: number;
  finishedAt: number | null;
}

interface TransfersState {
  order: string[];
  byId: Record<string, TransferRecord>;
  add(record: TransferRecord): void;
  patch(id: string, patch: Partial<TransferRecord>): void;
  remove(id: string): void;
  clearFinished(): void;
}

export const ACTIVE_STATUSES: ReadonlySet<TransferStatus> = new Set<TransferStatus>([
  'queued',
  'preparing',
  'negotiating',
  'uploading',
  'paused',
  'verifying',
]);

export const useTransfers = create<TransfersState>((set) => ({
  order: [],
  byId: {},
  add: (record) =>
    set((state) => ({
      order: [record.id, ...state.order],
      byId: { ...state.byId, [record.id]: record },
    })),
  patch: (id, patch) =>
    set((state) => {
      const existing = state.byId[id];
      if (!existing) return state;
      return { byId: { ...state.byId, [id]: { ...existing, ...patch } } };
    }),
  remove: (id) =>
    set((state) => {
      const byId = { ...state.byId };
      delete byId[id];
      return { order: state.order.filter((x) => x !== id), byId };
    }),
  clearFinished: () =>
    set((state) => {
      const order = state.order.filter((id) => {
        const record = state.byId[id];
        return record ? ACTIVE_STATUSES.has(record.status) : false;
      });
      const byId: Record<string, TransferRecord> = {};
      for (const id of order) {
        const record = state.byId[id];
        if (record) byId[id] = record;
      }
      return { order, byId };
    }),
}));

export function selectActiveTransfers(state: TransfersState): TransferRecord[] {
  return state.order
    .map((id) => state.byId[id])
    .filter((record): record is TransferRecord => Boolean(record));
}
