import type { Item, TransportKind } from '@filedrop/shared';
import {
  TransportError,
  type ListParams,
  type ListResult,
  type TextKind,
  type Transport,
} from '../types';
import { BaseTransport } from './base';

/**
 * signal-relay — the last-ditch tier, deliberately left as a stub.
 *
 * Reached only when ICE fails on every candidate pair, i.e. no direct path and
 * no TURN. The full version would tunnel chunk frames as base64 over the
 * signaling channel, which is functional but slow enough (and expensive enough,
 * on a metered signaling provider) that shipping it invites people to use it by
 * accident. Instead the app enters a visibly degraded state and tells the user
 * what to fix: put the device back on the LAN, or configure TURN.
 *
 * The interface is fully implemented so the manager and UI need no special
 * cases; every data operation reports `unsupported` rather than pretending.
 */
export class SignalRelayTransport extends BaseTransport implements Transport {
  readonly kind: TransportKind = 'signal-relay';

  constructor(
    private readonly reason: string,
    /**
     * What the user can actually do about it. Differs by deployment: a
     * NAS-hosted page can suggest rejoining the LAN, but a standalone page has
     * no HTTP path to the NAS under any circumstances, so only TURN helps.
     */
    private readonly advice = 'Connect to the same network as the NAS, or configure a TURN server.',
  ) {
    super();
  }

  async start(): Promise<void> {
    this.patchState({
      phase: 'degraded',
      kind: this.kind,
      signalingIdle: false,
      path: 'no ICE path',
      note: `Direct connection failed: ${this.reason}. Relay tunnelling is not enabled in this build. ${this.advice}`,
      error: null,
    });
  }

  stop(): void {
    this.patchState({ phase: 'idle' });
  }

  private unsupported(): never {
    throw new TransportError(
      'No usable path to the NAS. Rejoin the NAS network or configure TURN.',
      'unsupported',
    );
  }

  list(_params: ListParams): Promise<ListResult> {
    return Promise.resolve({ items: [], nextCursor: null });
  }

  postText(_text: string, _kind: TextKind, _clientId: string): Promise<Item> {
    return this.unsupported();
  }

  remove(_itemId: string): Promise<void> {
    return this.unsupported();
  }

  uploadFile(): Promise<Item> {
    return this.unsupported();
  }

  mediaUrl(): string | null {
    return null;
  }

  fetchItemBlob(): Promise<Blob> {
    return this.unsupported();
  }
}
