import { AUTH_FRAGMENT_KEY, buildAuthUrl } from '@filedrop/shared';
import { randomId } from '../lib/ids';
import { sha256Text } from './hash';

/**
 * The waiting device's half of the QR + Telegram authorisation flow: minting a
 * request, and turning it into a URL a phone camera can act on.
 *
 * SECRET / HASH SPLIT. Two values are generated here and they travel by
 * different routes on purpose:
 *
 *   secret      goes into the QR only. It never touches the signaling channel
 *               from this device.
 *   sha256hex   goes to the NAS in `auth-register`.
 *
 * The signaling channel is a third party (Agora) and may be observable, so
 * anything sent over it should be assumed public. Registering only the digest
 * means an observer sees a value they cannot invert, and cannot forge the
 * `auth-notify` that fires the owner's Telegram message. Conversely the secret
 * is worthless on its own: the NAS only ever hands the granted token back to
 * the peer id that registered the request, so lifting the secret off a screen
 * buys an attacker one notification the owner will reject, and nothing else.
 */

/**
 * 32 bytes of entropy, base64url. Long enough that guessing is hopeless, short
 * enough (43 chars) to keep the QR at version ~6 where the modules stay chunky
 * on a phone screen.
 *
 * `crypto.getRandomValues` — unlike `crypto.subtle` — is available on plain
 * HTTP, so this works in the NAS-hosted deployment too.
 */
function mintSecret(): string {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export interface AuthRequestSeed {
  requestId: string;
  secret: string;
  /** SHA-256 of `secret`, lowercase hex — the only half the NAS is told. */
  secretHash: string;
  /** What the QR encodes, and what is shown as selectable text underneath. */
  url: string;
}

/**
 * Where a scanning device should be sent.
 *
 * **This page's own origin, never the NAS's.** The entire premise of the
 * standalone build is that a device off the LAN cannot reach the NAS over
 * HTTP — an `https://` page may not even try. But it can always reach wherever
 * this page is hosted, because it is currently loading it. `BASE_URL` is
 * respected so a GitHub Pages project subpath (`/filedrop/`) survives; without
 * it the QR would point at the domain root and 404.
 */
export function authOrigin(): string {
  const base = import.meta.env.BASE_URL || '/';
  const path = base.startsWith('/') ? base : `/${base}`;
  return `${window.location.origin}${path.endsWith('/') ? path : `${path}/`}`;
}

export async function mintAuthRequest(): Promise<AuthRequestSeed> {
  const requestId = randomId('a');
  const secret = mintSecret();
  const secretHash = await sha256Text(secret);
  return { requestId, secret, secretHash, url: buildAuthUrl(authOrigin(), requestId, secret) };
}

/**
 * Take the auth fragment out of the address bar once it has been read.
 *
 * The secret is a one-shot credential; leaving it in `location.hash` means it
 * survives into the browser's history UI, into screenshots, and into whatever
 * syncs open tabs between a user's devices. Mirrors what
 * `adoptConfigFromFragment()` does for the App ID.
 */
export function scrubAuthFragment(): void {
  const raw = window.location.hash.replace(/^#/, '');
  if (!raw) return;
  let params: URLSearchParams;
  try {
    params = new URLSearchParams(raw);
  } catch {
    return;
  }
  if (!params.has(AUTH_FRAGMENT_KEY)) return;
  params.delete(AUTH_FRAGMENT_KEY);
  const remainder = params.toString();
  window.history.replaceState(
    null,
    '',
    window.location.pathname + window.location.search + (remainder ? `#${remainder}` : ''),
  );
}
