import {
  BUFFER_LOW_WATER,
  CHUNK_HEADER_BYTES,
  CHUNK_SIZE,
  decodeChunk,
  encodeChunk,
  type BootstrapResponse,
  type ControlMessage,
  type DecodedChunk,
  type SignalPayload,
  type TransportKind,
} from '@filedrop/shared';
import { deviceName, platformTag } from '../lib/ids';
import { createSignalingChannel, type SignalingChannel } from './signaling';
import type { DeviceSession } from './session';
import type { ChunkSink } from './chunkPump';
import { TransportError } from './types';

const NEGOTIATION_TIMEOUT_MS = 25_000;
const PING_INTERVAL_MS = 5_000;

export interface PeerLinkEvents {
  onControl(message: ControlMessage): void;
  onChunk(chunk: DecodedChunk): void;
  /** Fired when ICE settles, so the UI can show host / srflx / relay. */
  onPathResolved(kind: TransportKind, path: string): void;
  onRtt(rttMs: number): void;
  onClosed(reason: string): void;
}

export interface PeerLinkOptions extends PeerLinkEvents {
  bootstrap: BootstrapResponse;
  session: DeviceSession;
  /** True when the NAS HTTP API is unreachable, so signaling must go via Agora. */
  preferAgora: boolean;
  sessionId: string;
  /**
   * An already-connected channel to negotiate on, instead of building one.
   *
   * Standalone mode discovers, pairs and bootstraps over a long-lived Agora
   * connection; logging in again here would cost a round trip on every
   * reconnect and briefly put two peers with the same id on the channel. The
   * caller owns it — `close()` on such a channel only detaches us.
   */
  signaling?: SignalingChannel;
}

interface ControlWaiter {
  match: (message: ControlMessage) => boolean;
  resolve: (message: ControlMessage) => void;
  reject: (error: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

/**
 * One WebRTC peer connection to the NAS, plus the DataChannel that carries all
 * real traffic. The browser is always the offerer: the NAS runs headless and
 * only ever answers, which keeps glare impossible — there is exactly one
 * offerer per link, so we never need rollback.
 */
export class PeerLink implements ChunkSink {
  private pc: RTCPeerConnection | null = null;
  private dc: RTCDataChannel | null = null;
  private signaling: SignalingChannel | null = null;
  private readonly pendingRemoteCandidates: RTCIceCandidateInit[] = [];
  private remoteDescriptionSet = false;
  private readonly waiters = new Set<ControlWaiter>();
  private drainWaiters: Array<() => void> = [];
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private closed = false;
  private kindResolved: TransportKind = 'p2p-srflx';

  constructor(private readonly options: PeerLinkOptions) {}

  /** True once the handshake is done and the signaling channel can go quiet. */
  signalingIdle = false;

  get transportKind(): TransportKind {
    return this.kindResolved;
  }

  // -------------------------------------------------------------------------
  // Lifecycle
  // -------------------------------------------------------------------------

  async open(): Promise<Extract<ControlMessage, { type: 'ready' }>> {
    const { bootstrap, session, sessionId } = this.options;

    const signaling =
      this.options.signaling ??
      createSignalingChannel(
        { selfId: session.deviceId, peerId: session.nasPeerId, session: sessionId },
        bootstrap,
        this.options.preferAgora,
      );
    // A handed-over channel was last aimed at whatever discovery/pairing used;
    // point it at this negotiation. A freshly built one is already correct.
    signaling.retarget?.(session.nasPeerId, sessionId);
    this.signaling = signaling;
    signaling.onEnvelope = (envelope) => void this.handleSignal(envelope.payload);
    signaling.onClosed = (reason) => {
      // Losing signaling *after* the DataChannel is up is harmless — that is
      // the design. Only complain if we are still negotiating.
      if (!this.signalingIdle) this.fail(`signaling closed: ${reason}`);
    };

    await signaling.connect();

    const helloAck = this.waitForSignal(
      (payload) => payload.type === 'hello-ack' || payload.type === 'hello-reject',
      NEGOTIATION_TIMEOUT_MS,
    );
    await signaling.send({
      type: 'hello',
      role: 'device',
      deviceName: deviceName(),
      platform: platformTag(),
      token: session.token,
    });
    const ack = await helloAck;
    if (ack.type === 'hello-reject') {
      throw new TransportError(
        ack.reason === 'busy' ? 'The NAS is busy with another device' : 'This device is no longer paired',
        ack.reason === 'busy' ? 'io-error' : 'unauthorized',
      );
    }

    const pc = new RTCPeerConnection({
      iceServers: bootstrap.iceServers as RTCIceServer[],
      // "all" so we still get a relay candidate if hole-punching fails; the
      // candidate-pair inspection below tells the user which one actually won.
      iceTransportPolicy: 'all',
      bundlePolicy: 'max-bundle',
    });
    this.pc = pc;

    pc.addEventListener('icecandidate', (event) => {
      if (this.closed) return;
      const payload: SignalPayload = event.candidate
        ? {
            type: 'ice',
            candidate: event.candidate.candidate,
            sdpMid: event.candidate.sdpMid,
            sdpMLineIndex: event.candidate.sdpMLineIndex,
          }
        : { type: 'ice-complete' };
      void signaling.send(payload).catch(() => undefined);
    });
    pc.addEventListener('connectionstatechange', () => {
      if (pc.connectionState === 'failed') this.fail('peer connection failed');
      if (pc.connectionState === 'disconnected') this.fail('peer connection dropped');
    });

    // Ordered + reliable: chunk indices are explicit in the frame header, but
    // relying on ordering lets the NAS append sequentially without a sparse map.
    const dc = pc.createDataChannel('filedrop', { ordered: true });
    dc.binaryType = 'arraybuffer';
    dc.bufferedAmountLowThreshold = BUFFER_LOW_WATER;
    this.dc = dc;

    dc.addEventListener('bufferedamountlow', () => this.releaseDrainWaiters());
    dc.addEventListener('close', () => this.fail('data channel closed'));
    dc.addEventListener('error', () => this.fail('data channel error'));
    dc.addEventListener('message', (event) => this.handleData(event.data));

    const opened = new Promise<void>((resolve, reject) => {
      const timer = setTimeout(
        () => reject(new TransportError('Timed out establishing a direct connection', 'unreachable')),
        NEGOTIATION_TIMEOUT_MS,
      );
      dc.addEventListener('open', () => {
        clearTimeout(timer);
        resolve();
      });
      pc.addEventListener('iceconnectionstatechange', () => {
        if (pc.iceConnectionState === 'failed') {
          clearTimeout(timer);
          reject(new TransportError('ICE failed — no path to the NAS', 'unreachable'));
        }
      });
    });

    const answer = this.waitForSignal((payload) => payload.type === 'answer', NEGOTIATION_TIMEOUT_MS);
    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);
    await signaling.send({ type: 'offer', sdp: offer.sdp ?? '' });

    const answerPayload = await answer;
    if (answerPayload.type !== 'answer') throw new TransportError('Malformed answer', 'io-error');
    await pc.setRemoteDescription({ type: 'answer', sdp: answerPayload.sdp });
    this.remoteDescriptionSet = true;
    for (const candidate of this.pendingRemoteCandidates.splice(0)) {
      await pc.addIceCandidate(candidate).catch(() => undefined);
    }

    await opened;

    const ready = (await this.waitForControl(
      (message) => message.type === 'ready',
      NEGOTIATION_TIMEOUT_MS,
    )) as Extract<ControlMessage, { type: 'ready' }>;

    // From here on, no more signaling traffic. Park the channel and say so.
    this.signalingIdle = true;
    void this.resolvePath();
    this.startPinging();
    return ready;
  }

  close(reason = 'closed by client'): void {
    if (this.closed) return;
    this.closed = true;
    if (this.pingTimer) clearInterval(this.pingTimer);
    this.pingTimer = null;
    for (const waiter of this.waiters) {
      clearTimeout(waiter.timer);
      waiter.reject(new TransportError(reason, 'unreachable'));
    }
    this.waiters.clear();
    this.releaseDrainWaiters();
    if (this.signaling) {
      void this.signaling.send({ type: 'bye', reason }).catch(() => undefined);
      this.signaling.close();
      this.signaling = null;
    }
    this.dc?.close();
    this.pc?.close();
    this.dc = null;
    this.pc = null;
  }

  private fail(reason: string): void {
    if (this.closed) return;
    const notify = this.options.onClosed;
    this.close(reason);
    notify(reason);
  }

  // -------------------------------------------------------------------------
  // Signaling
  // -------------------------------------------------------------------------

  private signalWaiters = new Set<{
    match: (payload: SignalPayload) => boolean;
    resolve: (payload: SignalPayload) => void;
    reject: (error: Error) => void;
    timer: ReturnType<typeof setTimeout>;
  }>();

  private waitForSignal(
    match: (payload: SignalPayload) => boolean,
    timeoutMs: number,
  ): Promise<SignalPayload> {
    return new Promise((resolve, reject) => {
      const waiter = {
        match,
        resolve,
        reject,
        timer: setTimeout(() => {
          this.signalWaiters.delete(waiter);
          reject(new TransportError('The NAS did not answer the handshake', 'unreachable'));
        }, timeoutMs),
      };
      this.signalWaiters.add(waiter);
    });
  }

  private async handleSignal(payload: SignalPayload): Promise<void> {
    if (payload.type === 'ice' && this.pc) {
      const candidate: RTCIceCandidateInit = {
        candidate: payload.candidate,
        sdpMid: payload.sdpMid,
        sdpMLineIndex: payload.sdpMLineIndex,
      };
      // Candidates can arrive before the answer; addIceCandidate would throw.
      if (this.remoteDescriptionSet) {
        await this.pc.addIceCandidate(candidate).catch(() => undefined);
      } else {
        this.pendingRemoteCandidates.push(candidate);
      }
      return;
    }
    if (payload.type === 'bye') {
      this.fail(payload.reason || 'peer said bye');
      return;
    }
    for (const waiter of this.signalWaiters) {
      if (waiter.match(payload)) {
        clearTimeout(waiter.timer);
        this.signalWaiters.delete(waiter);
        waiter.resolve(payload);
      }
    }
  }

  // -------------------------------------------------------------------------
  // Data channel
  // -------------------------------------------------------------------------

  private handleData(data: unknown): void {
    if (typeof data === 'string') {
      let message: ControlMessage;
      try {
        message = JSON.parse(data) as ControlMessage;
      } catch {
        return;
      }
      if (message.type === 'ping') {
        this.sendControl({ type: 'pong', nonce: message.nonce });
        return;
      }
      for (const waiter of [...this.waiters]) {
        if (waiter.match(message)) {
          clearTimeout(waiter.timer);
          this.waiters.delete(waiter);
          waiter.resolve(message);
        }
      }
      this.options.onControl(message);
      return;
    }
    if (data instanceof ArrayBuffer) {
      const chunk = decodeChunk(data);
      if (chunk) this.options.onChunk(chunk);
    }
  }

  sendControl(message: ControlMessage): void {
    if (!this.dc || this.dc.readyState !== 'open') {
      throw new TransportError('Data channel is not open', 'unreachable');
    }
    this.dc.send(JSON.stringify(message));
  }

  waitForControl(
    match: (message: ControlMessage) => boolean,
    timeoutMs = 30_000,
  ): Promise<ControlMessage> {
    return new Promise((resolve, reject) => {
      const waiter: ControlWaiter = {
        match,
        resolve,
        reject,
        timer: setTimeout(() => {
          this.waiters.delete(waiter);
          reject(new TransportError('The NAS stopped responding', 'unreachable'));
        }, timeoutMs),
      };
      this.waiters.add(waiter);
    });
  }

  // --- ChunkSink -----------------------------------------------------------

  send(chunkIndex: number, payload: Uint8Array): void {
    if (!this.dc || this.dc.readyState !== 'open') {
      throw new TransportError('Data channel closed mid-transfer', 'unreachable');
    }
    if (payload.byteLength > CHUNK_SIZE) {
      throw new TransportError('Chunk exceeds CHUNK_SIZE', 'io-error');
    }
    this.dc.send(encodeChunk(this.currentSeq, chunkIndex, payload));
  }

  /** Set by the transport before pumping; the frame header needs it. */
  currentSeq = 0;

  bufferedAmount(): number {
    return this.dc?.bufferedAmount ?? 0;
  }

  whenDrained(): Promise<void> {
    const dc = this.dc;
    if (!dc || dc.readyState !== 'open') return Promise.resolve();
    if (dc.bufferedAmount <= BUFFER_LOW_WATER) return Promise.resolve();
    return new Promise<void>((resolve) => {
      this.drainWaiters.push(resolve);
      // Safety net: some stacks have historically dropped bufferedamountlow.
      // Polling at 250 ms costs nothing and prevents a wedged transfer.
      const poll = setInterval(() => {
        if (!this.dc || this.dc.readyState !== 'open' || this.dc.bufferedAmount <= BUFFER_LOW_WATER) {
          clearInterval(poll);
          resolve();
        }
      }, 250);
    });
  }

  isOpen(): boolean {
    return !this.closed && this.dc?.readyState === 'open';
  }

  private releaseDrainWaiters(): void {
    const waiters = this.drainWaiters;
    this.drainWaiters = [];
    for (const w of waiters) w();
  }

  /** Frame overhead per chunk, used for throughput accounting. */
  static readonly frameOverhead = CHUNK_HEADER_BYTES;

  // -------------------------------------------------------------------------
  // Diagnostics
  // -------------------------------------------------------------------------

  private startPinging(): void {
    this.pingTimer = setInterval(() => {
      if (!this.isOpen()) return;
      const nonce = Math.floor(Math.random() * 0xffffffff);
      const sentAt = performance.now();
      this.waitForControl(
        (message) => message.type === 'pong' && message.nonce === nonce,
        PING_INTERVAL_MS * 3,
      )
        .then(() => this.options.onRtt(Math.round(performance.now() - sentAt)))
        .catch(() => undefined);
      try {
        this.sendControl({ type: 'ping', nonce });
      } catch {
        /* link is going away; connectionstatechange will handle it */
      }
    }, PING_INTERVAL_MS);
  }

  /**
   * Inspect the nominated ICE candidate pair to report the *honest* transport
   * tier. "P2P" through a TURN relay is still a relay, and the UI says so.
   */
  private async resolvePath(): Promise<void> {
    const pc = this.pc;
    if (!pc) return;
    try {
      const stats = await pc.getStats();
      let pair: RTCIceCandidatePairStats | null = null;
      stats.forEach((report) => {
        if (report.type === 'candidate-pair') {
          const candidatePair = report as RTCIceCandidatePairStats;
          if (candidatePair.state === 'succeeded' && candidatePair.nominated) pair = candidatePair;
        }
      });
      if (!pair) return;
      const selected = pair as RTCIceCandidatePairStats;
      const local = stats.get(selected.localCandidateId) as { candidateType?: string } | undefined;
      const remote = stats.get(selected.remoteCandidateId) as { candidateType?: string } | undefined;
      const localType = local?.candidateType ?? 'unknown';
      const remoteType = remote?.candidateType ?? 'unknown';

      const kind: TransportKind =
        localType === 'relay' || remoteType === 'relay' ? 'p2p-relay'
        : localType === 'host' && remoteType === 'host' ? 'p2p-host'
        : 'p2p-srflx';
      this.kindResolved = kind;
      this.options.onPathResolved(kind, `${localType} ↔ ${remoteType}`);
    } catch {
      /* stats are best-effort */
    }
  }
}
