import { useToasts } from '../state/toasts';
import { AlertIcon, CheckIcon, DownloadIcon, InboxIcon } from './Icons';

export function DropOverlay(): JSX.Element {
  return (
    <div className="drop" aria-hidden="true">
      <div className="drop__frame">
        <DownloadIcon />
        <div className="drop__title">Drop to send to your NAS</div>
        <div className="drop__hint">files never leave your network on the LAN tier</div>
      </div>
    </div>
  );
}

export function Toasts(): JSX.Element | null {
  const toasts = useToasts((state) => state.toasts);
  if (toasts.length === 0) return null;
  return (
    <div className="toasts" role="status" aria-live="polite">
      {toasts.map((item) => (
        <div className="toast" key={item.id} data-tone={item.tone}>
          {item.tone === 'ok' ? <CheckIcon /> : item.tone === 'error' ? <AlertIcon /> : <InboxIcon />}
          {item.message}
        </div>
      ))}
    </div>
  );
}
