import { isFileKind, type Item } from '@filedrop/shared';
import { useState } from 'react';
import { formatBytes, formatDuration } from '../../lib/format';
import { useMediaSource } from '../../hooks/useMediaSource';
import { DownloadIcon, ImageIcon, PlayIcon } from '../Icons';

interface MediaTileProps {
  item: Item;
  onOpen(item: Item): void;
}

/**
 * One cell of the gallery grid. Thumbnails come from the NAS on the LAN tier;
 * over P2P they are pulled through the DataChannel, so anything sizeable waits
 * for an explicit tap rather than silently spending mobile data.
 */
export function MediaTile({ item, onOpen }: MediaTileProps): JSX.Element {
  const media = useMediaSource(item, 'thumb');
  const [loaded, setLoaded] = useState(false);

  return (
    <button type="button" className="tile" onClick={() => onOpen(item)} aria-label={item.name ?? 'Media'}>
      {media.status === 'ready' ? (
        <img
          src={media.url}
          alt={item.name ?? ''}
          loading="lazy"
          decoding="async"
          data-loaded={loaded}
          onLoad={() => setLoaded(true)}
        />
      ) : null}

      {media.status !== 'ready' || !loaded ? (
        <span className="tile__fallback">
          {media.status === 'loading' ? (
            <span className="spinner" />
          ) : (
            <>
              <ImageIcon />
              {media.status === 'needs-fetch' ? 'tap to load' : formatBytes(item.size)}
            </>
          )}
        </span>
      ) : null}

      {item.kind === 'video' ? (
        <span className="tile__badge">
          <PlayIcon />
          {item.durationMs ? formatDuration(item.durationMs) : 'video'}
        </span>
      ) : null}
    </button>
  );
}

interface GalleryProps {
  items: Item[];
  onOpen(item: Item): void;
}

export function Gallery({ items, onOpen }: GalleryProps): JSX.Element {
  return (
    <div className={`gallery${items.length === 1 ? ' gallery--single' : ''}`}>
      {items.map((item) => (
        <MediaTile key={item.id} item={item} onOpen={onOpen} />
      ))}
    </div>
  );
}

/** Non-previewable file: icon, name, size, download. */
export function FileCard({ item, onDownload }: { item: Item; onDownload(item: Item): void }): JSX.Element {
  const extension = (item.name?.split('.').pop() ?? '').toUpperCase().slice(0, 4);
  return (
    <div className="card file-card">
      <span className="file-card__glyph">
        {extension ? <span className="file-card__ext">{extension}</span> : <ImageIcon />}
      </span>
      <span className="file-card__body">
        <span className="file-card__name">{item.name ?? 'file'}</span>
        <span className="file-card__sub">
          {formatBytes(item.size)}
          {item.sha256 ? ` · ${item.sha256.slice(0, 10)}` : ''}
        </span>
      </span>
      <button
        type="button"
        className="icon-btn"
        onClick={() => onDownload(item)}
        aria-label={`Download ${item.name ?? 'file'}`}
        disabled={!isFileKind(item.kind)}
      >
        <DownloadIcon />
      </button>
    </div>
  );
}
