import { isFileKind, type Item } from '@filedrop/shared';
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { copyToClipboard } from '../hooks/useIngest';
import { useLongPress } from '../hooks/useLongPress';
import { dayKey, formatClock, formatDayLabel } from '../lib/format';
import { useAuth } from '../state/auth';
import { useItems } from '../state/items';
import { AlertIcon, CopyIcon, DownloadIcon, InboxIcon, TrashIcon } from './Icons';
import { FileCard, Gallery } from './items/MediaTile';
import { TextCard } from './items/TextCard';

/**
 * A run of items that render as one block. Consecutive images/videos collapse
 * into a single gallery grid so a 12-photo dump does not produce 12 cards.
 */
interface Group {
  key: string;
  items: Item[];
  gallery: boolean;
}

interface DaySection {
  key: string;
  label: string;
  timestamp: number;
  groups: Group[];
}

/** `items` must already be oldest → newest. */
function buildSections(items: Item[]): DaySection[] {
  const sections: DaySection[] = [];
  for (const item of items) {
    const key = dayKey(item.createdAt);
    let section = sections[sections.length - 1];
    if (!section || section.key !== key) {
      section = { key, label: formatDayLabel(item.createdAt), timestamp: item.createdAt, groups: [] };
      sections.push(section);
    }
    const isMedia = item.kind === 'image' || item.kind === 'video';
    const last = section.groups[section.groups.length - 1];
    if (isMedia && last?.gallery) {
      last.items.push(item);
    } else {
      section.groups.push({ key: item.id, items: [item], gallery: isMedia });
    }
  }
  return sections;
}

interface TimelineProps {
  onOpenMedia(item: Item, siblings: Item[]): void;
  onDownload(item: Item): void;
}

export function Timeline({ onOpenMedia, onDownload }: TimelineProps): JSX.Element {
  const {
    items,
    loading,
    loadingMore,
    nextCursor,
    error,
    query,
    loadMore,
    refresh,
    bootEpoch,
  } = useItems();
  const scrollRef = useRef<HTMLDivElement>(null);
  const topSentinel = useRef<HTMLDivElement>(null);
  const stickBottom = useRef(true);
  const prevLen = useRef(0);
  const sections = useMemo(() => buildSections(items), [items]);

  // Chat-style: load older history when the user scrolls near the top.
  useEffect(() => {
    const node = topSentinel.current;
    const root = scrollRef.current;
    if (!node || !nextCursor || !root) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) void loadMore();
      },
      { root, rootMargin: '200px 0px 0px 0px' },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [nextCursor, loadMore, items.length]);

  // Track whether the user is pinned near the bottom (for auto-scroll on new msgs).
  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const onScroll = (): void => {
      const distance = el.scrollHeight - el.scrollTop - el.clientHeight;
      stickBottom.current = distance < 80;
    };
    el.addEventListener('scroll', onScroll, { passive: true });
    return () => el.removeEventListener('scroll', onScroll);
  }, []);

  // After first page (or query refresh), jump to latest message.
  useLayoutEffect(() => {
    const el = scrollRef.current;
    if (!el || loading || items.length === 0) return;
    el.scrollTop = el.scrollHeight;
    stickBottom.current = true;
    prevLen.current = items.length;
  }, [bootEpoch, loading]);

  // New items while pinned to bottom → keep following the latest.
  useLayoutEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    if (items.length > prevLen.current && stickBottom.current) {
      el.scrollTop = el.scrollHeight;
    }
    // When loading older at top, preserve scroll position roughly by height delta.
    if (items.length > prevLen.current && !stickBottom.current && loadingMore === false) {
      // no-op: browser keeps anchor if content prepended carefully; we accept small jump
    }
    prevLen.current = items.length;
  }, [items.length, loadingMore]);

  if (loading && items.length === 0) {
    return (
      <div className="timeline" ref={scrollRef}>
        {[0, 1, 2, 3].map((index) => (
          <div className="skeleton" key={index} />
        ))}
      </div>
    );
  }

  if (error && items.length === 0) {
    return (
      <div className="timeline" ref={scrollRef}>
        <div className="state state--error">
          <div className="state__grid">
            <AlertIcon />
          </div>
          <h2>无法连接 NAS</h2>
          <p>{error}</p>
          <button type="button" className="btn" onClick={() => void refresh()}>
            重试
          </button>
        </div>
      </div>
    );
  }

  if (items.length === 0) {
    return (
      <div className="timeline" ref={scrollRef}>
        <div className="state">
          <div className="state__grid">
            <InboxIcon />
          </div>
          <h2>{query ? '没有匹配结果' : '还没有内容'}</h2>
          <p>
            {query ?
              '换个关键词，或清空搜索查看全部。'
            : <>
                把文件拖进窗口，或按 <kbd>⌘V</kbd> / <kbd>Ctrl+V</kbd> 粘贴，也可在下方输入文字。
                内容会保存在你自己的 NAS 上。
              </>
            }
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="timeline" ref={scrollRef}>
      {loadingMore ? <p className="timeline__more">加载更早的消息…</p> : null}
      {!nextCursor && items.length > 12 ?
        <p className="timeline__more">已到最早记录</p>
      : null}
      <div ref={topSentinel} className="timeline__sentinel" />

      {sections.map((section) => (
        <section className="day" key={section.key}>
          <div className="day__label">
            <span>{section.label}</span>
          </div>
          {section.groups.map((group) => (
            <TimelineEntry
              key={group.key}
              group={group}
              onOpenMedia={onOpenMedia}
              onDownload={onDownload}
            />
          ))}
        </section>
      ))}
    </div>
  );
}

function isMine(item: Item, myDeviceId: string | undefined): boolean {
  if (item.originDeviceId === 'self') return true;
  if (myDeviceId && item.originDeviceId === myDeviceId) return true;
  return false;
}

function TimelineEntry({
  group,
  onOpenMedia,
  onDownload,
}: {
  group: Group;
  onOpenMedia(item: Item, siblings: Item[]): void;
  onDownload(item: Item): void;
}): JSX.Element {
  const remove = useItems((state) => state.remove);
  const fresh = useItems((state) => state.fresh);
  const myDeviceId = useAuth((state) => state.session?.deviceId);
  const [menuOpen, setMenuOpen] = useState(false);
  const press = useLongPress(() => setMenuOpen(true));

  const head = group.items[0] as Item;
  const isFresh = fresh.has(head.id);
  const single = group.items.length === 1;
  const mine = isMine(head, myDeviceId);

  return (
    <div
      className={`entry${isFresh ? ' entry--fresh' : ''}${mine ? ' entry--mine' : ' entry--theirs'}`}
      style={{ position: 'relative' }}
      onPointerDown={press.onPointerDown}
      onPointerUp={press.onPointerUp}
      onPointerMove={press.onPointerMove}
      onPointerCancel={press.onPointerCancel}
      onContextMenu={press.onContextMenu}
      onMouseLeave={() => setMenuOpen(false)}
    >
      <div className="entry__meta">
        {!mine ? <span className="entry__origin">{head.originDeviceName}</span> : null}
        <span className="entry__time">{formatClock(head.createdAt)}</span>
        {mine ? <span className="entry__origin">我</span> : null}
      </div>

      <div className="entry__bubble">
        {group.gallery ? (
          <Gallery items={group.items} onOpen={(item) => onOpenMedia(item, group.items)} />
        ) : head.kind === 'file' || head.kind === 'audio' ? (
          <FileCard item={head} onDownload={onDownload} />
        ) : (
          <TextCard item={head} />
        )}

        {single ? (
          <div className="entry__menu" data-open={menuOpen}>
            {head.text ? (
              <button
                type="button"
                onClick={() => void copyToClipboard(head.text ?? '')}
                aria-label="复制"
                title="复制"
              >
                <CopyIcon />
              </button>
            ) : null}
            {isFileKind(head.kind) ? (
              <button
                type="button"
                onClick={() => onDownload(head)}
                aria-label="下载"
                title="下载"
              >
                <DownloadIcon />
              </button>
            ) : null}
            <button
              type="button"
              data-danger="true"
              onClick={() => void remove(head.id)}
              aria-label="删除"
              title="删除"
            >
              <TrashIcon />
            </button>
          </div>
        ) : null}
      </div>
    </div>
  );
}
