import type { BootstrapResponse, Item, TransportKind } from '@filedrop/shared';
import * as api from './api';
import { isStandalone } from './mode';
import { loadCachedBootstrap, saveBootstrap, type DeviceSession } from './session';
import { standalone } from './standalone';
import { LanTransport } from './transports/lan';
import { P2pTransport } from './transports/p2p';
import { SignalRelayTransport } from './transports/relay';
import {
  INITIAL_CONNECTION_STATE,
  TransportError,
  type ConnectionState,
  type ListParams,
  type ListResult,
  type TextKind,
  type Transport,
  type TransportEvent,
  type UploadContext,
} from './types';

/** How often we re-probe for the NAS while running on a lower tier. */
const UPGRADE_PROBE_MS = 20_000;
const RECONNECT_BASE_MS = 1_000;
const RECONNECT_MAX_MS = 20_000;

/**
 * Picks and owns the active transport tier, and keeps the UI pointed at one
 * stable object across tier changes.
 *
 * Selection order, cheapest first:
 *
 *   1. `lan-direct` — a 1.5 s probe of GET /api/health. If the NAS answers we
 *      are on its network and plain TCP beats everything else; there is no
 *      handshake to pay for and no reason to involve WebRTC.
 *   2. `p2p`        — the NAS is not reachable (mobile data, foreign wifi).
 *      Signaling sets up a DataChannel, then gets out of the way.
 *   3. `signal-relay` — ICE found no path at all. Degraded stub; see relay.ts.
 *
 * The probe result also decides *which* signaling channel P2P uses: if the NAS
 * HTTP API is unreachable then its WebSocket is too, so Agora carries the
 * handshake. Otherwise (rare: HTTP up but we chose P2P after a LAN failure) the
 * NAS's own socket does the job and no third party is involved.
 *
 * **Standalone mode collapses all of that to one tier.** When the page is not
 * served by the NAS (GitHub Pages), an `https://` origin may not issue a single
 * request to `http://<nas>` — mixed content, blocked with no override. So there
 * is no probe, no `lan-direct`, and no upgrade watch: doing any of those would
 * mean an HTTP call we know is forbidden. P2P is the only tier, its bootstrap
 * comes over the signaling channel, and if ICE fails we drop to the degraded
 * tier and say so plainly rather than pretending a LAN path exists.
 */
export class TransportManager {
  private active: Transport | null = null;
  private session: DeviceSession | null = null;
  private state: ConnectionState = { ...INITIAL_CONNECTION_STATE };
  private stateListeners = new Set<(state: ConnectionState) => void>();
  private eventListeners = new Set<(event: TransportEvent) => void>();
  private rejectionListeners = new Set<(message: string) => void>();
  private unsubscribeActive: Array<() => void> = [];
  private upgradeTimer: ReturnType<typeof setInterval> | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private reconnectAttempt = 0;
  private starting: Promise<void> | null = null;
  /** Non-zero while transfers are running: never switch tiers underneath them. */
  private busy = 0;
  private disposed = false;

  // -------------------------------------------------------------------------
  // Public surface
  // -------------------------------------------------------------------------

  getState(): ConnectionState {
    return this.state;
  }

  subscribeState(fn: (state: ConnectionState) => void): () => void {
    this.stateListeners.add(fn);
    fn(this.state);
    return () => this.stateListeners.delete(fn);
  }

  subscribeEvents(fn: (event: TransportEvent) => void): () => void {
    this.eventListeners.add(fn);
    return () => this.eventListeners.delete(fn);
  }

  /**
   * The NAS refused our credentials outright.
   *
   * Distinct from "offline": there is nothing to retry and no amount of waiting
   * fixes it, so the auth layer has to drop the session rather than let the
   * connection card sit there reconnecting forever. Tokens are hard-expiry, so
   * on a long-lived tab this is the *expected* end of a session, not an error.
   */
  onRejected(fn: (message: string) => void): () => void {
    this.rejectionListeners.add(fn);
    return () => this.rejectionListeners.delete(fn);
  }

  private emitRejected(message: string): void {
    for (const fn of [...this.rejectionListeners]) fn(message);
  }

  get kind(): TransportKind | null {
    return this.state.kind;
  }

  get isReady(): boolean {
    return this.state.phase === 'online' || this.state.phase === 'degraded';
  }

  /** Marks a transfer as in flight so tier switching is suspended. */
  acquireBusy(): () => void {
    this.busy += 1;
    let released = false;
    return () => {
      if (released) return;
      released = true;
      this.busy = Math.max(0, this.busy - 1);
    };
  }

  async start(session: DeviceSession): Promise<void> {
    this.session = session;
    this.disposed = false;
    api.setAuthToken(session.token);
    await this.select();
    this.startUpgradeProbe();
  }

  /** User-initiated: tear down whatever we have and re-run selection. */
  async reconnect(): Promise<void> {
    this.teardownActive();
    this.reconnectAttempt = 0;
    await this.select();
  }

  stop(): void {
    this.disposed = true;
    if (this.upgradeTimer) clearInterval(this.upgradeTimer);
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.upgradeTimer = null;
    this.reconnectTimer = null;
    this.teardownActive();
    this.session = null;
    this.patch({ ...INITIAL_CONNECTION_STATE });
  }

  private require(): Transport {
    if (!this.active) throw new TransportError('Not connected to the NAS yet', 'unreachable');
    return this.active;
  }

  list(params: ListParams): Promise<ListResult> {
    return this.require().list(params);
  }

  postText(text: string, kind: TextKind, clientId: string): Promise<Item> {
    return this.require().postText(text, kind, clientId);
  }

  remove(itemId: string): Promise<void> {
    return this.require().remove(itemId);
  }

  uploadFile(ctx: UploadContext): Promise<Item> {
    return this.require().uploadFile(ctx);
  }

  mediaUrl(item: Item, variant: 'raw' | 'thumb'): string | null {
    return this.active?.mediaUrl(item, variant) ?? null;
  }

  fetchItemBlob(item: Item, onProgress?: (bytes: number) => void): Promise<Blob> {
    return this.require().fetchItemBlob(item, onProgress);
  }

  // -------------------------------------------------------------------------
  // Tier selection
  // -------------------------------------------------------------------------

  private async select(): Promise<void> {
    if (this.starting) return this.starting;
    const run = this.doSelect();
    this.starting = run.finally(() => {
      this.starting = null;
    });
    return this.starting;
  }

  private async doSelect(): Promise<void> {
    const session = this.session;
    if (!session || this.disposed) return;

    // A failed tier arms the reconnect timer on its way out; cancel it so a
    // successful re-selection is not immediately torn down and redone.
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.reconnectTimer = null;

    if (isStandalone()) {
      await this.selectStandalone(session);
      return;
    }

    this.patch({ phase: 'probing', note: 'Looking for the NAS…', error: null });
    const health = await api.probeHealth(1500);

    if (health) {
      const lan = new LanTransport();
      try {
        await this.adopt(lan);
        this.reconnectAttempt = 0;
        // Refresh the bootstrap cache while we can reach the NAS, so the P2P
        // tier still has credentials later when we cannot.
        void api
          .bootstrap()
          .then(saveBootstrap)
          .catch(() => undefined);
        return;
      } catch {
        lan.stop();
      }
    }

    const bootstrap = await this.resolveBootstrap(Boolean(health));
    if (!bootstrap) {
      this.patch({
        phase: 'offline',
        kind: null,
        error: 'Cannot reach the NAS, and no cached connection details are stored on this device.',
        note: null,
      });
      this.scheduleReconnect();
      return;
    }

    const p2p = new P2pTransport(bootstrap, session, !health);
    try {
      await this.adopt(p2p);
      this.reconnectAttempt = 0;
      return;
    } catch (error) {
      p2p.stop();
      const message = error instanceof Error ? error.message : String(error);
      if (error instanceof TransportError && error.code === 'unauthorized') {
        this.patch({ phase: 'offline', error: message, kind: null });
        this.emitRejected(message);
        return;
      }
      // ICE gave up: fall to the degraded tier so the UI can explain itself
      // instead of silently spinning.
      const relay = new SignalRelayTransport(message);
      await this.adopt(relay);
      this.scheduleReconnect();
    }
  }

  /**
   * Standalone selection.
   *
   * 1. If this page is plain HTTP and a local/LAN agent answers on :8420 (or
   *    `localStorage.filedrop.agentOrigin`), use lan-direct. That covers
   *    "agent in Podman on this Mac + web on :8421" where WebRTC ICE usually
   *    fails through the VM network.
   * 2. Else signaling bootstrap → WebRTC (true remote / HTTPS Pages case).
   * 3. Else degraded + explain TURN / open NAS-hosted UI.
   */
  private async selectStandalone(session: DeviceSession): Promise<void> {
    this.patch({ phase: 'probing', note: 'Looking for your NAS…', error: null });

    // Prefer HTTP when reachable (no mixed-content issue on http→http).
    const local = await api.findReachableAgentOrigin(1200);
    if (local) {
      api.setApiOrigin(local.origin);
      const lan = new LanTransport();
      try {
        await this.adopt(lan);
        this.reconnectAttempt = 0;
        void api
          .bootstrap()
          .then(saveBootstrap)
          .catch(() => undefined);
        this.patch({
          note: `HTTP · ${local.origin.replace(/^https?:\/\//, '')}`,
        });
        return;
      } catch {
        lan.stop();
        api.setApiOrigin(null);
      }
    } else {
      api.setApiOrigin(null);
    }

    this.patch({
      phase: 'probing',
      note: 'Looking for your NAS on the signaling channel…',
      error: null,
    });

    let bootstrap: BootstrapResponse;
    try {
      bootstrap = await standalone.bootstrap(session.token, session.deviceId);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.patch({
        phase: 'offline',
        kind: null,
        note: null,
        error: `${message}. The NAS may be offline, or this browser may be pointed at the wrong Agora channel.`,
      });
      this.scheduleReconnect();
      return;
    }

    // Keep the stored peer id fresh — the agent can come back with a new one.
    if (bootstrap.nasPeerId && bootstrap.nasPeerId !== session.nasPeerId) {
      this.session = { ...session, nasPeerId: bootstrap.nasPeerId };
      session = this.session;
    }

    const p2p = new P2pTransport(bootstrap, session, true, standalone.signalingChannel());
    try {
      await this.adopt(p2p);
      this.reconnectAttempt = 0;
    } catch (error) {
      p2p.stop();
      const message = error instanceof Error ? error.message : String(error);
      if (error instanceof TransportError && error.code === 'unauthorized') {
        this.patch({ phase: 'offline', error: message, kind: null });
        this.emitRejected(message);
        return;
      }
      const relay = new SignalRelayTransport(
        message,
        'WebRTC could not reach the agent (common with Docker/Podman on a Mac). ' +
          'If the agent is on this machine, open http://127.0.0.1:8420/app/ instead, ' +
          'or set localStorage.filedrop.agentOrigin to the agent HTTP origin. ' +
          'For true remote access, configure TURN on the NAS.',
      );
      await this.adopt(relay);
      this.scheduleReconnect();
    }
  }

  private async resolveBootstrap(nasReachable: boolean): Promise<BootstrapResponse | null> {
    if (nasReachable) {
      try {
        const fresh = await api.bootstrap();
        saveBootstrap(fresh);
        return fresh;
      } catch {
        /* fall through to cache */
      }
    }
    return loadCachedBootstrap();
  }

  private async adopt(transport: Transport): Promise<void> {
    this.teardownActive();
    this.active = transport;
    this.unsubscribeActive = [
      transport.subscribeState((state) => {
        this.patch(state);
        if (state.phase === 'reconnecting' || state.phase === 'offline') this.scheduleReconnect();
      }),
      transport.subscribeEvents((event) => {
        for (const listener of this.eventListeners) listener(event);
      }),
    ];
    await transport.start();
  }

  private teardownActive(): void {
    for (const unsubscribe of this.unsubscribeActive) unsubscribe();
    this.unsubscribeActive = [];
    this.active?.stop();
    this.active = null;
  }

  private patch(state: Partial<ConnectionState>): void {
    this.state = { ...this.state, ...state };
    for (const listener of this.stateListeners) listener(this.state);
  }

  // -------------------------------------------------------------------------
  // Recovery
  // -------------------------------------------------------------------------

  /**
   * A dropped DataChannel mid-transfer is expected (walking out of wifi range,
   * a NAT rebinding). We re-run selection; the transfer engine then retries the
   * file, and the NAS replays which chunks it kept — so the upload picks up
   * from the last acked chunk instead of starting over.
   */
  private scheduleReconnect(): void {
    if (this.disposed || this.reconnectTimer) return;
    const delay = Math.min(RECONNECT_MAX_MS, RECONNECT_BASE_MS * 2 ** this.reconnectAttempt);
    this.reconnectAttempt = Math.min(this.reconnectAttempt + 1, 6);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      void this.select();
    }, delay);
  }

  /**
   * Upgrade watch: once you walk back through your own front door, the NAS
   * becomes reachable again and there is no reason to keep paying WebRTC
   * overhead. We only switch while idle — swapping tiers under a running
   * transfer would throw away its progress.
   */
  private startUpgradeProbe(): void {
    // Standalone has nothing to upgrade *to*, and probing would mean an HTTP
    // request the browser blocks as mixed content.
    if (isStandalone()) return;
    if (this.upgradeTimer) clearInterval(this.upgradeTimer);
    this.upgradeTimer = setInterval(() => {
      if (this.disposed || this.busy > 0) return;
      if (!this.active || this.active.kind === 'lan-direct') return;
      void api.probeHealth(1200).then((health) => {
        if (!health || this.busy > 0 || this.disposed) return;
        if (this.active?.kind === 'lan-direct') return;
        void this.select();
      });
    }, UPGRADE_PROBE_MS);
  }
}

/** Single instance shared by the stores and the UI. */
export const transport = new TransportManager();
