import { create } from 'zustand';
import { randomId } from '../lib/ids';

export interface Toast {
  id: string;
  message: string;
  tone: 'ok' | 'error' | 'info';
}

interface ToastStore {
  toasts: Toast[];
  push(message: string, tone?: Toast['tone']): void;
  dismiss(id: string): void;
}

export const useToasts = create<ToastStore>((set) => ({
  toasts: [],
  push: (message, tone = 'info') => {
    const id = randomId('t');
    set((state) => ({ toasts: [...state.toasts, { id, message, tone }] }));
    setTimeout(() => set((state) => ({ toasts: state.toasts.filter((t) => t.id !== id) })), 3200);
  },
  dismiss: (id) => set((state) => ({ toasts: state.toasts.filter((t) => t.id !== id) })),
}));

export const toast = {
  ok: (message: string): void => useToasts.getState().push(message, 'ok'),
  error: (message: string): void => useToasts.getState().push(message, 'error'),
  info: (message: string): void => useToasts.getState().push(message, 'info'),
};
