import { probeHealth } from './api';

/**
 * Deployment mode — *where this page is being served from*, which decides
 * whether the NAS's HTTP API is reachable at all.
 *
 *   hosted      The NAS agent itself served this page (`http://nas:8420/app/`).
 *               Same origin, so `/api/*` and `/ws/*` work, and all three
 *               transport tiers (lan-direct / p2p / signal-relay) are available.
 *
 *   standalone  The page came from somewhere else — GitHub Pages, a CDN, a
 *               file:// copy. There is NO usable HTTP path to the NAS:
 *
 *                 An `https://` page may not issue fetch/XHR/WebSocket to
 *                 `http://10.0.0.2:8420`. Browsers class it as active mixed
 *                 content and block it outright, with no user override, even
 *                 though both endpoints are on the same LAN. The NAS cannot
 *                 realistically hold a publicly-trusted certificate for a
 *                 private RFC1918 address, so this is not fixable from the
 *                 NAS side either.
 *
 *               WebRTC is the one exception: RTCPeerConnection is not subject
 *               to mixed-content blocking. So in standalone mode *everything*
 *               — discovery, pairing, bootstrap and all data — travels over
 *               Agora signaling and then the DataChannel. There is no
 *               `lan-direct` tier, and we must never issue an `/api/*` call.
 */
export type DeployMode = 'hosted' | 'standalone';

/**
 * The two values a standalone build needs and cannot ship with.
 *
 * The repository is public, so an Agora App ID baked into the bundle would be
 * a published credential: anyone could join the signaling channel and start
 * guessing pair codes. Keeping it in `localStorage` (typed once by the owner,
 * or handed over in a URL *fragment*) means the deployed artifact contains no
 * secrets at all — the same static files are useless to a stranger.
 *
 * The fragment, specifically, because fragments are never sent to the server:
 * GitHub's access logs, any CDN in front of them, and `document.referrer` on
 * outbound links all see the path and query string but never the `#...` part.
 */
export interface StandaloneConfig {
  appId: string;
  channel: string;
  /**
   * Optional RTM token.
   *
   * Normally empty: a static page has nowhere safe to keep an App Certificate,
   * so it signs in with the App ID alone and the Agora project must have its
   * certificate disabled.
   *
   * Supplying a token here is the escape hatch for a project that keeps its
   * certificate ON. It works, but the token is minted against the certificate
   * and expires (24h by default), so the page will stop connecting until it is
   * replaced — fine for a test or a locked-down setup, wrong as a daily driver.
   */
  token?: string;
}

const CONFIG_KEY = 'filedrop.standalone.v1';
const PEER_ID_KEY = 'filedrop.peerid.v1';

/** Static hosts that can never be the NAS, so the probe would just waste time. */
const STATIC_HOST_SUFFIXES = [
  '.github.io',
  '.pages.dev',
  '.netlify.app',
  '.vercel.app',
  '.gitlab.io',
  '.surge.sh',
];

let resolved: DeployMode | null = null;

// ---------------------------------------------------------------------------
// Config storage
// ---------------------------------------------------------------------------

/**
 * Whatever is stored, complete or not. Only the setup form should use this —
 * it exists so a half-filled fragment link (`#appId=…` with no channel) still
 * pre-fills the box instead of silently vanishing.
 */
/**
 * Build-time defaults, baked in by `vite.config.ts` from
 * `FILEDROP_AGORA_APP_ID` / `FILEDROP_AGORA_CHANNEL`.
 *
 * Empty in the GitHub Pages build ON PURPOSE: that artifact is published from a
 * public repository, and a baked App ID would be a published credential —
 * anyone could join the channel and start guessing pair codes.
 *
 * Bake them only when you control who can fetch the bundle: a private Docker
 * image, an internal host, a password-protected site. Then the setup screen is
 * skipped entirely and the page is ready to use the moment it loads.
 *
 * Anything already in localStorage wins, so a user can still point a baked
 * build at a different NAS without rebuilding it.
 */
const BAKED_APP_ID = (import.meta.env.VITE_FILEDROP_AGORA_APP_ID ?? '').trim();
const BAKED_CHANNEL = (import.meta.env.VITE_FILEDROP_AGORA_CHANNEL ?? '').trim();

/** True when this build ships with credentials, so the setup screen is skipped. */
export function hasBakedConfig(): boolean {
  return Boolean(BAKED_APP_ID && BAKED_CHANNEL);
}

export function loadStandaloneDraft(): StandaloneConfig {
  const baked: StandaloneConfig = { appId: BAKED_APP_ID, channel: BAKED_CHANNEL };
  try {
    const raw = localStorage.getItem(CONFIG_KEY);
    if (!raw) return baked;
    const parsed = JSON.parse(raw) as Partial<StandaloneConfig>;
    return {
      // Stored value first, baked default second — so a baked build is a
      // starting point, not a cage.
      appId: (typeof parsed.appId === 'string' ? parsed.appId.trim() : '') || baked.appId,
      channel: (typeof parsed.channel === 'string' ? parsed.channel.trim() : '') || baked.channel,
      token: typeof parsed.token === 'string' ? parsed.token.trim() : '',
    };
  } catch {
    return baked;
  }
}

/** Usable config only: both halves present. Everything but the form uses this. */
export function loadStandaloneConfig(): StandaloneConfig | null {
  const draft = loadStandaloneDraft();
  return draft.appId && draft.channel ? draft : null;
}

export function saveStandaloneConfig(config: StandaloneConfig): void {
  try {
    localStorage.setItem(
      CONFIG_KEY,
      JSON.stringify({
        appId: config.appId.trim(),
        channel: config.channel.trim(),
        // Persist only when non-empty so the common case stays a clean 2-key object.
        ...(config.token?.trim() ? { token: config.token.trim() } : {}),
      }),
    );
  } catch {
    /* private mode: the app still works for this tab, it just re-asks next time */
  }
}

export function clearStandaloneConfig(): void {
  try {
    localStorage.removeItem(CONFIG_KEY);
    localStorage.removeItem(PEER_ID_KEY);
  } catch {
    /* ignore */
  }
}

/**
 * This browser's stable address on the signaling channel.
 *
 * Distinct from the NAS-assigned `deviceId`: we need something to put in
 * `SignalEnvelope.from` *before* we are paired, and the NAS replies to whatever
 * address it received. Persisting it means a reload keeps the same identity
 * instead of leaving the NAS holding a stale peer.
 */
export function standalonePeerId(): string {
  try {
    const existing = localStorage.getItem(PEER_ID_KEY);
    if (existing) return existing;
  } catch {
    /* fall through and mint an ephemeral one */
  }
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  let id = 'dev-';
  for (const b of bytes) id += b.toString(16).padStart(2, '0');
  try {
    localStorage.setItem(PEER_ID_KEY, id);
  } catch {
    /* ephemeral for this tab */
  }
  return id;
}

// ---------------------------------------------------------------------------
// Fragment hand-off
// ---------------------------------------------------------------------------

/**
 * Accept `#appId=...&channel=...` so the owner can bookmark (or AirDrop to a
 * phone) one preconfigured link instead of retyping a 32-character App ID.
 *
 * Read once, persisted, then scrubbed from the address bar via
 * `history.replaceState` — otherwise it lingers in screenshots, in the
 * browser's history UI and in anything that syncs open tabs between devices.
 *
 * Call before rendering so the setup screen never flashes for a user who
 * arrived with a configured link.
 */
export function adoptConfigFromFragment(): void {
  const hash = window.location.hash.replace(/^#/, '');
  if (!hash) return;

  let params: URLSearchParams;
  try {
    params = new URLSearchParams(hash);
  } catch {
    return;
  }
  const appId = params.get('appId')?.trim();
  const channel = params.get('channel')?.trim();
  const token = params.get('token')?.trim();
  if (!appId && !channel && !token) return;

  // Persist even a partial hand-off: the setup form pre-fills from the draft,
  // so the user only has to supply the missing half rather than both.
  const existing = loadStandaloneDraft();
  saveStandaloneConfig({
    appId: appId || existing.appId,
    channel: channel || existing.channel,
    // Carry the stored token forward — omitting it here would silently wipe it
    // every time someone re-opened a plain `#appId=…&channel=…` link.
    token: token || existing.token,
  });

  params.delete('appId');
  params.delete('channel');
  params.delete('token');
  const remainder = params.toString();
  window.history.replaceState(
    null,
    '',
    window.location.pathname + window.location.search + (remainder ? `#${remainder}` : ''),
  );
}

// ---------------------------------------------------------------------------
// Detection
// ---------------------------------------------------------------------------

function isStaticHost(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return STATIC_HOST_SUFFIXES.some((suffix) => host.endsWith(suffix));
}

/**
 * Decide the mode *before* anything issues a request.
 *
 * Order matters. Every branch above the probe exists so that a page which is
 * obviously not NAS-hosted never touches `/api/*` at all: on GitHub Pages the
 * relative probe would resolve against github.io and come back as a 404 HTML
 * page, which is harmless but noisy, and it costs a round trip on every cold
 * start before the real work can begin.
 */
export async function resolveDeployMode(): Promise<DeployMode> {
  if (resolved) return resolved;

  const pinned = import.meta.env.VITE_FILEDROP_MODE;
  if (pinned === 'standalone' || pinned === 'hosted') {
    resolved = pinned;
    return resolved;
  }

  // Already set up as standalone once: never probe again.
  if (loadStandaloneConfig()) {
    resolved = 'standalone';
    return resolved;
  }

  if (isStaticHost(window.location.hostname) || window.location.protocol === 'file:') {
    resolved = 'standalone';
    return resolved;
  }

  // Undecidable statically (a custom domain, a local `vite preview`, an
  // intranet host). The probe is same-origin here — never mixed content — so
  // it is safe: it either answers (we are on the NAS) or it does not.
  const health = await probeHealth(1500);
  resolved = health ? 'hosted' : 'standalone';
  return resolved;
}

/** Synchronous accessor for code that runs after `resolveDeployMode()`. */
export function getDeployMode(): DeployMode {
  return resolved ?? 'hosted';
}

export function isStandalone(): boolean {
  return getDeployMode() === 'standalone';
}

/** Test/reset seam: forget the cached decision. */
export function resetDeployMode(): void {
  resolved = null;
}
