import { useState } from 'react';
import { useAuth } from '../state/auth';
import { loadStandaloneDraft } from '../net/mode';
import { LogoIcon } from './Icons';

/**
 * First-run setup for the standalone (GitHub Pages) build.
 *
 * Nothing is baked into the bundle: the repository is public, so an Agora App
 * ID compiled into the JavaScript would be a credential published to the world,
 * and anyone who found it could join the signaling channel. Instead the two
 * values live in this browser's `localStorage` — the deployed artifact stays
 * completely generic and is useless to anyone but its owner.
 *
 * The same pair can arrive in the URL *fragment* (`#appId=…&channel=…`), which
 * `adoptConfigFromFragment()` consumes and scrubs before render. Fragment, not
 * query string, because fragments are never transmitted to the server: they
 * stay out of GitHub's access logs, out of any CDN in between, and out of the
 * `Referer` header on outbound links.
 */

const APP_ID_HEX = /^[0-9a-f]{32}$/i;
/** Agora's channel-name charset, trimmed to what is comfortable to type. */
const CHANNEL_OK = /^[A-Za-z0-9_.\-]{3,64}$/;

function suggestChannel(): string {
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  let suffix = '';
  for (const b of bytes) suffix += b.toString(36);
  return `filedrop-${suffix.slice(0, 12)}`;
}

export function SetupScreen(): JSX.Element {
  const saveSetup = useAuth((state) => state.saveSetup);
  // Read once on mount: a fragment hand-off may have left a partial draft.
  const [appId, setAppId] = useState(() => loadStandaloneDraft().appId);
  const [channel, setChannel] = useState(() => loadStandaloneDraft().channel);
  const [touched, setTouched] = useState(false);
  const [copied, setCopied] = useState(false);

  const appIdTrimmed = appId.trim();
  const channelTrimmed = channel.trim();
  const appIdValid = APP_ID_HEX.test(appIdTrimmed);
  const channelValid = CHANNEL_OK.test(channelTrimmed);
  const valid = appIdValid && channelValid;

  const submit = (): void => {
    setTouched(true);
    if (!valid) return;
    saveSetup(appIdTrimmed, channelTrimmed);
  };

  const copyLink = (): void => {
    const params = new URLSearchParams({ appId: appIdTrimmed, channel: channelTrimmed });
    const link = `${window.location.origin}${window.location.pathname}#${params.toString()}`;
    void import('../lib/clipboard').then(({ copyText }) =>
      copyText(link).then((ok) => {
        if (!ok) return;
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      }),
    );
  };

  return (
    <div className="pair">
      <div className="pair__panel">
        <div className="pair__brand">
          <LogoIcon />
          <strong>FileDrop</strong>
        </div>

        <h1>Connect this page to your NAS</h1>
        <p className="pair__lede">
          This copy of FileDrop is served as a static page, so it cannot talk to your NAS over HTTP
          — a secure page is not allowed to reach a plain-HTTP address on your network. Everything
          goes peer-to-peer instead, and that needs the signaling details your NAS is configured
          with.
        </p>

        <form
          className="setup"
          onSubmit={(event) => {
            event.preventDefault();
            submit();
          }}
        >
          <label className="field">
            <span className="field__label">Agora App ID</span>
            <input
              className="field__input mono"
              value={appId}
              onChange={(event) => setAppId(event.target.value)}
              placeholder="32 hexadecimal characters"
              autoComplete="off"
              autoCapitalize="off"
              spellCheck={false}
              aria-invalid={touched && !appIdValid}
            />
            <span className="field__hint">
              {touched && !appIdValid ?
                'An Agora App ID is exactly 32 hexadecimal characters.'
              : 'From the Agora console — the same App ID your NAS agent uses.'}
            </span>
          </label>

          <label className="field">
            <span className="field__label">Signaling channel</span>
            <span className="field__row">
              <input
                className="field__input mono"
                value={channel}
                onChange={(event) => setChannel(event.target.value)}
                placeholder="filedrop-…"
                autoComplete="off"
                autoCapitalize="off"
                spellCheck={false}
                aria-invalid={touched && !channelValid}
              />
              <button
                type="button"
                className="btn btn--sm"
                onClick={() => setChannel(suggestChannel())}
              >
                Suggest
              </button>
            </span>
            <span className="field__hint">
              {touched && !channelValid ?
                '3–64 characters: letters, digits, dot, dash or underscore.'
              : 'Must match AGORA_CHANNEL on the NAS. Treat it as a secret — anyone who knows it can watch this channel.'}
            </span>
          </label>

          <button type="submit" className="btn btn--accent setup__submit" disabled={!valid}>
            Look for my NAS
          </button>
        </form>

        <div className="setup__aside">
          <p>
            Both values are stored <strong>only in this browser</strong>, in <code>localStorage</code>.
            They are never sent anywhere except to Agora when joining the channel, and nothing is
            baked into the page itself — that is why it asks.
          </p>
          <button type="button" className="btn btn--sm" disabled={!valid} onClick={copyLink}>
            {copied ? 'Link copied' : 'Copy preconfigured link'}
          </button>
          <p className="setup__aside-note">
            The link carries both values in the <code>#fragment</code>, which browsers never send to
            a server. Handy for setting up a phone — but treat it like a password.
          </p>
        </div>
      </div>
    </div>
  );
}
