import type { Item } from '@filedrop/shared';
import { create } from 'zustand';
import { randomId } from '../lib/ids';
import { setUploadListener } from '../net/transfer';
import { transport } from '../net/transport';
import type { TextKind } from '../net/types';

const PAGE_SIZE = 40;

export interface ItemsState {
  /** Oldest first — newest sits at the bottom (chat-style). */
  items: Item[];
  nextCursor: string | null;
  query: string;
  loading: boolean;
  loadingMore: boolean;
  /** Set when the first page could not be fetched at all. */
  error: string | null;
  /** Item ids that arrived after mount, so they can animate in exactly once. */
  fresh: Set<string>;
  /** Bumped when the first page lands so the timeline can scroll to bottom. */
  bootEpoch: number;

  refresh(): Promise<void>;
  loadMore(): Promise<void>;
  setQuery(query: string): void;
  sendText(text: string, kind: TextKind): Promise<void>;
  remove(itemId: string): Promise<void>;
  upsert(item: Item): void;
  drop(itemId: string): void;
}

let listToken = 0;

/** Stable chat order: older → newer. */
function sortChat(items: Item[]): Item[] {
  return [...items].sort((a, b) => {
    if (a.createdAt !== b.createdAt) return a.createdAt - b.createdAt;
    return a.id.localeCompare(b.id);
  });
}

function mergeChat(existing: Item[], incoming: Item[]): Item[] {
  const byId = new Map(existing.map((item) => [item.id, item]));
  for (const item of incoming) byId.set(item.id, item);
  return sortChat([...byId.values()]);
}

export const useItems = create<ItemsState>((set, get) => ({
  items: [],
  nextCursor: null,
  query: '',
  loading: false,
  loadingMore: false,
  error: null,
  fresh: new Set(),
  bootEpoch: 0,

  refresh: async () => {
    const token = ++listToken;
    set({ loading: true, error: null });
    try {
      // API still returns newest-first pages; reverse for chat display.
      const result = await transport.list({ limit: PAGE_SIZE, query: get().query || undefined });
      if (token !== listToken) return;
      set((state) => ({
        items: sortChat(result.items),
        nextCursor: result.nextCursor,
        loading: false,
        bootEpoch: state.bootEpoch + 1,
      }));
    } catch (error) {
      if (token !== listToken) return;
      set({
        loading: false,
        error: error instanceof Error ? error.message : 'Could not load the timeline',
      });
    }
  },

  loadMore: async () => {
    const { nextCursor, loadingMore, query } = get();
    if (!nextCursor || loadingMore) return;
    const token = listToken;
    set({ loadingMore: true });
    try {
      // Older page (API DESC). Merge into chat order (ASC).
      const result = await transport.list({
        cursor: nextCursor,
        limit: PAGE_SIZE,
        query: query || undefined,
      });
      if (token !== listToken) return;
      set((state) => ({
        items: mergeChat(state.items, result.items),
        nextCursor: result.nextCursor,
        loadingMore: false,
      }));
    } catch {
      set({ loadingMore: false });
    }
  },

  setQuery: (query) => {
    set({ query, nextCursor: null });
    void get().refresh();
  },

  sendText: async (text, kind) => {
    const trimmed = text.trim();
    if (!trimmed) return;
    const clientId = randomId('c');
    const optimistic: Item = {
      id: clientId,
      kind,
      createdAt: Date.now(),
      originDeviceId: 'self',
      originDeviceName: 'This device',
      text: trimmed,
    };
    set((state) => ({ items: mergeChat(state.items, [optimistic]) }));
    try {
      const item = await transport.postText(trimmed, kind, clientId);
      set((state) => ({
        items: mergeChat(
          state.items.filter((existing) => existing.id !== clientId),
          [item],
        ),
      }));
    } catch (error) {
      set((state) => ({
        items: state.items.filter((existing) => existing.id !== clientId),
        error: error instanceof Error ? error.message : 'Could not send',
      }));
      throw error;
    }
  },

  remove: async (itemId) => {
    const snapshot = get().items;
    set({ items: snapshot.filter((item) => item.id !== itemId) });
    try {
      await transport.remove(itemId);
    } catch (error) {
      set({ items: snapshot, error: error instanceof Error ? error.message : 'Could not delete' });
    }
  },

  upsert: (item) =>
    set((state) => {
      const known = state.items.some((existing) => existing.id === item.id);
      const fresh = new Set(state.fresh);
      if (!known) fresh.add(item.id);
      return { items: mergeChat(state.items, [item]), fresh };
    }),

  drop: (itemId) => set((state) => ({ items: state.items.filter((item) => item.id !== itemId) })),
}));

transport.subscribeEvents((event) => {
  const store = useItems.getState();
  if (event.type === 'item-new' || event.type === 'item-updated') store.upsert(event.item);
  else store.drop(event.itemId);
});

setUploadListener((item) => useItems.getState().upsert(item));
