import { AUTH_MAX_ATTEMPTS, AUTH_TOKEN_TTL_DAYS } from '@filedrop/shared';
import { useEffect, useMemo, useRef, useState } from 'react';
import { copyText, selectElementText } from '../lib/clipboard';
import { encodeQr, qrToSvgPath, qrViewBox } from '../lib/qr';
import { hasBakedConfig } from '../net/mode';
import { useAuth } from '../state/auth';
import { AlertIcon, CheckIcon, CopyIcon, LogoIcon, RefreshIcon } from './Icons';

/**
 * The unpaired standalone device's screen: a QR someone scans, then a wait.
 *
 * Replaces the typed pairing code. A code has to be read off a NAS log and
 * carried to another device by hand, and on a channel anyone can join it is the
 * only thing standing between a stranger and your files. Here nothing is typed:
 * the device commits to a secret, shows it as a QR, and a human with the
 * owner's Telegram account decides. The screen's whole job is to make the wait
 * legible — scanned yet? sent yet? how long have I got?
 */

/** Whole seconds until `until`, ticking; 0 once past. */
function useCountdown(until: number | null): number {
  const [remaining, setRemaining] = useState(() =>
    until ? Math.max(0, Math.ceil((until - Date.now()) / 1000)) : 0,
  );

  useEffect(() => {
    if (!until) {
      setRemaining(0);
      return;
    }
    const tick = (): void => setRemaining(Math.max(0, Math.ceil((until - Date.now()) / 1000)));
    tick();
    const timer = setInterval(tick, 500);
    return () => clearInterval(timer);
  }, [until]);

  return remaining;
}

function mmss(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m)}:${String(s).padStart(2, '0')}`;
}

/**
 * The QR itself, as inline SVG.
 *
 * White panel with a wide quiet zone, even though the rest of the UI is dark.
 * Inverting it to fit the theme is the single most common way to ship a QR that
 * photographs badly: scanners look for dark-on-light finder patterns, and while
 * many cope with an inversion, the ones on a stranger's phone in bad light
 * often do not. Scannability wins over taste here.
 */
function QrPanel({ value }: { value: string }): JSX.Element {
  const qr = useMemo(() => {
    try {
      return encodeQr(value, { ecLevel: 'M' });
    } catch {
      return null;
    }
  }, [value]);

  if (!qr) {
    return (
      <p className="pair__error">
        授权链接过长，无法生成二维码，请改用复制链接。
      </p>
    );
  }

  const box = qrViewBox(qr);
  return (
    <div className="qr">
      <svg
        viewBox={`0 0 ${String(box)} ${String(box)}`}
        xmlns="http://www.w3.org/2000/svg"
        // Without this, the browser antialiases the edges of the merged runs and
        // adjacent modules bleed into one another at small sizes.
        shapeRendering="crispEdges"
        role="img"
        aria-label="QR code containing this device's authorisation link"
      >
        <rect width={box} height={box} fill="#ffffff" />
        <path d={qrToSvgPath(qr)} fill="#000000" />
      </svg>
    </div>
  );
}

function CopyButton({
  value,
  selectTarget,
}: {
  value: string;
  /** Visible node to highlight if the Clipboard API is blocked (common on mobile HTTP). */
  selectTarget?: React.RefObject<HTMLElement | null>;
}): JSX.Element {
  const [copied, setCopied] = useState(false);
  const [hint, setHint] = useState<string | null>(null);

  return (
    <div className="auth__copy-wrap">
      <button
        type="button"
        className="btn btn--sm auth__copy"
        onClick={() => {
          void (async () => {
            const ok = await copyText(value);
            if (ok) {
              setCopied(true);
              setHint(null);
              setTimeout(() => setCopied(false), 2000);
              return;
            }
            // Mobile Safari / Chrome on http://LAN-IP often block clipboard —
            // select the URL so the user can long-press → 复制.
            selectElementText(selectTarget?.current ?? null);
            setHint('已选中链接，请长按选择「复制」');
            setTimeout(() => setHint(null), 4000);
          })();
        }}
      >
        {copied ? <CheckIcon /> : <CopyIcon />}
        <span>{copied ? '已复制' : '复制链接'}</span>
      </button>
      {hint ? <p className="auth__copy-hint">{hint}</p> : null}
    </div>
  );
}

export function AuthRequestScreen(): JSX.Element {
  const nasName = useAuth((state) => state.nas?.nasName ?? 'your NAS');
  const authRequest = useAuth((state) => state.authRequest);
  const authState = useAuth((state) => state.authState);
  const attemptsLeft = useAuth((state) => state.authAttemptsLeft);
  const authError = useAuth((state) => state.authError);
  const authMessage = useAuth((state) => state.authMessage);
  const authBusy = useAuth((state) => state.authBusy);
  const lapsedNote = useAuth((state) => state.lapsedNote);
  const startAuthRequest = useAuth((state) => state.startAuthRequest);
  const forget = useAuth((state) => state.forget);
  const baked = hasBakedConfig();
  const certificateError = /DYNAMIC_ENABLED_BUT_STATIC_KEY/i.test(authError ?? '');

  // Register on arrival, and never twice: `authError` is the brake, so a NAS
  // that is not answering produces one message rather than a retry storm.
  useEffect(() => {
    if (!authRequest && !authBusy && !authError) startAuthRequest();
  }, [authRequest, authBusy, authError, startAuthRequest]);

  const remaining = useCountdown(authRequest?.expiresAt ?? null);
  const terminal =
    authState === 'rejected' || authState === 'expired' || authState === 'blocked';
  const showQr = authRequest !== null && !terminal;
  const urlRef = useRef<HTMLElement | null>(null);

  return (
    <div className="pair">
      <div className="pair__panel pair__panel--wide">
        <div className="pair__brand">
          <LogoIcon />
          <strong>FileDrop</strong>
        </div>

        <h1>扫码申请访问</h1>
        <p className="pair__lede">
          授权给<strong>当前这个浏览器</strong>（本机手机/电脑），不是给提供网页的那台主机。
          其它设备打开同一地址会各自申请、各自授权，可同时连接 {nasName} 存数据。
          用任意手机扫码，机主在 Telegram 点同意即可。
        </p>

        {lapsedNote ? <p className="auth__note">{lapsedNote}</p> : null}

        {authBusy && !authRequest ?
          <p className="auth__status">
            <span className="spinner discover__spinner" aria-hidden="true" />
            正在准备二维码…
          </p>
        : null}

        {showQr && authRequest ?
          <>
            <QrPanel value={authRequest.url} />

            <div className="auth__link">
              <p className="auth__link-label">或在另一台设备打开链接</p>
              {/* Selectable: camera / blocked Clipboard API on mobile HTTP. */}
              <code className="auth__url mono" ref={urlRef as React.RefObject<HTMLElement>}>
                {authRequest.url}
              </code>
              <CopyButton value={authRequest.url} selectTarget={urlRef} />
            </div>
          </>
        : null}

        <AuthState
          state={authState}
          message={authMessage}
          error={authError}
          remaining={remaining}
        />

        {certificateError ?
          <div className="discover__causes">
            <p className="discover__causes-title">
              <AlertIcon />
              Agora 仍开启了 App Certificate
            </p>
            <p>
              请使用带 token 签发的本地 UI（<code>serve:standalone</code>），或在 Agora 控制台关闭
              Primary Certificate，并保证 NAS 的 <code>agora.certificate</code> 配置一致。
            </p>
          </div>
        : null}

        {attemptsLeft !== null && attemptsLeft < AUTH_MAX_ATTEMPTS ?
          <p className="auth__attempts">
            Attempts left: <strong className="mono">{attemptsLeft}</strong> of{' '}
            {String(AUTH_MAX_ATTEMPTS)}
          </p>
        : null}

        {terminal || authError ?
          <button
            type="button"
            className="btn btn--accent"
            style={{ width: '100%', height: 40 }}
            disabled={authState === 'blocked' || authBusy}
            onClick={startAuthRequest}
          >
            <RefreshIcon />
            {authBusy ? '重新申请中…' : '重新申请'}
          </button>
        : null}

        <p className="pair__hint">
          流程：扫码 → Telegram 批准 → 点对点连接 NAS。授权有效期{' '}
          {String(AUTH_TOKEN_TTL_DAYS)} 天，到期后需重新批准。
        </p>

        {!baked ?
          <button type="button" className="btn btn--sm btn--ghost pair__reset" onClick={forget}>
            重置连接配置
          </button>
        : null}
      </div>
    </div>
  );
}

/**
 * One line saying exactly where the request is.
 *
 * The three live states are genuinely different situations for the user — no
 * one has scanned it yet / someone has and the owner has not answered / it is
 * over — and collapsing them into a single spinner is what makes a wait feel
 * broken.
 */
function AuthState({
  state,
  message,
  error,
  remaining,
}: {
  state: string | null;
  message: string | null;
  error: string | null;
  remaining: number;
}): JSX.Element | null {
  if (error) {
    return (
      <p className="pair__error">
        <AlertIcon />
        {error}
      </p>
    );
  }

  switch (state) {
    case 'pending':
      return (
        <p className="auth__status" data-tone="wait">
          <span className="auth__dot" aria-hidden="true" />
          等待扫码 · 剩余 <strong className="mono">{mmss(remaining)}</strong>
        </p>
      );
    case 'notified':
      return (
        <p className="auth__status" data-tone="live">
          <span className="auth__dot" aria-hidden="true" />
          已通知 · 等待 Telegram 批准 ·{' '}
          <strong className="mono">{mmss(remaining)}</strong>
        </p>
      );
    case 'approved':
      return (
        <p className="auth__status" data-tone="ok">
          <CheckIcon />
          已批准，正在连接…
        </p>
      );
    case 'rejected':
      return (
        <p className="pair__error">
          {message ?? '机主已拒绝此请求，未向本设备共享任何内容。'}
        </p>
      );
    case 'expired':
      return (
        <p className="pair__error">
          {message ?? '请求已过期，请重新申请获取新的二维码。'}
        </p>
      );
    case 'blocked':
      return (
        <p className="pair__error">
          <AlertIcon />
          {message ??
            `本设备已用尽 ${String(AUTH_MAX_ATTEMPTS)} 次尝试并被封锁。机主已收到通知，可在 NAS 上解除。`}
        </p>
      );
    default:
      return null;
  }
}
