/**
 * Copy text on desktop + mobile, including plain HTTP on a LAN IP.
 *
 * `navigator.clipboard` only works in a secure context (HTTPS or localhost).
 * Phones opening `http://192.168.x.x:8421` are NOT secure contexts, so the
 * Clipboard API is missing or throws — silent failure looked like "copy does
 * nothing". Fall back to a temporary textarea + `document.execCommand('copy')`,
 * which still works under a user gesture on most mobile browsers.
 */

export async function copyText(text: string): Promise<boolean> {
  const value = typeof text === 'string' ? text : String(text ?? '');
  if (!value) return false;

  if (typeof window !== 'undefined' && window.isSecureContext && navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(value);
      return true;
    } catch {
      /* fall through to legacy path */
    }
  }

  return copyTextLegacy(value);
}

function copyTextLegacy(text: string): boolean {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.setAttribute('aria-hidden', 'true');
    // Keep in viewport (iOS often ignores off-screen elements).
    ta.style.position = 'fixed';
    ta.style.top = '0';
    ta.style.left = '0';
    ta.style.width = '2em';
    ta.style.height = '2em';
    ta.style.padding = '0';
    ta.style.margin = '0';
    ta.style.border = 'none';
    ta.style.outline = 'none';
    ta.style.boxShadow = 'none';
    ta.style.background = 'transparent';
    ta.style.opacity = '0.01';
    // 16px avoids iOS focus zoom.
    ta.style.fontSize = '16px';
    ta.style.zIndex = '-1';

    document.body.appendChild(ta);

    const isIOS =
      /iPad|iPhone|iPod/.test(navigator.userAgent) ||
      (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

    if (isIOS) {
      const range = document.createRange();
      range.selectNodeContents(ta);
      const sel = window.getSelection();
      sel?.removeAllRanges();
      sel?.addRange(range);
      ta.setSelectionRange(0, text.length);
    } else {
      ta.focus();
      ta.select();
      ta.setSelectionRange(0, text.length);
    }

    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    window.getSelection()?.removeAllRanges();
    return ok;
  } catch {
    return false;
  }
}

/**
 * Last-resort UX when copy APIs fail: select a visible element so the user
 * can long-press → copy on mobile.
 */
export function selectElementText(el: HTMLElement | null): void {
  if (!el) return;
  try {
    const range = document.createRange();
    range.selectNodeContents(el);
    const sel = window.getSelection();
    sel?.removeAllRanges();
    sel?.addRange(range);
  } catch {
    /* ignore */
  }
}
