import type { Item } from '@filedrop/shared';
import { Fragment } from 'react';
import { findUrls, isBareUrl, normalizeUrl, urlHost } from '../../lib/format';
import { ClipboardIcon, LinkIcon } from '../Icons';

/** Renders a text body with any embedded URLs turned into real links. */
function Linkified({ text }: { text: string }): JSX.Element {
  const urls = findUrls(text);
  if (urls.length === 0) return <>{text}</>;

  const pattern = new RegExp(`(${urls.map(escapeRegExp).join('|')})`, 'g');
  const parts = text.split(pattern);
  return (
    <>
      {parts.map((part, index) =>
        urls.includes(part) ? (
          // eslint-disable-next-line react/no-array-index-key -- split output is positional
          <a key={index} href={normalizeUrl(part)} target="_blank" rel="noreferrer noopener">
            {part}
          </a>
        ) : (
          <Fragment key={index}>{part}</Fragment>
        ),
      )}
    </>
  );
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export function TextCard({ item }: { item: Item }): JSX.Element {
  const text = item.text ?? '';

  // A message that is nothing but a URL reads better as a card than as a line
  // of blue text — it is the most common thing people send themselves.
  if (item.kind === 'link' || isBareUrl(text)) {
    return (
      <a
        className="card link-card"
        href={normalizeUrl(text.trim())}
        target="_blank"
        rel="noreferrer noopener"
      >
        <span className="link-card__glyph">
          <LinkIcon />
        </span>
        <span className="link-card__text">
          <span className="link-card__host">{urlHost(text.trim())}</span>
          <span className="link-card__url">{text.trim()}</span>
        </span>
      </a>
    );
  }

  return (
    <div className={`card text-card${item.kind === 'clipboard' ? ' text-card--clipboard' : ''}`}>
      {item.kind === 'clipboard' ? (
        <span className="text-card__tag">
          <ClipboardIcon />
          clipboard
        </span>
      ) : null}
      <p className="text-card__body">
        <Linkified text={text} />
      </p>
    </div>
  );
}
