import type { Item } from '@filedrop/shared';
import { useEffect, useState } from 'react';
import { usePasteIngest, useWindowDrop } from '../hooks/useIngest';
import { downloadItem } from '../lib/download';
import { useAuth } from '../state/auth';
import { useConnection } from '../state/connection';
import { useItems } from '../state/items';
import { Composer } from './Composer';
import { ConnectionModule } from './ConnectionModule';
import { CloseIcon, LogoIcon, SearchIcon } from './Icons';
import { Lightbox } from './Lightbox';
import { DropOverlay, Toasts } from './Overlays';
import { Timeline } from './Timeline';
import { TransferTray } from './TransferTray';

interface Viewer {
  items: Item[];
  index: number;
}

export function MainScreen(): JSX.Element {
  const dragging = useWindowDrop();
  usePasteIngest();

  const phase = useConnection((state) => state.phase);
  const nasName = useConnection((state) => state.nasName);
  const sessionNas = useAuth((state) => state.session?.nasName ?? null);
  const refresh = useItems((state) => state.refresh);
  const [viewer, setViewer] = useState<Viewer | null>(null);

  // The first list can only be fetched once a transport is up; re-fetch after a
  // reconnect too, since we may have missed pushes while the link was down.
  const ready = phase === 'online' || phase === 'degraded';
  useEffect(() => {
    if (ready) void refresh();
  }, [ready, refresh]);

  return (
    <>
      <div className="grain" aria-hidden="true" />
      <div className="app">
        <header className="header">
          <div className="brand">
            <LogoIcon className="brand__mark" />
            <div>
              <div className="brand__name">FileDrop</div>
              <div className="brand__nas">{nasName ?? sessionNas ?? 'not connected'}</div>
            </div>
          </div>
          <div className="header__spacer" />
          <SearchBox />
          <ConnectionModule />
        </header>

        <Timeline
          onOpenMedia={(item, siblings) =>
            setViewer({ items: siblings, index: Math.max(0, siblings.indexOf(item)) })
          }
          onDownload={(item) => void downloadItem(item)}
        />

        <div>
          <TransferTray />
          <Composer />
        </div>
      </div>

      {dragging ? <DropOverlay /> : null}
      {viewer ? (
        <Lightbox
          items={viewer.items}
          index={viewer.index}
          onIndexChange={(index) => setViewer({ ...viewer, index })}
          onClose={() => setViewer(null)}
          onDownload={(item) => void downloadItem(item)}
        />
      ) : null}
      <Toasts />
    </>
  );
}

function SearchBox(): JSX.Element {
  const query = useItems((state) => state.query);
  const setQuery = useItems((state) => state.setQuery);
  const [draft, setDraft] = useState(query);

  // Debounced: search is server-side, and firing a request per keystroke over a
  // DataChannel would queue up behind itself.
  useEffect(() => {
    if (draft === query) return;
    const timer = setTimeout(() => setQuery(draft), 260);
    return () => clearTimeout(timer);
  }, [draft, query, setQuery]);

  return (
    <div className="search">
      <SearchIcon className="search__icon" />
      <input
        type="search"
        value={draft}
        placeholder="Search"
        onChange={(event) => setDraft(event.target.value)}
        aria-label="Search the timeline"
      />
      {draft ? (
        <button type="button" className="search__clear" onClick={() => setDraft('')} aria-label="Clear search">
          <CloseIcon />
        </button>
      ) : null}
    </div>
  );
}
