import {
  CHUNK_SIZE,
  type BootstrapResponse,
  type ControlMessage,
  type DecodedChunk,
  type Item,
  type TransportKind,
} from '@filedrop/shared';
import { randomId, seqToTransferId, newTransferSeq, transferIdToSeq } from '../../lib/ids';
import { chunkCount, pumpBlob } from '../chunkPump';
import { hashFile } from '../hash';
import { PeerLink } from '../rtc';
import type { DeviceSession } from '../session';
import type { SignalingChannel } from '../signaling';
import {
  TransportError,
  type ListParams,
  type ListResult,
  type TextKind,
  type Transport,
  type UploadContext,
} from '../types';
import { BaseTransport } from './base';

interface ActiveDownload {
  seq: number;
  parts: Array<Uint8Array | undefined>;
  received: number;
  expected: number | null;
  totalChunks: number;
  onProgress?: (bytes: number) => void;
}

/**
 * P2P tier — WebRTC DataChannel.
 *
 * The signaling channel is used for exactly one thing: swapping an SDP
 * offer/answer and ICE candidates. Once `datachannel.readyState === 'open'` it
 * goes idle and every byte — control JSON and file chunks alike — flows
 * directly between this browser and the NAS.
 */
export class P2pTransport extends BaseTransport implements Transport {
  private link: PeerLink | null = null;
  private resolvedKind: TransportKind = 'p2p-srflx';
  private readonly downloads = new Map<number, ActiveDownload>();
  private stopped = false;

  constructor(
    private readonly bootstrap: BootstrapResponse,
    private readonly session: DeviceSession,
    /** True when the NAS HTTP API could not be reached, so Agora carries signaling. */
    private readonly preferAgora: boolean,
    /**
     * Standalone mode hands over the Agora channel it already used to discover,
     * pair and bootstrap, rather than paying for a second RTM login.
     */
    private readonly signaling?: SignalingChannel,
  ) {
    super();
  }

  get kind(): TransportKind {
    return this.resolvedKind;
  }

  async start(): Promise<void> {
    this.stopped = false;
    this.patchState({
      phase: 'connecting',
      kind: null,
      signalingIdle: false,
      note: this.preferAgora ? 'Negotiating via Agora Signaling…' : 'Negotiating via the NAS socket…',
      error: null,
    });

    const link = new PeerLink({
      bootstrap: this.bootstrap,
      session: this.session,
      preferAgora: this.preferAgora,
      sessionId: randomId('s'),
      ...(this.signaling ? { signaling: this.signaling } : {}),
      onControl: (message) => this.handleControl(message),
      onChunk: (chunk) => this.handleChunk(chunk),
      onPathResolved: (kind, path) => {
        this.resolvedKind = kind;
        this.patchState({ kind, path });
      },
      onRtt: (rttMs) => this.patchState({ rttMs }),
      onClosed: (reason) => {
        if (this.stopped) return;
        this.link = null;
        this.failAllDownloads();
        this.patchState({ phase: 'reconnecting', note: reason, signalingIdle: false });
      },
    });
    this.link = link;

    const ready = await link.open();
    this.patchState({
      phase: 'online',
      kind: link.transportKind,
      nasName: ready.nasName,
      freeBytes: ready.freeBytes,
      // The headline fact: signaling is done, the link is direct.
      signalingIdle: true,
      note: null,
      error: null,
    });
  }

  stop(): void {
    this.stopped = true;
    this.link?.close('client stopped');
    this.link = null;
    this.failAllDownloads();
    this.patchState({ phase: 'idle', signalingIdle: false });
  }

  private require(): PeerLink {
    if (!this.link || !this.link.isOpen()) {
      throw new TransportError('The direct link is down', 'unreachable');
    }
    return this.link;
  }

  // -------------------------------------------------------------------------
  // Inbound
  // -------------------------------------------------------------------------

  private handleControl(message: ControlMessage): void {
    for (const listener of this.ackListeners) listener(message);
    switch (message.type) {
      case 'item-new':
        this.emit({ type: 'item-new', item: message.item });
        break;
      case 'item-removed':
        this.emit({ type: 'item-removed', itemId: message.itemId });
        break;
      case 'item-updated':
        this.emit({ type: 'item-updated', item: message.item });
        break;
      case 'download-init': {
        const seq = transferIdToSeq(message.transferId);
        const download = seq == null ? undefined : this.downloads.get(seq);
        if (download) {
          download.expected = message.file.size;
          download.totalChunks = message.totalChunks;
          download.parts = new Array<Uint8Array | undefined>(message.totalChunks);
        }
        break;
      }
      default:
        break;
    }
  }

  private handleChunk(chunk: DecodedChunk): void {
    let download = this.downloads.get(chunk.transferSeq);
    // Defensive: if a peer implementation derives the seq differently and only
    // one download is in flight, route to it rather than dropping the file.
    if (!download && this.downloads.size === 1) {
      download = [...this.downloads.values()][0];
    }
    if (!download) return;
    // The payload view aliases the receive buffer, so copy before keeping it.
    download.parts[chunk.chunkIndex] = new Uint8Array(chunk.payload);
    download.received += chunk.payload.byteLength;
    download.onProgress?.(download.received);
  }

  /**
   * Downloads are awaiting a `download-complete` that will never arrive once
   * the link is gone; clearing the map lets their waiters time out and frees
   * the buffered parts immediately rather than holding a partial file.
   */
  private failAllDownloads(): void {
    this.downloads.clear();
  }

  // -------------------------------------------------------------------------
  // Library
  // -------------------------------------------------------------------------

  async list(params: ListParams): Promise<ListResult> {
    const link = this.require();
    const requestId = randomId('q');
    const response = link.waitForControl(
      (message) => message.type === 'list-response' && message.requestId === requestId,
      20_000,
    );
    link.sendControl({
      type: 'list-request',
      requestId,
      cursor: params.cursor ?? null,
      limit: params.limit ?? 40,
      ...(params.query ? { query: params.query } : {}),
    });
    const message = (await response) as Extract<ControlMessage, { type: 'list-response' }>;
    return { items: message.items, nextCursor: message.nextCursor };
  }

  /**
   * `post-text` carries a clientId but `item-new` does not echo it, so the
   * confirmation is matched on content instead. Text posts are small and
   * near-instant, which makes a collision window of a few hundred ms harmless.
   */
  async postText(text: string, kind: TextKind, clientId: string): Promise<Item> {
    const link = this.require();
    const confirmed = link.waitForControl(
      (message) => message.type === 'item-new' && message.item.text === text && message.item.kind === kind,
      15_000,
    );
    link.sendControl({ type: 'post-text', clientId, text, kind });
    const message = (await confirmed) as Extract<ControlMessage, { type: 'item-new' }>;
    return message.item;
  }

  async remove(itemId: string): Promise<void> {
    this.require().sendControl({ type: 'delete', itemId });
  }

  /**
   * There is no HTTP origin to point an `<img>` at on this tier — the NAS is
   * unreachable, which is why we are on WebRTC in the first place. The UI falls
   * back to fetching bytes over the DataChannel and making an object URL.
   */
  mediaUrl(): string | null {
    return null;
  }

  async fetchItemBlob(item: Item, onProgress?: (bytes: number) => void): Promise<Blob> {
    const link = this.require();
    const seq = newTransferSeq();
    const transferId = seqToTransferId(seq);
    const size = item.size ?? 0;

    const download: ActiveDownload = {
      seq,
      parts: new Array<Uint8Array | undefined>(chunkCount(size)),
      received: 0,
      expected: size || null,
      totalChunks: chunkCount(size),
      ...(onProgress ? { onProgress } : {}),
    };
    this.downloads.set(seq, download);

    try {
      const finished = link.waitForControl(
        (message) =>
          (message.type === 'download-complete' || message.type === 'download-error') &&
          message.transferId === transferId,
        10 * 60_000,
      );
      link.sendControl({ type: 'download-request', transferId, itemId: item.id, fromChunk: 0 });
      const result = await finished;
      if (result.type === 'download-error') {
        throw new TransportError(result.message, result.code === 'not-found' ? 'io-error' : 'io-error');
      }

      const parts = download.parts.filter((p): p is Uint8Array => p !== undefined);
      if (parts.length !== download.totalChunks) {
        throw new TransportError('The transfer finished with missing chunks', 'io-error');
      }
      const blob = new Blob(parts as BlobPart[], { type: item.mime ?? 'application/octet-stream' });

      if (result.type === 'download-complete') {
        const actual = await hashFile(blob);
        if (actual !== result.sha256) {
          throw new TransportError('Checksum mismatch — the file arrived corrupted', 'checksum-mismatch');
        }
      }
      return blob;
    } finally {
      this.downloads.delete(seq);
    }
  }

  // -------------------------------------------------------------------------
  // Upload
  // -------------------------------------------------------------------------

  async uploadFile(ctx: UploadContext): Promise<Item> {
    const link = this.require();

    const readyPromise = link.waitForControl(
      (message) =>
        (message.type === 'upload-ready' || message.type === 'upload-error') &&
        message.transferId === ctx.transferId,
      60_000,
    );
    link.sendControl({ type: 'upload-init', transferId: ctx.transferId, file: ctx.meta });
    const ready = await readyPromise;
    if (ready.type === 'upload-error') throw toTransportError(ready);
    if (ready.type !== 'upload-ready') throw new TransportError('Unexpected upload response', 'io-error');

    ctx.onReady({ haveChunks: ready.haveChunks, skipEntirely: ready.skipEntirely });

    const verified = link.waitForControl(
      (message) =>
        (message.type === 'upload-verified' || message.type === 'upload-error') &&
        message.transferId === ctx.transferId,
      10 * 60_000,
    );

    if (ready.skipEntirely) {
      // Content-addressed dedup: the NAS already has these bytes, so it only
      // needs to create the timeline entry. Nothing goes over the wire.
      ctx.onProgress(ctx.meta.size);
      const done = await verified;
      if (done.type === 'upload-error') throw toTransportError(done);
      return (done as Extract<ControlMessage, { type: 'upload-verified' }>).item;
    }

    // Acks drive resume: if the link drops we come back and re-init, and the
    // NAS replays whatever it actually committed. Tracking it locally too lets
    // the UI show a truthful "resumed at" figure.
    const acked = new Set<number>(ready.haveChunks);
    const unsubscribeAcks = this.subscribeAcks(ctx.transferId, (throughIndex) => {
      for (let i = 0; i <= throughIndex; i += 1) acked.add(i);
    });

    link.currentSeq = ctx.transferSeq;
    try {
      await pumpBlob(ctx.file, link, {
        skip: new Set(ready.haveChunks),
        gate: ctx.gate,
        signal: ctx.signal,
        onChunkQueued: (_index, bytesQueued) => {
          // Progress reflects bytes handed to the transport minus what is still
          // sitting in the send queue — otherwise the bar hits 100% while
          // megabytes are still draining.
          ctx.onProgress(Math.max(0, bytesQueued - link.bufferedAmount()));
        },
      });

      // Drain before declaring completion, or the NAS sees upload-complete
      // ahead of the tail chunks.
      await link.whenDrained();
      while (link.isOpen() && link.bufferedAmount() > 0) {
        await new Promise((resolve) => setTimeout(resolve, 50));
      }
      ctx.onProgress(ctx.meta.size);
      link.sendControl({ type: 'upload-complete', transferId: ctx.transferId, sha256: ctx.meta.sha256 });

      const done = await verified;
      if (done.type === 'upload-error') throw toTransportError(done);
      return (done as Extract<ControlMessage, { type: 'upload-verified' }>).item;
    } catch (error) {
      if (ctx.signal.aborted && link.isOpen()) {
        try {
          link.sendControl({ type: 'transfer-cancel', transferId: ctx.transferId, reason: 'user cancelled' });
        } catch {
          /* link already gone */
        }
      }
      throw error;
    } finally {
      unsubscribeAcks();
    }
  }

  private subscribeAcks(transferId: string, onAck: (throughIndex: number) => void): () => void {
    const listener = (message: ControlMessage): void => {
      if (message.type === 'upload-ack' && message.transferId === transferId) {
        onAck(message.throughIndex);
      }
    };
    this.ackListeners.add(listener);
    return () => this.ackListeners.delete(listener);
  }

  private readonly ackListeners = new Set<(message: ControlMessage) => void>();
}

function toTransportError(message: Extract<ControlMessage, { type: 'upload-error' }>): TransportError {
  const code =
    message.code === 'out-of-space' ? 'out-of-space'
    : message.code === 'checksum-mismatch' ? 'checksum-mismatch'
    : message.code === 'unauthorized' ? 'unauthorized'
    : message.code === 'cancelled' ? 'cancelled'
    : 'io-error';
  return new TransportError(message.message, code);
}

/** Bytes represented by a set of chunk indices for a file of `size` bytes. */
export function bytesForChunks(indices: Iterable<number>, size: number): number {
  let total = 0;
  for (const index of indices) {
    const start = index * CHUNK_SIZE;
    total += Math.max(0, Math.min(CHUNK_SIZE, size - start));
  }
  return total;
}
