import type { FileMeta, Item, ItemKind, TransportKind } from '@filedrop/shared';

/** Where the connection is in its lifecycle, independent of which tier won. */
export type ConnectionPhase =
  | 'idle' // nothing started yet
  | 'probing' // deciding which tier to use
  | 'connecting' // negotiating (signaling / ICE)
  | 'online' // ready for traffic
  | 'degraded' // connected, but on the last-resort tier
  | 'reconnecting'
  | 'offline'; // NAS unreachable on every tier

export interface ConnectionState {
  phase: ConnectionPhase;
  /** null until a tier is chosen. */
  kind: TransportKind | null;
  nasName: string | null;
  freeBytes: number | null;
  /** e.g. "host ↔ host" or "srflx ↔ relay" — the ICE candidate pair, if known. */
  path: string | null;
  /**
   * True once the DataChannel is carrying traffic and the signaling channel has
   * gone quiet. Surfaced in the UI because it is the whole point of the design:
   * signaling sets the call up, then gets out of the way.
   */
  signalingIdle: boolean;
  /** Round-trip time over the data path, from control-plane ping/pong. */
  rttMs: number | null;
  /** Non-fatal explanation shown in the connection popover. */
  note: string | null;
  error: string | null;
}

export const INITIAL_CONNECTION_STATE: ConnectionState = {
  phase: 'idle',
  kind: null,
  nasName: null,
  freeBytes: null,
  path: null,
  signalingIdle: false,
  rttMs: null,
  note: null,
  error: null,
};

export interface ListParams {
  cursor?: string | null;
  limit?: number;
  query?: string;
  signal?: AbortSignal;
}

export interface ListResult {
  items: Item[];
  nextCursor: string | null;
}

export type TextKind = Extract<ItemKind, 'text' | 'link' | 'clipboard'>;

/** Everything the UI needs to know about a single upload while it runs. */
export interface UploadContext {
  file: Blob;
  meta: FileMeta;
  transferId: string;
  transferSeq: number;
  /** Called once the NAS has answered upload-init. */
  onReady(ready: { haveChunks: number[]; skipEntirely: boolean }): void;
  /** Absolute bytes confirmed sent so far (not just this attempt). */
  onProgress(bytesDone: number): void;
  /** Resolves when the transfer is allowed to keep going; rejects on cancel. */
  gate: TransferGate;
  signal: AbortSignal;
}

/**
 * Pause/cancel coordination. The chunk pump awaits `wait()` at slice
 * boundaries, so a pause takes effect within one CHUNK_SIZE read rather than
 * requiring the whole transfer to unwind.
 */
export class TransferGate {
  private paused = false;
  private waiters: Array<() => void> = [];
  private listeners = new Set<(paused: boolean) => void>();

  pause(): void {
    if (this.paused) return;
    this.paused = true;
    for (const listener of this.listeners) listener(true);
  }

  resume(): void {
    if (!this.paused) return;
    this.paused = false;
    const waiters = this.waiters;
    this.waiters = [];
    for (const w of waiters) w();
    for (const listener of this.listeners) listener(false);
  }

  /**
   * Transports that cannot suspend a request mid-flight (the LAN tier uses one
   * long XHR) need to *react* to a pause by aborting and re-resuming later.
   */
  onChange(listener: (paused: boolean) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  get isPaused(): boolean {
    return this.paused;
  }

  async wait(): Promise<void> {
    if (!this.paused) return;
    await new Promise<void>((resolve) => this.waiters.push(resolve));
  }
}

export type TransportEvent =
  | { type: 'item-new'; item: Item }
  | { type: 'item-removed'; itemId: string }
  | { type: 'item-updated'; item: Item };

/**
 * The single surface the UI talks to. Three implementations
 * (lan-direct / p2p / signal-relay) satisfy it; `TransportManager` picks one
 * and re-picks it when conditions change.
 */
export interface Transport {
  readonly kind: TransportKind;
  getState(): ConnectionState;
  subscribeState(fn: (state: ConnectionState) => void): () => void;
  subscribeEvents(fn: (event: TransportEvent) => void): () => void;

  start(): Promise<void>;
  stop(): void;

  list(params: ListParams): Promise<ListResult>;
  postText(text: string, kind: TextKind, clientId: string): Promise<Item>;
  remove(itemId: string): Promise<void>;
  uploadFile(ctx: UploadContext): Promise<Item>;

  /**
   * URL usable directly as an `<img>`/`<video>` src, or null when this tier
   * cannot serve media by URL (P2P has no HTTP origin to point at).
   */
  mediaUrl(item: Item, variant: 'raw' | 'thumb'): string | null;
  /** Pull the bytes of an item; used for download and for P2P previews. */
  fetchItemBlob(item: Item, onProgress?: (bytes: number) => void): Promise<Blob>;
}

export class TransportError extends Error {
  constructor(
    message: string,
    readonly code:
      | 'unreachable'
      | 'unauthorized'
      | 'out-of-space'
      | 'checksum-mismatch'
      | 'cancelled'
      | 'unsupported'
      | 'io-error' = 'io-error',
  ) {
    super(message);
    this.name = 'TransportError';
  }
}
