import { useEffect, useState } from 'react';
import { hasBakedConfig, loadStandaloneConfig } from '../net/mode';
import { useAuth } from '../state/auth';
import { AlertIcon, LogoIcon, RefreshIcon } from './Icons';

/**
 * Standalone discovery: we have an App ID and a channel, and are waiting for a
 * `discover-ack` from a NAS on that channel.
 *
 * There is no other way to tell whether this is going to work — no HTTP probe
 * is available from an https page — so silence has to be explained rather than
 * left as a spinner. After a few seconds we start listing what silence could
 * actually mean.
 */

const PATIENCE_MS = 6000;

export function DiscoverScreen(): JSX.Element {
  const nasName = useAuth((state) => state.nas?.nasName ?? null);
  const discoverError = useAuth((state) => state.discoverError);
  const retryDiscovery = useAuth((state) => state.retryDiscovery);
  const forget = useAuth((state) => state.forget);
  const config = loadStandaloneConfig();
  /** Private builds bake App ID + channel; hide reconfiguration chrome. */
  const baked = hasBakedConfig();

  const [patienceUp, setPatienceUp] = useState(false);
  useEffect(() => {
    if (discoverError) return;
    setPatienceUp(false);
    const timer = setTimeout(() => setPatienceUp(true), PATIENCE_MS);
    return () => clearTimeout(timer);
  }, [discoverError]);

  const failed = discoverError !== null;
  /**
   * Agora's marker for "this project has an App Certificate, but you signed in
   * without a token". Matched on the detail string rather than code -10005,
   * which also covers genuinely malformed tokens.
   */
  const certificateEnabled = /DYNAMIC_ENABLED_BUT_STATIC_KEY/i.test(discoverError ?? '');

  return (
    <div className="pair">
      <div className="pair__panel">
        <div className="pair__brand">
          <LogoIcon />
          <strong>FileDrop</strong>
        </div>

        {failed ? (
          <>
            <h1>No NAS answered</h1>
            <p className="pair__lede">
              Joined the signaling channel, but nothing replied. That is all this page can tell from
              here — it has no other way to reach your NAS.
            </p>
            <p className="pair__error">{discoverError}</p>
          </>
        ) : (
          <>
            <h1>
              <span className="spinner discover__spinner" aria-hidden="true" />
              Looking for your NAS…
            </h1>
            <p className="pair__lede">
              Broadcasting on <code>{config?.channel ?? '—'}</code> and waiting for your NAS agent to
              answer.
            </p>
          </>
        )}

        {nasName && !failed ? <p className="pair__lede">Found {nasName}. Connecting…</p> : null}

        {/*
          Agora reports "certificate is enabled but we logged in without a token"
          as DYNAMIC_ENABLED_BUT_STATIC_KEY, which is both the single most likely
          setup mistake here and completely opaque unless you already know what
          it means. It has one exact fix, so say it plainly instead of listing
          three guesses that are all wrong.
        */}
        {certificateEnabled ? (
          <div className="discover__causes">
            <p className="discover__causes-title">
              <AlertIcon />
              App Certificate is still enabled
            </p>
            <p>
              A static page has nowhere safe to keep an App Certificate, so it signs in with the App
              ID alone. Your Agora project currently requires a token, and rejects that.
            </p>
            <p>
              Fix it in the <strong>Agora Console</strong> → your project → <strong>Config</strong> →
              disable the <strong>Primary Certificate</strong>, then try again.
            </p>
            <p className="discover__note">
              Your NAS still refuses to connect to any device that has not paired, so the pairing
              code remains what actually protects your files.
            </p>
          </div>
        ) : failed || patienceUp ? (
          <div className="discover__causes">
            <p className="discover__causes-title">
              <AlertIcon />
              Usually one of three things:
            </p>
            <ul>
              <li>
                The NAS agent is not running, or has no internet access to reach Agora signaling.
              </li>
              <li>
                The channel name here (<code className="mono">{config?.channel ?? '—'}</code>) does
                not match <code>AGORA_CHANNEL</code> on the NAS.
              </li>
              <li>The App ID here belongs to a different Agora project than the NAS uses.</li>
            </ul>
          </div>
        ) : null}

        <div className="discover__actions">
          <button type="button" className="btn" onClick={retryDiscovery}>
            <RefreshIcon />
            Try again
          </button>
          {!baked ? (
            <button type="button" className="btn btn--ghost" onClick={forget}>
              Change App ID / channel
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
}
