import { useRef, useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { usePushClipboard } from '../hooks/useIngest';
import { findUrls } from '../lib/format';
import { enqueueFiles } from '../net/transfer';
import { useItems } from '../state/items';
import { toast } from '../state/toasts';
import { ClipboardIcon, PaperclipIcon, SendIcon } from './Icons';

export function Composer(): JSX.Element {
  const sendText = useItems((state) => state.sendText);
  const pushClipboard = usePushClipboard();
  const [draft, setDraft] = useState('');
  const [sending, setSending] = useState(false);
  const textarea = useRef<HTMLTextAreaElement>(null);
  const picker = useRef<HTMLInputElement>(null);

  const grow = (element: HTMLTextAreaElement): void => {
    element.style.height = 'auto';
    element.style.height = `${Math.min(160, element.scrollHeight)}px`;
  };

  const send = async (): Promise<void> => {
    const text = draft.trim();
    if (!text || sending) return;
    // A message that is a single bare URL is stored as a link so the NAS (and
    // other devices) can render it as a card rather than a wall of text.
    const kind = findUrls(text).length === 1 && !/\s/.test(text) ? 'link' : 'text';
    setSending(true);
    setDraft('');
    if (textarea.current) textarea.current.style.height = 'auto';
    try {
      await sendText(text, kind);
    } catch {
      setDraft(text); // put it back rather than losing what they typed
      toast.error('Could not send — check the connection');
    } finally {
      setSending(false);
    }
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>): void => {
    if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) {
      event.preventDefault();
      void send();
    }
  };

  const onPick = (event: ChangeEvent<HTMLInputElement>): void => {
    const files = Array.from(event.target.files ?? []);
    if (files.length > 0) enqueueFiles(files);
    event.target.value = '';
  };

  const ready = draft.trim().length > 0;

  return (
    <div className="composer">
      <div className="composer__tools">
        <button
          type="button"
          className="icon-btn"
          onClick={() => picker.current?.click()}
          aria-label="Choose files"
          title="Choose files"
        >
          <PaperclipIcon />
        </button>
        <button
          type="button"
          className="icon-btn"
          onClick={() => void pushClipboard()}
          aria-label="Send clipboard to NAS"
          title="Send clipboard"
        >
          <ClipboardIcon />
        </button>
        <input ref={picker} type="file" multiple hidden onChange={onPick} />
      </div>

      <div className="composer__field">
        <textarea
          ref={textarea}
          value={draft}
          rows={1}
          placeholder="Message, link, or drop a file…"
          onChange={(event) => {
            setDraft(event.target.value);
            grow(event.target);
          }}
          onKeyDown={onKeyDown}
          aria-label="Message"
        />
      </div>

      <button
        type="button"
        className="composer__send"
        data-ready={ready}
        disabled={!ready || sending}
        onClick={() => void send()}
        aria-label="Send"
      >
        <SendIcon />
      </button>
    </div>
  );
}
