import { useEffect } from 'react';
import { AuthApproveScreen } from './components/AuthApproveScreen';
import { AuthRequestScreen } from './components/AuthRequestScreen';
import { DiscoverScreen } from './components/DiscoverScreen';
import { MainScreen } from './components/MainScreen';
import { PairScreen } from './components/PairScreen';
import { SetupScreen } from './components/SetupScreen';
import { useAuth } from './state/auth';

export function App(): JSX.Element | null {
  const status = useAuth((state) => state.status);
  const mode = useAuth((state) => state.mode);
  const boot = useAuth((state) => state.boot);

  useEffect(() => {
    boot();
  }, [boot]);

  switch (status) {
    // `booting` covers the deployment-mode decision, which may involve one
    // same-origin probe. Render nothing rather than flash the wrong screen.
    case 'booting':
      return null;
    case 'setup':
      return <SetupScreen />;
    case 'discovering':
      return <DiscoverScreen />;
    case 'approving':
      return <AuthApproveScreen />;
    case 'paired':
      return <MainScreen />;
    default:
      // Unpaired. The two deployments authorise a device completely differently:
      // hosted is reachable only from the LAN and uses a six-digit code typed
      // into the NAS-served page; standalone rides a public signaling channel,
      // where a guessable code would be the weak point, so it uses a QR the
      // owner approves in Telegram.
      return mode === 'standalone' ? <AuthRequestScreen /> : <PairScreen />;
  }
}
