import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { adoptConfigFromFragment } from './net/mode';
import './styles/app.css';

// Before anything renders or reads config: pick up `#appId=…&channel=…` from a
// preconfigured bookmark, persist it, and scrub it back out of the address bar.
adoptConfigFromFragment();

const container = document.getElementById('root');
if (!container) throw new Error('#root is missing from index.html');

createRoot(container).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
