/**
 * FileDrop wire protocol — shared contract between the browser client and the NAS agent.
 *
 * Two separate channels carry traffic:
 *
 *   1. SIGNALING (Agora RTM, or the NAS-hosted WebSocket on LAN)
 *      Carries ONLY the WebRTC handshake: SDP offer/answer + ICE candidates.
 *      A few KB total, once per connection. No file data ever crosses it.
 *
 *   2. DATA (WebRTC DataChannel, peer-to-peer)
 *      Carries everything else: control JSON + binary file chunks.
 *      Established via (1), then runs independently. If the peer connection
 *      drops, we re-run (1) and resume the transfer where it left off.
 */
export const PROTOCOL_VERSION = 1;
/** DataChannel messages larger than this risk being dropped by some stacks. */
export const MAX_DC_MESSAGE = 262144; // 256 KiB
/** Payload bytes per chunk. Leaves room for the binary header under the cap. */
export const CHUNK_SIZE = 65536; // 64 KiB
/** Pause reading the file when the DataChannel has this many bytes queued. */
export const BUFFER_HIGH_WATER = 8 * 1024 * 1024;
/** Resume reading once the queue drains below this. */
export const BUFFER_LOW_WATER = 1 * 1024 * 1024;
/**
 * Envelope `to` value meaning "any NAS listening on this channel".
 *
 * A remote client knows the channel but not the NAS's peer id, so `discover`
 * is addressed here and the NAS answers with its real id. Every later message
 * is addressed directly.
 */
export const BROADCAST = '*';
/**
 * Remote pairing codes are alphanumeric and longer than the 6-digit LAN code.
 *
 * The LAN code is only reachable by someone already on your network; a remote
 * code can be attempted by anyone who joins the signaling channel, and six
 * digits is a million guesses. Crockford's base32 (no I/L/O/U) avoids the
 * character pairs people misread when copying a code off a screen.
 */
export const PAIR_CODE_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
export const REMOTE_PAIR_CODE_LENGTH = 10;
/** Attempts a device gets before it is blocked outright. */
export const AUTH_MAX_ATTEMPTS = 10;
/** How long an unanswered request stays live. */
export const AUTH_REQUEST_TTL_MS = 10 * 60 * 1000;
/** Granted device tokens last exactly this long — hard expiry, no renewal. */
export const AUTH_TOKEN_TTL_DAYS = 7;
/** Fragment key the scanning device reads: `#auth=<requestId>.<secret>`. */
export const AUTH_FRAGMENT_KEY = 'auth';
/** Build the QR payload. `origin` is the UI's own origin, never the NAS's. */
export function buildAuthUrl(origin, requestId, secret) {
    const base = origin.endsWith('/') ? origin : `${origin}/`;
    return `${base}#${AUTH_FRAGMENT_KEY}=${requestId}.${secret}`;
}
/** Inverse of {@link buildAuthUrl}. Returns null when the fragment is absent or malformed. */
export function parseAuthFragment(hash) {
    const raw = hash.replace(/^#/, '');
    if (!raw)
        return null;
    let value = null;
    try {
        value = new URLSearchParams(raw).get(AUTH_FRAGMENT_KEY);
    }
    catch {
        return null;
    }
    if (!value)
        return null;
    const dot = value.indexOf('.');
    if (dot <= 0 || dot === value.length - 1)
        return null;
    return { requestId: value.slice(0, dot), secret: value.slice(dot + 1) };
}
/** Normalise user input before comparing: strip separators, upcase, fix look-alikes. */
export function normalizePairCode(input) {
    return input
        .toUpperCase()
        .replace(/[\s-]/g, '')
        .replace(/[IL]/g, '1')
        .replace(/O/g, '0')
        .replace(/U/g, 'V');
}
// ---------------------------------------------------------------------------
// Data channel — binary chunk frames
// ---------------------------------------------------------------------------
/**
 * Binary frame layout (little-endian), sent as an ArrayBuffer on the DataChannel:
 *
 *   offset  size  field
 *   0       4     magic 0x46445254 ("FDRT")
 *   4       4     transferSeq  — numeric handle assigned in upload-ready/download-init
 *   8       4     chunkIndex
 *   12      4     payloadLength
 *   16      n     payload
 *
 * A 16-byte header keeps the whole frame under CHUNK_SIZE + 16, comfortably
 * inside MAX_DC_MESSAGE on every stack we target.
 */
export const CHUNK_MAGIC = 0x46445254;
export const CHUNK_HEADER_BYTES = 16;
export function encodeChunk(transferSeq, chunkIndex, payload) {
    const buf = new ArrayBuffer(CHUNK_HEADER_BYTES + payload.byteLength);
    const view = new DataView(buf);
    view.setUint32(0, CHUNK_MAGIC, true);
    view.setUint32(4, transferSeq, true);
    view.setUint32(8, chunkIndex, true);
    view.setUint32(12, payload.byteLength, true);
    new Uint8Array(buf, CHUNK_HEADER_BYTES).set(payload);
    return buf;
}
/** Returns null if the buffer is not a well-formed chunk frame. */
export function decodeChunk(buf) {
    if (buf.byteLength < CHUNK_HEADER_BYTES)
        return null;
    const view = new DataView(buf);
    if (view.getUint32(0, true) !== CHUNK_MAGIC)
        return null;
    const payloadLength = view.getUint32(12, true);
    if (buf.byteLength !== CHUNK_HEADER_BYTES + payloadLength)
        return null;
    return {
        transferSeq: view.getUint32(4, true),
        chunkIndex: view.getUint32(8, true),
        payload: new Uint8Array(buf, CHUNK_HEADER_BYTES, payloadLength),
    };
}
export function isFileKind(kind) {
    return kind === 'file' || kind === 'image' || kind === 'video' || kind === 'audio';
}
export function kindForMime(mime) {
    if (mime.startsWith('image/'))
        return 'image';
    if (mime.startsWith('video/'))
        return 'video';
    if (mime.startsWith('audio/'))
        return 'audio';
    return 'file';
}
