import { useEffect } from 'react';
import { useAuth } from '../state/auth';
import { AlertIcon, CheckIcon, LogoIcon, RefreshIcon } from './Icons';

/**
 * After opening a QR / 复制链接: notify Telegram, then poll every 0.5s.
 * If this browser is the one that asked for access, TG 通过后自动进入主界面。
 * Never auto-jump back to a new QR — that was the phone “又跳回二维码” bug.
 */
export function AuthApproveScreen(): JSX.Element {
  const nasName = useAuth((state) => state.nas?.nasName ?? null);
  const state = useAuth((state) => state.approvalState);
  const error = useAuth((state) => state.approvalError);
  const authState = useAuth((state) => state.authState);
  const session = useAuth((state) => state.session);
  const sendApproval = useAuth((state) => state.sendApproval);
  const dismissApproval = useAuth((state) => state.dismissApproval);

  // When poll succeeds, status becomes `paired` and App switches away.
  // Soft visual tick only — real work is in auth store schedulePoll(500ms).
  useEffect(() => {
    if (state !== 'sent' || session) return;
    const id = window.setInterval(() => {
      /* re-render when zustand updates; interval keeps “checking…” honest */
    }, 500);
    return () => window.clearInterval(id);
  }, [state, session]);

  const waitingTg = state === 'sent' && !session;
  const statusLine =
    authState === 'approved' ? '已通过，正在进入…'
    : authState === 'notified' || state === 'sent' ? '已通知 · 等待 Telegram 通过（每 0.5 秒检查）…'
    : authState === 'rejected' ? '已拒绝'
    : authState === 'expired' ? '请求已过期'
    : null;

  return (
    <div className="pair">
      <div className="pair__panel">
        <div className="pair__brand">
          <LogoIcon />
          <strong>FileDrop</strong>
        </div>

        {state === 'sending' ?
          <>
            <h1>
              <span className="spinner discover__spinner" aria-hidden="true" />
              正在通知 NAS…
            </h1>
            <p className="pair__lede">正在把访问申请发给 {nasName ?? 'NAS'}。</p>
          </>
        : state === 'sent' ?
          <>
            <h1>{session ? '授权成功' : '请在 Telegram 点通过'}</h1>
            <p className="pair__lede">
              已通知 <strong>{nasName ?? 'NAS'}</strong>。请在 Telegram 里点
              <strong> 同意</strong>。本页会自动检测，通过后直接进入，无需再扫码。
            </p>
            {statusLine ?
              <p className="auth__status" data-tone={session || authState === 'approved' ? 'ok' : 'live'}>
                {session || authState === 'approved' ?
                  <CheckIcon />
                : <span className="spinner discover__spinner" aria-hidden="true" />}
                {session ? '已授权，正在进入…' : statusLine}
              </p>
            : null}
            <p className="pair__hint">
              若这是<strong>另一台设备</strong>的二维码，通过后授权的是那台设备，不是本机。
              本机要单独进 FileDrop 时再点下方「申请本机访问」。
            </p>
          </>
        : <>
            <h1>无法通知 NAS</h1>
            <p className="pair__lede">链接可能已过期，或当前连不上信令。</p>
            <p className="pair__error">
              <AlertIcon />
              {error ?? 'NAS 无应答'}
            </p>
            <button
              type="button"
              className="btn btn--accent"
              style={{ width: '100%', height: 40 }}
              onClick={sendApproval}
            >
              <RefreshIcon />
              重试
            </button>
          </>
        }

        {waitingTg ? null : (
          <button
            type="button"
            className="btn btn--sm btn--ghost pair__reset"
            onClick={dismissApproval}
          >
            {session ? '进入 FileDrop' : '申请本机访问（新二维码）'}
          </button>
        )}

        {waitingTg ?
          <button
            type="button"
            className="btn btn--sm btn--ghost pair__reset"
            onClick={dismissApproval}
          >
            不要等了，改为申请本机访问
          </button>
        : null}
      </div>
    </div>
  );
}
