import {
  PROTOCOL_VERSION,
  type BootstrapResponse,
  type SignalEnvelope,
  type SignalPayload,
} from '@filedrop/shared';
import { signalSocketUrl } from './api';

/**
 * Signaling is the *only* thing that ever touches a third party, and it only
 * ever carries the WebRTC handshake — a few KB, once. Two implementations:
 *
 *   ws    — the NAS's own WebSocket. Free, private, but requires the NAS to be
 *           reachable, so it is only useful on the LAN or through a public
 *           reverse proxy.
 *   agora — Agora Signaling (RTM). Used when the NAS is not reachable at all,
 *           which is exactly the case the whole P2P tier exists for.
 *
 * Both are addressed with the same `SignalEnvelope`, so the peer-connection
 * code above does not care which one it got.
 */
export interface SignalingChannel {
  readonly name: 'ws' | 'agora';
  connect(): Promise<void>;
  /** `to` overrides the channel's current peer — used to address BROADCAST. */
  send(payload: SignalPayload, to?: string): Promise<void>;
  close(): void;
  /**
   * Aim an already-connected channel at a (new) peer and negotiation session.
   *
   * Standalone mode discovers the NAS's peer id over the very channel it will
   * later negotiate on, so the channel outlives any single `peerId`.
   */
  retarget?(peerId: string, session: string): void;
  onEnvelope: ((envelope: SignalEnvelope) => void) | null;
  onClosed: ((reason: string) => void) | null;
}

export interface ChannelIdentity {
  selfId: string;
  peerId: string;
  session: string;
}

function envelope(identity: ChannelIdentity, payload: SignalPayload, to?: string): SignalEnvelope {
  return {
    v: PROTOCOL_VERSION,
    from: identity.selfId,
    to: to ?? identity.peerId,
    session: identity.session,
    ts: Date.now(),
    payload,
  };
}

/** Envelopes and library push messages share the socket; discriminate on shape. */
export function isSignalEnvelope(value: unknown): value is SignalEnvelope {
  return (
    typeof value === 'object' &&
    value !== null &&
    'payload' in value &&
    'session' in value &&
    typeof (value as SignalEnvelope).payload === 'object'
  );
}

// ---------------------------------------------------------------------------
// NAS WebSocket
// ---------------------------------------------------------------------------

export class WsSignaling implements SignalingChannel {
  readonly name = 'ws' as const;
  onEnvelope: ((envelope: SignalEnvelope) => void) | null = null;
  onClosed: ((reason: string) => void) | null = null;

  private socket: WebSocket | null = null;

  constructor(
    private readonly identity: ChannelIdentity,
    private readonly path: string,
  ) {}

  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      const socket = new WebSocket(signalSocketUrl(this.path));
      this.socket = socket;
      const timer = setTimeout(() => {
        socket.close();
        reject(new Error('Signaling socket timed out'));
      }, 8000);

      socket.addEventListener('open', () => {
        clearTimeout(timer);
        resolve();
      });
      socket.addEventListener('error', () => {
        clearTimeout(timer);
        reject(new Error('Signaling socket failed'));
      });
      socket.addEventListener('close', (event) => {
        clearTimeout(timer);
        this.onClosed?.(event.reason || 'socket closed');
      });
      socket.addEventListener('message', (event) => {
        if (typeof event.data !== 'string') return;
        try {
          const parsed: unknown = JSON.parse(event.data);
          if (isSignalEnvelope(parsed) && parsed.to === this.identity.selfId) {
            this.onEnvelope?.(parsed);
          }
        } catch {
          /* ignore malformed frames */
        }
      });
    });
  }

  async send(payload: SignalPayload, to?: string): Promise<void> {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
      throw new Error('Signaling socket is not open');
    }
    this.socket.send(JSON.stringify(envelope(this.identity, payload, to)));
  }

  retarget(peerId: string, session: string): void {
    this.identity.peerId = peerId;
    this.identity.session = session;
  }

  close(): void {
    this.onClosed = null;
    this.socket?.close();
    this.socket = null;
  }
}

// ---------------------------------------------------------------------------
// Agora Signaling (RTM v2)
// ---------------------------------------------------------------------------

/**
 * Minimal structural view of the bits of the RTM SDK we use. Typing it here
 * rather than importing the SDK's types keeps the dynamic import at the module
 * boundary — the ~200 KB SDK is never fetched on the LAN path.
 */
interface RtmMessageEvent {
  channelName: string;
  publisher: string;
  message: string | Uint8Array;
}
interface RtmClient {
  login(options?: { token?: string }): Promise<unknown>;
  logout(): Promise<unknown>;
  subscribe(channel: string, options?: { withMessage?: boolean; withPresence?: boolean }): Promise<unknown>;
  publish(channel: string, message: string, options?: { channelType?: 'MESSAGE' | 'USER' }): Promise<unknown>;
  addEventListener(event: 'message', listener: (event: RtmMessageEvent) => void): void;
  addEventListener(event: 'status', listener: (event: { state: string; reason?: string }) => void): void;
}

export type AgoraCredentials = NonNullable<BootstrapResponse['signaling']['agora']>;

/**
 * What `AgoraSignaling` actually needs. Looser than `AgoraCredentials` because
 * of the standalone path, where `token` is absent.
 *
 * **App-ID-only auth, and its tradeoff.** A token-authenticated RTM login is
 * minted by a server that already knows who you are; standalone mode has no
 * server it can reach over HTTP (that is the whole problem), so it logs in with
 * the App ID alone. That means anyone who learns the App ID *and* the channel
 * name can join the channel and see signaling envelopes fly past. What they
 * cannot do is: read any file data (it never leaves the DataChannel), or pair
 * (they must also produce a 10-character code that the NAS rate-limits and
 * expires). Discovery/pairing is therefore the only pre-auth surface, and the
 * channel name doubles as a weak shared secret — pick an unguessable one.
 */
export interface AgoraChannelConfig {
  appId: string;
  channel: string;
  uid: string;
  /** Omitted in App-ID-only (standalone) mode. */
  token?: string;
}

export class AgoraSignaling implements SignalingChannel {
  readonly name = 'agora' as const;
  onEnvelope: ((envelope: SignalEnvelope) => void) | null = null;
  onClosed: ((reason: string) => void) | null = null;

  private client: RtmClient | null = null;
  /**
   * Extra addresses we answer to. After pairing, the NAS may address us by the
   * `deviceId` it assigned rather than the peer id we introduced ourselves
   * with; accepting both avoids dropping a reply over a bookkeeping detail.
   */
  private readonly selfAliases = new Set<string>();

  constructor(
    private readonly identity: ChannelIdentity,
    private readonly credentials: AgoraChannelConfig,
  ) {}

  /** True when this envelope is addressed to us under any of our ids. */
  private addressedToUs(to: string): boolean {
    return to === this.identity.selfId || this.selfAliases.has(to);
  }

  /**
   * Whether an inbound RTM message belongs to this client: either it came over
   * our channel, or it was a direct peer message addressed to our uid (in which
   * case the SDK puts the recipient uid in `channelName`).
   */
  private isOurs(channelName: string): boolean {
    return (
      channelName === this.credentials.channel ||
      channelName === this.credentials.uid ||
      this.addressedToUs(channelName)
    );
  }

  addSelfAlias(id: string): void {
    if (id) this.selfAliases.add(id);
  }

  retarget(peerId: string, session: string): void {
    this.identity.peerId = peerId;
    this.identity.session = session;
  }

  async connect(): Promise<void> {
    const module = await import('agora-rtm');
    const RTM = (module.default as unknown as { RTM: new (appId: string, uid: string, config?: object) => RtmClient }).RTM;
    const client = new RTM(this.credentials.appId, this.credentials.uid, {
      logLevel: 'error',
      logUpload: false,
      // The handshake is a handful of small text messages; presence just adds
      // traffic and another failure mode we would have to interpret.
      presenceTimeout: 30,
    });
    this.client = client;

    client.addEventListener('message', (event) => {
      // Two delivery shapes arrive here and BOTH matter:
      //
      //   channelType 'MESSAGE' — published to the channel; `channelName` is
      //                           the channel. Used for our outbound requests.
      //   channelType 'USER'    — a direct peer message; the SDK reports
      //                           `channelName` as the *recipient uid*, not the
      //                           channel. The NAS answers `discover-ack`,
      //                           `pair-response`, `pair-error` and
      //                           `bootstrap-response` this way, so filtering
      //                           on the channel name alone silently drops
      //                           every reply we care about.
      //
      // The envelope's own `to` field is the real authorisation check below;
      // this test only rejects traffic that plainly belongs to someone else.
      if (!this.isOurs(event.channelName)) return;
      const text = typeof event.message === 'string' ? event.message : new TextDecoder().decode(event.message);
      try {
        const parsed: unknown = JSON.parse(text);
        if (isSignalEnvelope(parsed) && this.addressedToUs(parsed.to)) {
          this.onEnvelope?.(parsed);
        }
      } catch {
        /* not ours */
      }
    });
    client.addEventListener('status', (event) => {
      if (event.state === 'FAILED' || event.state === 'DISCONNECTED') {
        this.onClosed?.(event.reason ?? event.state);
      }
    });

    // App-ID-only login.
    //
    // The NAS signals "log in without a token" by sending `token: ''` in the
    // bootstrap `agora` block (it used to omit the block entirely, which hid a
    // working remote path from LAN-paired devices). Standalone mode has no
    // bootstrap at all and simply never sets one.
    //
    // Both cases must call `login()` with NO `token` key whatsoever: some SDK
    // builds reject an explicitly-present `undefined`, and `''` is not a valid
    // token. So branch on the call itself rather than building an options
    // object with a conditional property.
    const token = this.credentials.token?.trim();
    await (token ? client.login({ token }) : client.login());
    await client.subscribe(this.credentials.channel, { withMessage: true, withPresence: false });
  }

  async send(payload: SignalPayload, to?: string): Promise<void> {
    if (!this.client) throw new Error('Agora signaling is not connected');
    await this.client.publish(
      this.credentials.channel,
      JSON.stringify(envelope(this.identity, payload, to)),
      { channelType: 'MESSAGE' },
    );
  }

  close(): void {
    this.onClosed = null;
    const client = this.client;
    this.client = null;
    // Fire-and-forget: nothing downstream depends on a clean RTM logout, and
    // awaiting it would delay tearing the peer connection down.
    void client?.logout().catch(() => undefined);
  }
}

export function createSignalingChannel(
  identity: ChannelIdentity,
  bootstrap: BootstrapResponse,
  preferAgora: boolean,
): SignalingChannel {
  const agora = bootstrap.signaling.agora;
  if (preferAgora && agora) return new AgoraSignaling(identity, agora);
  return new WsSignaling(identity, bootstrap.signaling.ws || '/ws/signal');
}
