/**
 * A minimal QR Code encoder — byte mode only, versions 1–12.
 *
 * WHY this is hand-rolled instead of `npm i qrcode`: the standalone build is a
 * static bundle published from a public repository, and every dependency added
 * here is another package a user has to trust in the artifact that handles
 * their device authorisation. The subset we actually need — one byte-mode
 * segment, one error-correction level, a URL of ~60–110 characters — is a few
 * hundred lines, so the dependency buys nothing but supply-chain surface.
 *
 * Scope: byte mode, EC levels L/M/Q/H, versions 1–12 (up to 321 bytes at level
 * M). That covers every authorisation URL this app can produce with room to
 * spare; anything longer throws rather than silently truncating.
 *
 * The implementation follows ISO/IEC 18004. It is verified module-for-module
 * against an independent reference encoder (`segno`) across all supported
 * versions, EC levels and all eight mask patterns — see the accompanying
 * verification notes. A QR that renders but does not decode is worse than no QR
 * at all, so nothing here is "probably right".
 */

export type QrEcLevel = 'L' | 'M' | 'Q' | 'H';

export interface QrCode {
  /** Side length in modules, excluding the quiet zone. */
  size: number;
  version: number;
  ecLevel: QrEcLevel;
  mask: number;
  /** `modules[y][x]` — true is dark. */
  modules: boolean[][];
}

/** Highest version this encoder implements. */
export const QR_MAX_VERSION = 12;

/**
 * Per (version, EC level): [error-correction codewords per block, block count].
 *
 * Deliberately only these two numbers rather than the full ISO table of group
 * sizes: the group split is *derived* from them (see `blockLayout`), which
 * removes ~200 hand-transcribed integers — and every one of those would have
 * been a silent-corruption bug waiting to happen.
 */
const EC_TABLE: Record<QrEcLevel, ReadonlyArray<readonly [number, number]>> = {
  //     v1       v2       v3       v4       v5       v6       v7       v8       v9      v10      v11      v12
  L: [[7, 1], [10, 1], [15, 1], [20, 1], [26, 1], [18, 2], [20, 2], [24, 2], [30, 2], [18, 4], [20, 4], [24, 4]],
  M: [[10, 1], [16, 1], [26, 1], [18, 2], [24, 2], [16, 4], [18, 4], [22, 4], [22, 5], [26, 5], [30, 5], [22, 8]],
  Q: [[13, 1], [22, 1], [18, 2], [26, 2], [18, 4], [24, 4], [18, 6], [22, 6], [20, 8], [24, 8], [28, 8], [26, 10]],
  H: [[17, 1], [28, 1], [22, 2], [16, 4], [22, 4], [28, 4], [26, 5], [26, 6], [24, 8], [28, 8], [24, 11], [28, 11]],
};

const EC_LEVEL_BITS: Record<QrEcLevel, number> = { L: 1, M: 0, Q: 3, H: 2 };

const PENALTY_N1 = 3;
const PENALTY_N2 = 3;
const PENALTY_N3 = 40;
const PENALTY_N4 = 10;

// ---------------------------------------------------------------------------
// Capacity
// ---------------------------------------------------------------------------

/** Total codewords (data + EC) a version holds, from the module-count formula. */
function totalCodewords(version: number): number {
  let modules = (16 * version + 128) * version + 64;
  if (version >= 2) {
    const alignCount = Math.floor(version / 7) + 2;
    modules -= (25 * alignCount - 10) * alignCount - 55;
  }
  if (version >= 7) modules -= 36;
  return Math.floor(modules / 8);
}

function ecEntry(version: number, ec: QrEcLevel): readonly [number, number] {
  const entry = EC_TABLE[ec][version - 1];
  if (!entry) throw new Error(`qr: unsupported version ${String(version)}`);
  return entry;
}

interface BlockLayout {
  blocks: number;
  ecPerBlock: number;
  totalData: number;
  shortLen: number;
  shortCount: number;
}

/**
 * ISO splits each version's data codewords into at most two group sizes that
 * differ by exactly one, so the split falls straight out of a division.
 */
function blockLayout(version: number, ec: QrEcLevel): BlockLayout {
  const [ecPerBlock, blocks] = ecEntry(version, ec);
  const totalData = totalCodewords(version) - ecPerBlock * blocks;
  const shortLen = Math.floor(totalData / blocks);
  const longCount = totalData % blocks;
  return { blocks, ecPerBlock, totalData, shortLen, shortCount: blocks - longCount };
}

/** Character-count field width for byte mode. */
function charCountBits(version: number): number {
  return version <= 9 ? 8 : 16;
}

/** Payload bytes that fit at this version/level, after mode + count overhead. */
export function qrByteCapacity(version: number, ec: QrEcLevel): number {
  const { totalData } = blockLayout(version, ec);
  return totalData - 1 - charCountBits(version) / 8;
}

// ---------------------------------------------------------------------------
// GF(256) / Reed–Solomon
// ---------------------------------------------------------------------------

const GF_EXP = new Uint8Array(512);
const GF_LOG = new Uint8Array(256);
{
  let x = 1;
  for (let i = 0; i < 255; i += 1) {
    GF_EXP[i] = x;
    GF_LOG[x] = i;
    // Multiply by 2 in GF(2^8) with the QR primitive polynomial x^8+x^4+x^3+x^2+1.
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i += 1) GF_EXP[i] = GF_EXP[i - 255] ?? 0;
}

function gfMul(a: number, b: number): number {
  if (a === 0 || b === 0) return 0;
  return GF_EXP[((GF_LOG[a] ?? 0) + (GF_LOG[b] ?? 0)) % 255] ?? 0;
}

/**
 * Generator polynomial (x-α⁰)(x-α¹)…(x-α^(degree-1)), coefficients high-order
 * first — the order `rsRemainder` consumes them in.
 */
function rsGenerator(degree: number): Uint8Array {
  // Built low-order first because that is the natural direction for polynomial
  // multiplication, then reversed once at the end.
  let poly = new Uint8Array([1]);
  for (let i = 0; i < degree; i += 1) {
    const next = new Uint8Array(poly.length + 1);
    for (let j = 0; j < poly.length; j += 1) {
      const coefficient = poly[j] ?? 0;
      next[j] = (next[j] ?? 0) ^ gfMul(coefficient, GF_EXP[i] ?? 0);
      next[j + 1] = (next[j + 1] ?? 0) ^ coefficient;
    }
    poly = next;
  }
  return poly.reverse();
}

function rsRemainder(data: Uint8Array, generator: Uint8Array): Uint8Array {
  const degree = generator.length - 1;
  const remainder = new Uint8Array(degree);
  for (const byte of data) {
    const factor = byte ^ (remainder[0] ?? 0);
    remainder.copyWithin(0, 1);
    remainder[degree - 1] = 0;
    for (let i = 0; i < degree; i += 1) {
      remainder[i] = (remainder[i] ?? 0) ^ gfMul(generator[i + 1] ?? 0, factor);
    }
  }
  return remainder;
}

// ---------------------------------------------------------------------------
// Bit buffer
// ---------------------------------------------------------------------------

class BitBuffer {
  readonly bits: number[] = [];

  push(value: number, length: number): void {
    for (let i = length - 1; i >= 0; i -= 1) this.bits.push((value >>> i) & 1);
  }

  get length(): number {
    return this.bits.length;
  }
}

// ---------------------------------------------------------------------------
// Codeword assembly
// ---------------------------------------------------------------------------

function buildCodewords(bytes: Uint8Array, version: number, ec: QrEcLevel): Uint8Array {
  const layout = blockLayout(version, ec);
  const capacityBits = layout.totalData * 8;

  const buffer = new BitBuffer();
  buffer.push(0b0100, 4); // byte mode
  buffer.push(bytes.length, charCountBits(version));
  for (const byte of bytes) buffer.push(byte, 8);

  if (buffer.length > capacityBits) {
    throw new Error('qr: payload does not fit the chosen version');
  }

  // Terminator, then pad to a codeword boundary, then the fixed alternating
  // pad bytes the spec mandates (0xEC / 0x11).
  buffer.push(0, Math.min(4, capacityBits - buffer.length));
  buffer.push(0, (8 - (buffer.length % 8)) % 8);
  for (let pad = 0xec; buffer.length < capacityBits; pad ^= 0xec ^ 0x11) buffer.push(pad, 8);

  const data = new Uint8Array(layout.totalData);
  for (let i = 0; i < data.length; i += 1) {
    let byte = 0;
    for (let b = 0; b < 8; b += 1) byte = (byte << 1) | (buffer.bits[i * 8 + b] ?? 0);
    data[i] = byte;
  }

  // Split into blocks, compute each block's EC, then interleave: all first
  // data codewords, all second, … then the same for the EC codewords. The
  // interleaving is what lets a localised smudge damage one codeword per block
  // instead of destroying a single block outright.
  const generator = rsGenerator(layout.ecPerBlock);
  const dataBlocks: Uint8Array[] = [];
  const ecBlocks: Uint8Array[] = [];
  let offset = 0;
  for (let b = 0; b < layout.blocks; b += 1) {
    const length = layout.shortLen + (b < layout.shortCount ? 0 : 1);
    const block = data.subarray(offset, offset + length);
    offset += length;
    dataBlocks.push(block);
    ecBlocks.push(rsRemainder(block, generator));
  }

  const out = new Uint8Array(totalCodewords(version));
  let cursor = 0;
  const longLen = layout.shortLen + 1;
  for (let i = 0; i < longLen; i += 1) {
    for (const block of dataBlocks) {
      if (i < block.length) out[cursor++] = block[i] ?? 0;
    }
  }
  for (let i = 0; i < layout.ecPerBlock; i += 1) {
    for (const block of ecBlocks) out[cursor++] = block[i] ?? 0;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Matrix
// ---------------------------------------------------------------------------

function alignmentPositions(version: number): number[] {
  if (version === 1) return [];
  const count = Math.floor(version / 7) + 2;
  const size = version * 4 + 17;
  const step = version === 32 ? 26 : Math.ceil((version * 4 + 4) / (count * 2 - 2)) * 2;
  const positions = [6];
  for (let pos = size - 7; positions.length < count; pos -= step) positions.splice(1, 0, pos);
  return positions;
}

/** 15-bit BCH(15,5) format information, already XOR-masked with 0x5412. */
function formatBits(ec: QrEcLevel, mask: number): number {
  const data = (EC_LEVEL_BITS[ec] << 3) | mask;
  let rest = data << 10;
  for (let i = 14; i >= 10; i -= 1) {
    if ((rest >>> i) & 1) rest ^= 0x537 << (i - 10);
  }
  return ((data << 10) | rest) ^ 0x5412;
}

/** 18-bit BCH(18,6) version information. Only present from version 7 up. */
function versionBits(version: number): number {
  let rest = version << 12;
  for (let i = 17; i >= 12; i -= 1) {
    if ((rest >>> i) & 1) rest ^= 0x1f25 << (i - 12);
  }
  return (version << 12) | rest;
}

function maskAt(mask: number, x: number, y: number): boolean {
  switch (mask) {
    case 0:
      return (x + y) % 2 === 0;
    case 1:
      return y % 2 === 0;
    case 2:
      return x % 3 === 0;
    case 3:
      return (x + y) % 3 === 0;
    case 4:
      return (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0;
    case 5:
      return ((x * y) % 2) + ((x * y) % 3) === 0;
    case 6:
      return (((x * y) % 2) + ((x * y) % 3)) % 2 === 0;
    default:
      return (((x + y) % 2) + ((x * y) % 3)) % 2 === 0;
  }
}

/** The dark:light:dark:dark:dark:light:dark core of a finder pattern. */
const FINDER_RUN = [true, false, true, true, true, false, true];

/**
 * Penalty rule 3 over one row or column.
 *
 * The "light area 4 modules wide" is clamped at the symbol edge rather than
 * required to be inside it — a pattern flush against the border has the quiet
 * zone next to it, which is exactly as misleading to a scanner. zxing, segno
 * and Nayuki all read the spec this way.
 */
function finderLikePenalty(line: boolean[]): number {
  const n = line.length;
  const matchesAt = (start: number): boolean =>
    FINDER_RUN.every((value, offset) => line[start + offset] === value);
  const allLight = (from: number, to: number): boolean => {
    for (let i = Math.max(from, 0); i < Math.min(to, n); i += 1) if (line[i]) return false;
    return true;
  };

  let score = 0;
  let index = 0;
  while (index + 7 <= n) {
    if (!matchesAt(index)) {
      index += 1;
      continue;
    }
    if (allLight(index - 4, index) || allLight(index + 7, index + 11)) {
      score += PENALTY_N3;
      index += 7;
    } else {
      // The three dark modules in the middle can start another candidate, so
      // resume from there rather than skipping the whole run.
      index += 4;
    }
  }
  return score;
}

class Matrix {
  readonly size: number;
  readonly modules: boolean[][];
  /** Function patterns are never masked and never carry data. */
  readonly reserved: boolean[][];

  constructor(readonly version: number) {
    this.size = version * 4 + 17;
    this.modules = Array.from({ length: this.size }, () =>
      Array.from<boolean>({ length: this.size }).fill(false),
    );
    this.reserved = Array.from({ length: this.size }, () =>
      Array.from<boolean>({ length: this.size }).fill(false),
    );
  }

  private set(x: number, y: number, dark: boolean, reserve = true): void {
    const row = this.modules[y];
    const mark = this.reserved[y];
    if (!row || !mark) return;
    row[x] = dark;
    if (reserve) mark[x] = true;
  }

  get(x: number, y: number): boolean {
    return this.modules[y]?.[x] ?? false;
  }

  isReserved(x: number, y: number): boolean {
    return this.reserved[y]?.[x] ?? false;
  }

  drawFunctionPatterns(): void {
    const last = this.size - 7;
    for (const [ox, oy] of [
      [0, 0],
      [last, 0],
      [0, last],
    ] as Array<[number, number]>) {
      this.drawFinder(ox, oy);
    }
    // Separators: the one-module light ring around each finder.
    for (const [ox, oy] of [
      [0, 0],
      [last, 0],
      [0, last],
    ] as Array<[number, number]>) {
      for (let i = -1; i <= 7; i += 1) {
        for (const [x, y] of [
          [ox + i, oy - 1],
          [ox + i, oy + 7],
          [ox - 1, oy + i],
          [ox + 7, oy + i],
        ] as Array<[number, number]>) {
          if (x >= 0 && x < this.size && y >= 0 && y < this.size && !this.isReserved(x, y)) {
            this.set(x, y, false);
          }
        }
      }
    }

    // Timing patterns.
    for (let i = 8; i < this.size - 8; i += 1) {
      this.set(i, 6, i % 2 === 0);
      this.set(6, i, i % 2 === 0);
    }

    // Alignment patterns, skipping the three that would collide with a finder.
    const positions = alignmentPositions(this.version);
    const count = positions.length;
    for (let a = 0; a < count; a += 1) {
      for (let b = 0; b < count; b += 1) {
        if ((a === 0 && b === 0) || (a === 0 && b === count - 1) || (a === count - 1 && b === 0)) {
          continue;
        }
        this.drawAlignment(positions[a] ?? 0, positions[b] ?? 0);
      }
    }

    // Reserve the format-information strips by drawing placeholder bits: the
    // strips are not contiguous (they step around the timing patterns), so
    // reusing the real writer is the only way to reserve exactly the right
    // modules and no others.
    this.drawFormat('M', 0);
    // The one module that is dark in every symbol ever made.
    this.set(8, this.size - 8, true);

    if (this.version >= 7) {
      const bits = versionBits(this.version);
      for (let i = 0; i < 18; i += 1) {
        const dark = ((bits >>> i) & 1) === 1;
        const a = Math.floor(i / 3);
        const b = (i % 3) + this.size - 11;
        this.set(a, b, dark);
        this.set(b, a, dark);
      }
    }
  }

  private drawFinder(ox: number, oy: number): void {
    for (let dy = 0; dy < 7; dy += 1) {
      for (let dx = 0; dx < 7; dx += 1) {
        const ring = Math.max(Math.abs(dx - 3), Math.abs(dy - 3));
        this.set(ox + dx, oy + dy, ring !== 2);
      }
    }
  }

  private drawAlignment(cx: number, cy: number): void {
    for (let dy = -2; dy <= 2; dy += 1) {
      for (let dx = -2; dx <= 2; dx += 1) {
        this.set(cx + dx, cy + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
      }
    }
  }

  /** Zig-zag placement, two columns at a time, right to left. */
  placeData(codewords: Uint8Array): void {
    let bit = 0;
    const total = codewords.length * 8;
    for (let right = this.size - 1; right >= 1; right -= 2) {
      // Column 6 is the vertical timing pattern; the pairing skips over it.
      if (right === 6) right = 5;
      for (let vertical = 0; vertical < this.size; vertical += 1) {
        for (let j = 0; j < 2; j += 1) {
          const x = right - j;
          const upward = ((right + 1) & 2) === 0;
          const y = upward ? this.size - 1 - vertical : vertical;
          if (this.isReserved(x, y) || bit >= total) continue;
          const byte = codewords[bit >>> 3] ?? 0;
          this.set(x, y, ((byte >>> (7 - (bit & 7))) & 1) === 1, false);
          bit += 1;
        }
      }
    }
  }

  applyMask(mask: number): void {
    for (let y = 0; y < this.size; y += 1) {
      const row = this.modules[y];
      if (!row) continue;
      for (let x = 0; x < this.size; x += 1) {
        if (this.isReserved(x, y)) continue;
        if (maskAt(mask, x, y)) row[x] = !row[x];
      }
    }
  }

  drawFormat(ec: QrEcLevel, mask: number): void {
    const bits = formatBits(ec, mask);
    for (let i = 0; i < 15; i += 1) {
      const dark = ((bits >>> i) & 1) === 1;
      // First copy: down the left of the top-left finder, then along its bottom.
      if (i < 6) this.set(8, i, dark);
      else if (i < 8) this.set(8, i + 1, dark);
      else if (i === 8) this.set(7, 8, dark);
      else this.set(14 - i, 8, dark);
      // Second copy, split between the other two finders.
      if (i < 8) this.set(this.size - 1 - i, 8, dark);
      else this.set(8, this.size - 15 + i, dark);
    }
  }

  penalty(): number {
    let score = 0;
    const n = this.size;

    // Rule 1 — runs of five or more same-coloured modules in a line.
    for (let i = 0; i < n; i += 1) {
      for (const horizontal of [true, false]) {
        let run = 1;
        let previous = horizontal ? this.get(0, i) : this.get(i, 0);
        for (let j = 1; j < n; j += 1) {
          const current = horizontal ? this.get(j, i) : this.get(i, j);
          if (current === previous) {
            run += 1;
            if (run === 5) score += PENALTY_N1;
            else if (run > 5) score += 1;
          } else {
            previous = current;
            run = 1;
          }
        }
      }
    }

    // Rule 2 — every 2x2 block of one colour.
    for (let y = 0; y < n - 1; y += 1) {
      for (let x = 0; x < n - 1; x += 1) {
        const c = this.get(x, y);
        if (c === this.get(x + 1, y) && c === this.get(x, y + 1) && c === this.get(x + 1, y + 1)) {
          score += PENALTY_N2;
        }
      }
    }

    // Rule 3 — finder-like 1:1:3:1:1 sequences with a four-module light area on
    // one side, which is what actually misleads a scanner hunting for finders.
    for (let i = 0; i < n; i += 1) {
      const row: boolean[] = [];
      const column: boolean[] = [];
      for (let j = 0; j < n; j += 1) {
        row.push(this.get(j, i));
        column.push(this.get(i, j));
      }
      score += finderLikePenalty(row) + finderLikePenalty(column);
    }

    // Rule 4 — deviation of the dark-module ratio from 50%, in 5% steps.
    let dark = 0;
    for (let y = 0; y < n; y += 1) {
      for (let x = 0; x < n; x += 1) if (this.get(x, y)) dark += 1;
    }
    const total = n * n;
    score += Math.floor(Math.abs(dark * 20 - total * 10) / total) * PENALTY_N4;

    return score;
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export interface QrOptions {
  /** Preferred EC level. Falls back to weaker levels only if nothing fits. */
  ecLevel?: QrEcLevel;
  /** Force a mask (0–7) instead of picking the lowest-penalty one. Testing seam. */
  mask?: number;
  /** Force a version instead of picking the smallest that fits. Testing seam. */
  version?: number;
}

/** Levels tried in order when the requested one cannot hold the payload. */
const FALLBACK_ORDER: QrEcLevel[] = ['H', 'Q', 'M', 'L'];

/**
 * Encode `text` as a QR symbol.
 *
 * Picks the smallest version that fits at `ecLevel` (default M — the usual
 * print/screen compromise, 15% recovery). Only if the payload will not fit at
 * any supported version does it step down to a weaker level, so a long URL
 * degrades in redundancy rather than failing outright.
 */
export function encodeQr(text: string, options: QrOptions = {}): QrCode {
  const bytes = new TextEncoder().encode(text);
  const preferred = options.ecLevel ?? 'M';

  // Only ever step *down* in redundancy: a payload that does not fit at M is
  // not helped by trying Q.
  const candidates = FALLBACK_ORDER.slice(FALLBACK_ORDER.indexOf(preferred));

  for (const ec of candidates) {
    const from = options.version ?? 1;
    const to = options.version ?? QR_MAX_VERSION;
    for (let version = from; version <= to; version += 1) {
      if (bytes.length > qrByteCapacity(version, ec)) continue;
      return render(bytes, version, ec, options.mask);
    }
  }

  throw new Error(
    `qr: ${String(bytes.length)} bytes exceeds the capacity of version ${String(QR_MAX_VERSION)}`,
  );
}

function render(bytes: Uint8Array, version: number, ec: QrEcLevel, forcedMask?: number): QrCode {
  const codewords = buildCodewords(bytes, version, ec);

  let best: Matrix | null = null;
  let bestMask = 0;
  let bestScore = Number.POSITIVE_INFINITY;

  const masks = forcedMask === undefined ? [0, 1, 2, 3, 4, 5, 6, 7] : [forcedMask];
  for (const mask of masks) {
    const matrix = new Matrix(version);
    matrix.drawFunctionPatterns();
    matrix.placeData(codewords);
    matrix.applyMask(mask);
    matrix.drawFormat(ec, mask);
    const score = matrix.penalty();
    if (score < bestScore) {
      bestScore = score;
      best = matrix;
      bestMask = mask;
    }
  }
  if (!best) throw new Error('qr: no mask produced a symbol');

  return { size: best.size, version, ecLevel: ec, mask: bestMask, modules: best.modules };
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

/**
 * Dark modules as a single SVG path, in a viewBox of `size + 2 * quietZone`.
 *
 * One path rather than thousands of `<rect>`s: a version-6 symbol has ~1800
 * dark modules, and that many DOM nodes is a visible hitch on a phone. The
 * horizontal run-merging also keeps the path string small.
 */
export function qrToSvgPath(qr: QrCode, quietZone = 4): string {
  const parts: string[] = [];
  for (let y = 0; y < qr.size; y += 1) {
    let x = 0;
    while (x < qr.size) {
      if (!qr.modules[y]?.[x]) {
        x += 1;
        continue;
      }
      let run = 1;
      while (x + run < qr.size && qr.modules[y]?.[x + run]) run += 1;
      parts.push(`M${String(x + quietZone)} ${String(y + quietZone)}h${String(run)}v1h-${String(run)}z`);
      x += run;
    }
  }
  return parts.join('');
}

/** Side length of the rendered viewBox, quiet zone included. */
export function qrViewBox(qr: QrCode, quietZone = 4): number {
  return qr.size + quietZone * 2;
}
