/**
 * Transfer identity.
 *
 * The binary chunk frame (see protocol.ts) addresses a transfer with a uint32
 * `transferSeq`, but every control message addresses it with a string
 * `transferId`, and neither `upload-ready` nor `download-init` carries an
 * explicit mapping between the two. So the mapping has to be derivable by both
 * peers without an extra round trip: **transferId is the decimal string form of
 * the uint32 transferSeq**. `Number(transferId)` on either side yields the seq.
 */

const MAX_SEQ = 0xffffffff;

let counter = 0;

export function newTransferSeq(): number {
  // Random high bits keep two independently-restarted sessions from colliding;
  // the counter keeps two transfers created in the same millisecond distinct.
  counter = (counter + 1) & 0xffff;
  const random = Math.floor(Math.random() * 0xffff) << 16;
  const seq = (random | counter) >>> 0;
  return seq === 0 ? 1 : Math.min(seq, MAX_SEQ);
}

export function seqToTransferId(seq: number): string {
  return String(seq >>> 0);
}

export function transferIdToSeq(id: string): number | null {
  const n = Number(id);
  return Number.isInteger(n) && n >= 0 && n <= MAX_SEQ ? n : null;
}

/** Short opaque id for client-side objects (request ids, optimistic items). */
export function randomId(prefix = ''): string {
  const bytes = new Uint8Array(9);
  crypto.getRandomValues(bytes);
  let out = '';
  for (const b of bytes) out += b.toString(36).padStart(2, '0');
  return prefix + out.slice(0, 14);
}

export function deviceName(): string {
  const ua = navigator.userAgent;
  const platform =
    /iPhone/.test(ua) ? 'iPhone'
    : /iPad/.test(ua) ? 'iPad'
    : /Android/.test(ua) ? 'Android'
    : /Macintosh/.test(ua) ? 'Mac'
    : /Windows/.test(ua) ? 'Windows'
    : /Linux/.test(ua) ? 'Linux'
    : 'Browser';
  const browser =
    /Firefox\//.test(ua) ? 'Firefox'
    : /Edg\//.test(ua) ? 'Edge'
    : /Chrome\//.test(ua) ? 'Chrome'
    : /Safari\//.test(ua) ? 'Safari'
    : 'Browser';
  return `${platform} · ${browser}`;
}

export function platformTag(): string {
  return navigator.platform || 'web';
}
