import type { BootstrapResponse } from '@filedrop/shared';

/**
 * Device credentials + a cached bootstrap payload.
 *
 * The bootstrap cache matters: the P2P tier needs Agora credentials, but it is
 * used exactly when the NAS's HTTP API is *not* reachable (mobile data). We
 * therefore persist the last good `/api/bootstrap` response and fall back to it
 * while the Agora token is still valid.
 */

const SESSION_KEY = 'filedrop.session.v1';
const BOOTSTRAP_KEY = 'filedrop.bootstrap.v1';

export interface DeviceSession {
  deviceId: string;
  token: string;
  nasName: string;
  nasPeerId: string;
  /**
   * Epoch ms at which the NAS stops honouring this token, when it told us.
   *
   * Tokens granted through the QR + Telegram flow last exactly
   * AUTH_TOKEN_TTL_DAYS and are never renewed — the point is that access is
   * time-boxed, so a device that borrowed the library for an afternoon does not
   * keep it forever. Storing the expiry lets the client say so plainly instead
   * of letting the user discover it as a mysterious connection failure.
   *
   * Absent for sessions created by the six-digit LAN pairing flow.
   */
  tokenExpiresAt?: number;
}

function readJson<T>(key: string): T | null {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : null;
  } catch {
    return null;
  }
}

function writeJson(key: string, value: unknown): void {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    /* private mode / quota — the app still works, it just re-pairs next visit */
  }
}

export function loadSession(): DeviceSession | null {
  const s = readJson<DeviceSession>(SESSION_KEY);
  if (!s || typeof s.token !== 'string' || typeof s.deviceId !== 'string') return null;
  return s;
}

export function saveSession(session: DeviceSession): void {
  writeJson(SESSION_KEY, session);
}

export function clearSession(): void {
  try {
    localStorage.removeItem(SESSION_KEY);
    localStorage.removeItem(BOOTSTRAP_KEY);
  } catch {
    /* ignore */
  }
}

export function loadCachedBootstrap(): BootstrapResponse | null {
  const b = readJson<BootstrapResponse>(BOOTSTRAP_KEY);
  if (!b || !b.signaling) return null;

  const agora = b.signaling.agora;
  // App-ID-only credentials: the NAS emits `token: ''` with `expiresAt: 0` to
  // mean "log in without a token". Those never expire, so the staleness check
  // below must be skipped — running it would discard a perfectly usable cached
  // bootstrap on every load, since `0 * 1000 < Date.now()` is always true.
  if (!agora || !agora.token.trim()) return b;

  // A genuinely expired Agora token is worse than none: the SDK would sit
  // retrying a login that cannot succeed.
  if (agora.expiresAt && agora.expiresAt * 1000 < Date.now()) {
    return { ...b, signaling: { ws: b.signaling.ws } };
  }
  return b;
}

export function saveBootstrap(bootstrap: BootstrapResponse): void {
  writeJson(BOOTSTRAP_KEY, bootstrap);
}
