import type {
  BootstrapResponse,
  ControlMessage,
  FileMeta,
  Item,
  ItemKind,
  PairRequest,
  PairResponse,
} from '@filedrop/shared';

/**
 * Thin HTTP client for the NAS agent.
 *
 * All paths are root-absolute (`/api/...`) even though the app is served from
 * `/app/`, so the same code works behind a reverse proxy and through the Vite
 * dev proxy. Auth is a bearer token, except for media URLs consumed by
 * `<img>`/`<video>` which cannot carry headers and use `?t=<token>` instead.
 */

export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
    readonly code?: string,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

let authToken: string | null = null;
let unauthorizedHandler: (() => void) | null = null;
/**
 * Absolute origin of the NAS agent when the UI is not same-origin
 * (e.g. standalone on :8421 talking to agent on :8420). Empty = relative.
 */
let apiOrigin = '';

export function setAuthToken(token: string | null): void {
  authToken = token;
}

export function getAuthToken(): string | null {
  return authToken;
}

export function setApiOrigin(origin: string | null): void {
  apiOrigin = origin ? origin.replace(/\/+$/, '') : '';
}

export function getApiOrigin(): string {
  return apiOrigin;
}

/** Build a path against the configured API origin (or page origin). */
export function apiUrl(path: string): string {
  if (!path.startsWith('/')) path = `/${path}`;
  return apiOrigin ? `${apiOrigin}${path}` : path;
}

/** Registered by the auth store: a 401 means the device was revoked → re-pair. */
export function onUnauthorized(handler: () => void): void {
  unauthorizedHandler = handler;
}

function authHeaders(extra?: HeadersInit): Headers {
  const headers = new Headers(extra);
  if (authToken) headers.set('authorization', `Bearer ${authToken}`);
  return headers;
}

async function toError(res: Response): Promise<ApiError> {
  let message = `${res.status} ${res.statusText}`;
  let code: string | undefined;
  try {
    const body = (await res.json()) as { error?: string; message?: string; code?: string };
    message = body.message ?? body.error ?? message;
    code = body.code;
  } catch {
    /* non-JSON error body */
  }
  return new ApiError(res.status, message, code);
}

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(apiUrl(path), { ...init, headers: authHeaders(init.headers) });
  if (res.status === 401 || res.status === 403) {
    unauthorizedHandler?.();
    throw await toError(res);
  }
  if (!res.ok) throw await toError(res);
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

// ---------------------------------------------------------------------------
// Endpoints
// ---------------------------------------------------------------------------

export interface HealthResponse {
  ok: boolean;
  nasName: string;
  freeBytes: number;
  protocolVersion: number;
}

/**
 * The LAN probe. Deliberately short-timeout: on mobile data the NAS address is
 * either refused instantly or black-holed, and we do not want to stall the app
 * behind a 30s TCP timeout before falling back to P2P.
 */
export async function probeHealth(timeoutMs = 1500): Promise<HealthResponse | null> {
  return probeHealthAt(apiUrl('/api/health'), timeoutMs);
}

/** Probe a fully-qualified health URL (used to find a local agent from :8421). */
export async function probeHealthAt(
  healthUrl: string,
  timeoutMs = 1500,
): Promise<HealthResponse | null> {
  const abort = new AbortController();
  const timer = setTimeout(() => abort.abort(), timeoutMs);
  try {
    const res = await fetch(healthUrl, {
      signal: abort.signal,
      cache: 'no-store',
      headers: authHeaders(),
    });
    if (!res.ok) return null;
    const body = (await res.json()) as HealthResponse;
    return body.ok ? body : null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Origins to try for a same-LAN / same-machine agent when the UI is standalone
 * (http only — https pages cannot probe http without mixed-content blocks).
 */
export function localAgentOriginCandidates(): string[] {
  if (typeof window === 'undefined') return [];
  if (window.location.protocol === 'https:') return [];

  const out: string[] = [];
  try {
    const custom = localStorage.getItem('filedrop.agentOrigin')?.trim();
    if (custom) out.push(custom.replace(/\/+$/, ''));
  } catch {
    /* ignore */
  }
  try {
    const u = new URL(window.location.href);
    out.push(`${u.protocol}//${u.hostname}:8420`);
    if (u.hostname !== '127.0.0.1') out.push(`${u.protocol}//127.0.0.1:8420`);
    if (u.hostname !== 'localhost') out.push(`${u.protocol}//localhost:8420`);
  } catch {
    out.push('http://127.0.0.1:8420', 'http://localhost:8420');
  }
  return [...new Set(out)];
}

/** First candidate that answers /api/health, or null. */
export async function findReachableAgentOrigin(
  timeoutMs = 1200,
): Promise<{ origin: string; health: HealthResponse } | null> {
  for (const origin of localAgentOriginCandidates()) {
    const health = await probeHealthAt(`${origin}/api/health`, timeoutMs);
    if (health) return { origin, health };
  }
  return null;
}

export function pair(body: PairRequest): Promise<PairResponse> {
  return request<PairResponse>('/api/pair', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function bootstrap(): Promise<BootstrapResponse> {
  return request<BootstrapResponse>('/api/bootstrap');
}

export interface ListResponse {
  items: Item[];
  nextCursor: string | null;
}

export function listItems(params: {
  cursor?: string | null;
  limit?: number;
  query?: string;
  signal?: AbortSignal;
}): Promise<ListResponse> {
  const qs = new URLSearchParams();
  if (params.cursor) qs.set('cursor', params.cursor);
  if (params.limit) qs.set('limit', String(params.limit));
  if (params.query) qs.set('q', params.query);
  const suffix = qs.toString();
  return request<ListResponse>(`/api/items${suffix ? `?${suffix}` : ''}`, {
    signal: params.signal ?? null,
  });
}

export function postText(text: string, kind: Extract<ItemKind, 'text' | 'link' | 'clipboard'>, clientId: string): Promise<{ item: Item }> {
  return request<{ item: Item }>('/api/items', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ text, kind, clientId }),
  });
}

export function deleteItem(itemId: string): Promise<void> {
  return request<void>(`/api/items/${encodeURIComponent(itemId)}`, { method: 'DELETE' });
}

/** Mirrors the `upload-init` → `upload-ready` control exchange over HTTP. */
export type UploadReady = Extract<ControlMessage, { type: 'upload-ready' }> & { item?: Item };

export function uploadInit(transferId: string, file: FileMeta): Promise<UploadReady> {
  return request<UploadReady>('/api/upload/init', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ type: 'upload-init', transferId, file }),
  });
}

/**
 * Media URLs for `<img>`/`<video>`/download anchors. These carry the token in
 * the query string because element loads cannot set an Authorization header.
 */
export function mediaUrl(itemId: string, variant: 'raw' | 'thumb'): string {
  const token = authToken ? `?t=${encodeURIComponent(authToken)}` : '';
  return apiUrl(`/api/items/${encodeURIComponent(itemId)}/${variant}${token}`);
}

/** Signaling / push socket. Absolute ws(s) URL from API origin or page origin. */
export function signalSocketUrl(path = '/ws/signal'): string {
  const base = apiOrigin || window.location.href;
  const url = new URL(path, base.endsWith('/') ? base : `${base}/`);
  url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
  if (authToken) url.searchParams.set('t', authToken);
  return url.toString();
}
