import {
  useEffect,
  useRef,
  type MouseEvent as ReactMouseEvent,
  type PointerEvent as ReactPointerEvent,
} from 'react';

const HOLD_MS = 480;
const MOVE_TOLERANCE_PX = 10;

/**
 * Long-press for touch, right-click for mouse. Both open the same item menu.
 * Movement cancels the hold so a press that turns into a scroll does not fire.
 */
export function useLongPress(onTrigger: () => void): {
  onPointerDown: (event: ReactPointerEvent) => void;
  onPointerUp: () => void;
  onPointerMove: (event: ReactPointerEvent) => void;
  onPointerCancel: () => void;
  onContextMenu: (event: ReactMouseEvent) => void;
} {
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const origin = useRef<{ x: number; y: number } | null>(null);

  const clear = (): void => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = null;
    origin.current = null;
  };

  useEffect(() => clear, []);

  return {
    onPointerDown: (event) => {
      if (event.pointerType === 'mouse') return;
      origin.current = { x: event.clientX, y: event.clientY };
      timer.current = setTimeout(() => {
        clear();
        onTrigger();
      }, HOLD_MS);
    },
    onPointerMove: (event) => {
      if (!origin.current) return;
      const dx = Math.abs(event.clientX - origin.current.x);
      const dy = Math.abs(event.clientY - origin.current.y);
      if (dx > MOVE_TOLERANCE_PX || dy > MOVE_TOLERANCE_PX) clear();
    },
    onPointerUp: clear,
    onPointerCancel: clear,
    onContextMenu: (event) => {
      event.preventDefault();
      onTrigger();
    },
  };
}
