import type { TransportKind } from '@filedrop/shared';
import { useEffect, useRef } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { deviceName } from '../lib/ids';
import { formatBytes, formatRate } from '../lib/format';
import { useAuth } from '../state/auth';
import { useConnection } from '../state/connection';
import { ACTIVE_STATUSES, useTransfers } from '../state/transfers';
import { RefreshIcon } from './Icons';

const TIER_LABEL: Record<TransportKind, string> = {
  'lan-direct': 'LAN DIRECT',
  'p2p-host': 'P2P HOST',
  'p2p-srflx': 'P2P DIRECT',
  'p2p-relay': 'P2P RELAY',
  'signal-relay': 'RELAY',
};

const TIER_DETAIL: Record<TransportKind, string> = {
  'lan-direct': '本机/局域网 HTTP 直连 agent — 无 WebRTC 握手。',
  'p2p-host': '同网 WebRTC 直连，信令仅握手。',
  'p2p-srflx': '经 NAT 打洞的 WebRTC 直连。',
  'p2p-relay': 'WebRTC 经 TURN 中继。',
  'signal-relay': '无可用直连路径，无法传文件。',
};

/**
 * Every label here comes from the *negotiated* ICE candidate pair (see
 * `PeerLink.resolvePath`), not from an assumption about the network. That
 * matters most in standalone mode: the page has no HTTP path to the NAS, so
 * `lan-direct` can never be the answer even when both ends sit on the same
 * wifi — what you get there is `p2p-host`, and the badge says exactly that.
 */

/**
 * Aggregate live throughput across everything currently uploading.
 * `useShallow` matters: the selector builds a fresh object each call and
 * zustand's default `Object.is` comparison would re-render on every store tick.
 */
function useLiveRate(): { rate: number; active: boolean } {
  return useTransfers(
    useShallow((state) => {
      let rate = 0;
      let active = false;
      for (const id of state.order) {
        const record = state.byId[id];
        if (!record || !ACTIVE_STATUSES.has(record.status)) continue;
        active = true;
        rate += record.rate;
      }
      return { rate, active };
    }),
  );
}

export function ConnectionModule(): JSX.Element {
  const state = useConnection();
  const { rate, active } = useLiveRate();
  const { session, unpair, forget, mode: deployMode } = useAuth();
  const container = useRef<HTMLDivElement>(null);
  const standaloneMode = deployMode === 'standalone';

  const open = state.panelOpen;
  const setOpen = state.setPanelOpen;

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent): void => {
      if (!container.current?.contains(event.target as Node)) setOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') setOpen(false);
    };
    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open, setOpen]);

  const down = state.phase === 'offline' || state.phase === 'reconnecting';
  const tone = down ? 'down' : state.phase === 'degraded' ? 'warn' : state.phase === 'online' ? 'live' : 'idle';
  const mode = down ? 'down' : active ? 'flow' : 'idle';

  const label =
    state.kind ? TIER_LABEL[state.kind]
    : state.phase === 'probing' ? 'PROBING'
    : state.phase === 'connecting' ? 'LINKING'
    : state.phase === 'reconnecting' ? 'RETRY'
    : state.phase === 'offline' ? 'OFFLINE'
    : 'IDLE';

  return (
    <div className="conn" ref={container}>
      <button
        type="button"
        className="conn__badge"
        data-tone={tone}
        onClick={() => setOpen(!open)}
        aria-expanded={open}
        aria-label={`Connection: ${label}. Open connection details.`}
      >
        <span className="pulse" data-mode={mode} aria-hidden="true">
          <span />
          <span />
          <span />
        </span>
        <span className="conn__label">{label}</span>
        {active && rate > 0 ? <span className="conn__rate">{formatRate(rate)}</span> : null}
      </button>

      {open ? (
        <div className="conn__panel" role="dialog" aria-label="Connection details">
          <h3>连接</h3>
          <dl className="kv">
            <dt>档位</dt>
            <dd data-accent={state.phase === 'online' ? 'true' : 'false'}>{label}</dd>

            <dt>路径</dt>
            <dd>{state.path ?? '—'}</dd>

            <dt>本浏览器</dt>
            <dd>
              {deviceName()}
              {session?.deviceId ?
                <span className="mono" style={{ display: 'block', opacity: 0.7, fontSize: 11 }}>
                  {session.deviceId}
                </span>
              : null}
            </dd>

            <dt>NAS</dt>
            <dd>{state.nasName ?? session?.nasName ?? '—'}</dd>

            <dt>吞吐</dt>
            <dd data-accent={active ? 'true' : 'false'}>{active ? formatRate(rate) : 'idle'}</dd>

            <dt>延迟</dt>
            <dd>{state.rttMs != null ? `${state.rttMs} ms` : '—'}</dd>

            <dt>剩余空间</dt>
            <dd>{formatBytes(state.freeBytes)}</dd>
          </dl>

          <p className="conn__note">
            授权绑定的是<strong>当前这台设备上的浏览器</strong>
            （不是提供页面的主机 IP）。其它手机/电脑打开同一地址后需各自扫码授权，可同时使用。
          </p>

          {state.error ? (
            <p className="conn__note" data-tone="bad">
              {state.error}
            </p>
          ) : state.note ? (
            <p className="conn__note">{state.note}</p>
          ) : state.kind ? (
            <p className="conn__note">{TIER_DETAIL[state.kind]}</p>
          ) : null}

          <div className="conn__actions">
            <button type="button" className="btn btn--sm" onClick={() => state.reconnect()}>
              <RefreshIcon />
              Reconnect
            </button>
            <button type="button" className="btn btn--sm btn--danger" onClick={unpair}>
              Unpair
            </button>
            {standaloneMode ? (
              <button
                type="button"
                className="btn btn--sm btn--danger"
                onClick={forget}
                title="Clear the App ID, channel and device token stored in this browser"
              >
                Forget this NAS
              </button>
            ) : null}
          </div>
        </div>
      ) : null}
    </div>
  );
}
