import { useEffect, useReducer } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { formatBytes, formatDuration, formatPercent, formatRate } from '../lib/format';
import { cancelTransfer, canRetry, pauseTransfer, resumeTransfer, retryTransfer } from '../net/transfer';
import { useTransfers, type TransferRecord } from '../state/transfers';
import { CloseIcon, PauseIcon, PlayIcon, RefreshIcon } from './Icons';

/** Rows disappear once they have been done for this long. */
const KEEP_FINISHED_MS = 6000;

export function TransferTray(): JSX.Element | null {
  const records = useTransfers(
    useShallow((state) =>
      state.order
        .map((id) => state.byId[id])
        .filter((record): record is TransferRecord => {
          if (!record) return false;
          if (record.status === 'error') return true;
          if (record.finishedAt == null) return true;
          return Date.now() - record.finishedAt < KEEP_FINISHED_MS;
        }),
    ),
  );
  const clearFinished = useTransfers((state) => state.clearFinished);
  const hasFinished = useTransfers((state) =>
    state.order.some((id) => state.byId[id]?.finishedAt != null),
  );

  // Finished rows expire on a wall-clock deadline, and the store may go quiet
  // before then — so tick while any of them are still on screen.
  const [, tick] = useReducer((n: number) => n + 1, 0);
  useEffect(() => {
    if (!hasFinished) return;
    const timer = setInterval(tick, 1000);
    return () => clearInterval(timer);
  }, [hasFinished]);

  if (records.length === 0) return null;

  const inFlight = records.filter((record) => record.finishedAt == null).length;

  return (
    <div className="tray">
      <div className="tray__head">
        <span className="tray__title">
          Transfers {inFlight > 0 ? <span className="tray__count">· {inFlight} active</span> : null}
        </span>
        <span style={{ flex: 1 }} />
        <button type="button" className="btn btn--sm btn--ghost" onClick={clearFinished}>
          Clear
        </button>
      </div>
      {records.map((record) => (
        <TransferRow key={record.id} record={record} />
      ))}
    </div>
  );
}

function TransferRow({ record }: { record: TransferRecord }): JSX.Element {
  const fraction =
    record.status === 'preparing' ? (record.size > 0 ? record.hashedBytes / record.size : 0)
    : record.size > 0 ? record.bytesDone / record.size
    : 0;

  const indeterminate = record.status === 'negotiating' || (record.status === 'verifying' && record.size === 0);
  const done = record.status === 'done' || record.status === 'deduped';

  return (
    <div className="transfer">
      <span className="transfer__name" title={record.name}>
        {record.name}
      </span>

      <span className="transfer__actions">
        {record.status === 'uploading' || record.status === 'preparing' ? (
          <button type="button" onClick={() => pauseTransfer(record.id)} aria-label="Pause" title="Pause">
            <PauseIcon />
          </button>
        ) : null}
        {record.status === 'paused' ? (
          <button type="button" onClick={() => resumeTransfer(record.id)} aria-label="Resume" title="Resume">
            <PlayIcon />
          </button>
        ) : null}
        {record.status === 'error' && canRetry(record.id) ? (
          <button type="button" onClick={() => retryTransfer(record.id)} aria-label="Retry" title="Retry">
            <RefreshIcon />
          </button>
        ) : null}
        {record.finishedAt == null ? (
          <button type="button" onClick={() => cancelTransfer(record.id)} aria-label="Cancel" title="Cancel">
            <CloseIcon />
          </button>
        ) : null}
      </span>

      <span className="transfer__bar" data-indeterminate={indeterminate}>
        <i style={{ width: formatPercent(done ? 1 : fraction) }} />
      </span>

      <span className="transfer__stats">
        <Status record={record} />
      </span>
    </div>
  );
}

function Status({ record }: { record: TransferRecord }): JSX.Element {
  if (record.status === 'error') {
    return <span data-tone="bad">{record.error ?? 'Failed'}</span>;
  }
  if (record.status === 'cancelled') return <span>Cancelled</span>;
  if (record.status === 'deduped') {
    return (
      <>
        <span data-tone="good">Already on NAS · instant</span>
        <b>{formatBytes(record.size)}</b>
      </>
    );
  }
  if (record.status === 'done') {
    return (
      <>
        <span data-tone="good">Sent</span>
        <b>{formatBytes(record.size)}</b>
        {record.resumedFromBytes > 0 ? <span>resumed at {formatBytes(record.resumedFromBytes)}</span> : null}
      </>
    );
  }
  if (record.status === 'preparing') {
    return (
      <>
        <span data-tone="accent">Preparing · SHA-256</span>
        <b>
          {formatBytes(record.hashedBytes)} / {formatBytes(record.size)}
        </b>
      </>
    );
  }
  if (record.status === 'negotiating') return <span data-tone="accent">Negotiating with the NAS…</span>;
  if (record.status === 'verifying') return <span data-tone="accent">Verifying checksum…</span>;
  if (record.status === 'queued') return <span>{record.error ?? 'Queued'}</span>;
  if (record.status === 'paused') {
    return (
      <>
        <span>Paused</span>
        <b>
          {formatBytes(record.bytesDone)} / {formatBytes(record.size)}
        </b>
      </>
    );
  }

  return (
    <>
      <b>
        {formatBytes(record.bytesDone)} / {formatBytes(record.size)}
      </b>
      <span data-tone="accent">{formatRate(record.rate)}</span>
      {record.etaMs != null ? <span>{formatDuration(record.etaMs)} left</span> : null}
      {record.resumedFromBytes > 0 ? <span>resumed</span> : null}
    </>
  );
}
