import { useCallback, useEffect, useState } from 'react';
import { copyText } from '../lib/clipboard';
import { findUrls } from '../lib/format';
import { enqueueFiles, fileFromClipboardBlob } from '../net/transfer';
import { useItems } from '../state/items';
import { toast } from '../state/toasts';

/**
 * Window-level drag & drop.
 *
 * Chrome fires dragenter/dragleave for every element crossed, so a naive
 * boolean flickers badly. Counting enter/leave pairs is the standard fix.
 */
export function useWindowDrop(): boolean {
  const [dragging, setDragging] = useState(false);

  useEffect(() => {
    let depth = 0;

    const hasFiles = (event: DragEvent): boolean =>
      Array.from(event.dataTransfer?.types ?? []).includes('Files');

    const onEnter = (event: DragEvent): void => {
      if (!hasFiles(event)) return;
      depth += 1;
      setDragging(true);
    };
    const onOver = (event: DragEvent): void => {
      if (!hasFiles(event)) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'copy';
    };
    const onLeave = (event: DragEvent): void => {
      if (!hasFiles(event)) return;
      depth = Math.max(0, depth - 1);
      if (depth === 0) setDragging(false);
    };
    const onDrop = (event: DragEvent): void => {
      depth = 0;
      setDragging(false);
      if (!hasFiles(event)) return;
      event.preventDefault();
      const files = Array.from(event.dataTransfer?.files ?? []);
      if (files.length > 0) enqueueFiles(files);
    };

    window.addEventListener('dragenter', onEnter);
    window.addEventListener('dragover', onOver);
    window.addEventListener('dragleave', onLeave);
    window.addEventListener('drop', onDrop);
    return () => {
      window.removeEventListener('dragenter', onEnter);
      window.removeEventListener('dragover', onOver);
      window.removeEventListener('dragleave', onLeave);
      window.removeEventListener('drop', onDrop);
    };
  }, []);

  return dragging;
}

/**
 * Ctrl/Cmd+V anywhere outside a text field: image blobs become uploads, plain
 * text becomes a text/link item. Inside the composer the browser's own paste
 * behaviour wins for text, but images are still intercepted.
 */
export function usePasteIngest(): void {
  useEffect(() => {
    const onPaste = (event: ClipboardEvent): void => {
      const data = event.clipboardData;
      if (!data) return;

      const target = event.target as HTMLElement | null;
      const inEditable =
        target?.tagName === 'TEXTAREA' ||
        target?.tagName === 'INPUT' ||
        target?.isContentEditable === true;

      const files = Array.from(data.files ?? []);
      const imageItems = Array.from(data.items ?? [])
        .filter((entry) => entry.kind === 'file' && entry.type.startsWith('image/'))
        .map((entry) => entry.getAsFile())
        .filter((file): file is File => file !== null);

      const blobs = files.length > 0 ? files : imageItems;
      if (blobs.length > 0) {
        event.preventDefault();
        enqueueFiles(
          blobs.map((file, index) =>
            file.name && file.name !== 'image.png' ? file : fileFromClipboardBlob(file, index),
          ),
        );
        return;
      }

      if (inEditable) return;

      const text = data.getData('text/plain').trim();
      if (!text) return;
      event.preventDefault();
      const kind = findUrls(text).length === 1 && !/\s/.test(text) ? 'link' : 'text';
      void useItems
        .getState()
        .sendText(text, kind)
        .catch(() => toast.error('Could not send pasted text'));
    };

    window.addEventListener('paste', onPaste);
    return () => window.removeEventListener('paste', onPaste);
  }, []);
}

/** Reads the system clipboard on demand and pushes it as a `clipboard` item. */
export function usePushClipboard(): () => Promise<void> {
  return useCallback(async () => {
    if (!navigator.clipboard?.readText) {
      toast.error('Clipboard access needs HTTPS or localhost');
      return;
    }
    try {
      const text = (await navigator.clipboard.readText()).trim();
      if (!text) {
        toast.info('Clipboard is empty');
        return;
      }
      await useItems.getState().sendText(text, 'clipboard');
      toast.ok('Clipboard sent to the NAS');
    } catch {
      toast.error('Could not read the clipboard');
    }
  }, []);
}

export async function copyToClipboard(text: string): Promise<void> {
  const ok = await copyText(text);
  if (ok) toast.ok('已复制');
  else toast.error('复制失败，请长按链接手动复制');
}
