import { useEffect, useRef, useState, type ChangeEvent, type ClipboardEvent, type KeyboardEvent } from 'react';
import { useAuth } from '../state/auth';
import { LogoIcon } from './Icons';

const LOCAL_LENGTH = 6;

/**
 * The NAS-hosted pairing screen: six digits, typed.
 *
 * This is the only place a typed code survives. It is reachable exclusively by
 * someone already on your local network, talking to a socket a stranger cannot
 * open, so six digits is proportionate — and it needs no camera, no Telegram
 * and no internet.
 *
 * The standalone build has the opposite threat model (pairing would ride a
 * public signaling channel) and uses the QR + Telegram approval flow instead;
 * see `AuthRequestScreen`.
 *
 * Six individual boxes, but with the behaviours people actually expect: paste
 * fills every box, typing auto-advances, Backspace on an empty box steps back,
 * and arrow keys move between boxes. `inputMode="numeric"` gets the number pad
 * on phones without the spinner arrows a `type=number` would add.
 */
export function PairScreen(): JSX.Element {
  const { pair, pairing, pairError } = useAuth();
  const [digits, setDigits] = useState<string[]>(() => Array<string>(LOCAL_LENGTH).fill(''));
  const inputs = useRef<Array<HTMLInputElement | null>>([]);

  useEffect(() => {
    inputs.current[0]?.focus();
  }, []);

  const code = digits.join('');

  const commit = (next: string[]): void => {
    setDigits(next);
    if (next.every((digit) => digit !== '')) {
      void pair(next.join(''));
    }
  };

  const handleChange = (index: number) => (event: ChangeEvent<HTMLInputElement>) => {
    const raw = event.target.value.replace(/\D/g, '');
    if (!raw) {
      const next = [...digits];
      next[index] = '';
      setDigits(next);
      return;
    }
    // A phone keyboard can deliver several characters at once (autofill from an
    // SMS-style suggestion), so spread anything longer than one digit forward.
    const next = [...digits];
    let cursor = index;
    for (const character of raw) {
      if (cursor >= LOCAL_LENGTH) break;
      next[cursor] = character;
      cursor += 1;
    }
    commit(next);
    inputs.current[Math.min(cursor, LOCAL_LENGTH - 1)]?.focus();
  };

  const handleKeyDown = (index: number) => (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Backspace' && !digits[index] && index > 0) {
      event.preventDefault();
      const next = [...digits];
      next[index - 1] = '';
      setDigits(next);
      inputs.current[index - 1]?.focus();
    } else if (event.key === 'ArrowLeft' && index > 0) {
      event.preventDefault();
      inputs.current[index - 1]?.focus();
    } else if (event.key === 'ArrowRight' && index < LOCAL_LENGTH - 1) {
      event.preventDefault();
      inputs.current[index + 1]?.focus();
    } else if (event.key === 'Enter' && code.length === LOCAL_LENGTH) {
      void pair(code);
    }
  };

  const handlePaste = (event: ClipboardEvent<HTMLInputElement>): void => {
    const pasted = event.clipboardData.getData('text').replace(/\D/g, '').slice(0, LOCAL_LENGTH);
    if (!pasted) return;
    event.preventDefault();
    const next = Array<string>(LOCAL_LENGTH).fill('');
    for (let index = 0; index < pasted.length; index += 1) next[index] = pasted[index] ?? '';
    commit(next);
    inputs.current[Math.min(pasted.length, LOCAL_LENGTH - 1)]?.focus();
  };

  return (
    <div className="pair">
      <div className="pair__panel">
        <div className="pair__brand">
          <LogoIcon />
          <strong>FileDrop</strong>
        </div>

        <h1>Pair this device</h1>
        <p className="pair__lede">
          Enter the six-digit code your NAS printed on startup. The code is valid for a few minutes
          and can only be used once.
        </p>

        <div className="code" onPaste={handlePaste}>
          {digits.map((digit, index) => (
            <input
              // eslint-disable-next-line react/no-array-index-key -- fixed-length positional inputs
              key={index}
              ref={(element) => {
                inputs.current[index] = element;
              }}
              className="mono"
              value={digit}
              onChange={handleChange(index)}
              onKeyDown={handleKeyDown(index)}
              onFocus={(event) => event.currentTarget.select()}
              inputMode="numeric"
              autoComplete={index === 0 ? 'one-time-code' : 'off'}
              maxLength={LOCAL_LENGTH}
              disabled={pairing}
              data-filled={digit !== ''}
              aria-label={`Digit ${index + 1} of ${LOCAL_LENGTH}`}
            />
          ))}
        </div>

        {pairError ? <p className="pair__error">{pairError}</p> : null}

        <button
          type="button"
          className="btn btn--accent"
          style={{ width: '100%', height: 40 }}
          disabled={pairing || code.length !== LOCAL_LENGTH}
          onClick={() => void pair(code)}
        >
          {pairing ? 'Pairing…' : 'Pair device'}
        </button>

        <p className="pair__hint">
          Can&apos;t find the code? On the NAS run <code>docker logs filedrop</code> — it is printed
          at the top of the log, and again whenever you run <code>docker compose restart</code>.
        </p>
      </div>
    </div>
  );
}
