import type { Item } from '@filedrop/shared';
import { useCallback, useEffect, useState } from 'react';
import { useMediaSource } from '../hooks/useMediaSource';
import { formatBytes } from '../lib/format';
import { ChevronLeftIcon, ChevronRightIcon, CloseIcon, DownloadIcon } from './Icons';

interface LightboxProps {
  items: Item[];
  index: number;
  onIndexChange(index: number): void;
  onClose(): void;
  onDownload(item: Item): void;
}

/**
 * Full-screen media viewer. Video is served straight from the NAS on the LAN
 * tier so the browser can issue Range requests and seeking works; over P2P the
 * file is pulled into a Blob first, since there is no HTTP origin to range
 * against.
 */
export function Lightbox({ items, index, onIndexChange, onClose, onDownload }: LightboxProps): JSX.Element | null {
  const item = items[index];
  const media = useMediaSource(item ?? null, 'raw');
  const [dimensions, setDimensions] = useState<string | null>(null);

  const step = useCallback(
    (delta: number) => {
      const next = index + delta;
      if (next >= 0 && next < items.length) onIndexChange(next);
    },
    [index, items.length, onIndexChange],
  );

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
      else if (event.key === 'ArrowLeft') step(-1);
      else if (event.key === 'ArrowRight') step(1);
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [onClose, step]);

  useEffect(() => setDimensions(null), [index]);

  if (!item) return null;

  return (
    <div className="lightbox" role="dialog" aria-modal="true" aria-label={item.name ?? 'Media viewer'}>
      <div className="lightbox__bar">
        <div className="lightbox__title">
          <div className="lightbox__name">{item.name ?? 'Untitled'}</div>
          <div className="lightbox__meta">
            {formatBytes(item.size)}
            {dimensions ? ` · ${dimensions}` : item.width && item.height ? ` · ${item.width}×${item.height}` : ''}
          </div>
        </div>
        <button type="button" className="icon-btn" onClick={() => onDownload(item)} aria-label="Download">
          <DownloadIcon />
        </button>
        <button type="button" className="icon-btn" onClick={onClose} aria-label="Close">
          <CloseIcon />
        </button>
      </div>

      <div className="lightbox__stage">
        {media.status === 'loading' ? <span className="spinner" /> : null}

        {media.status === 'needs-fetch' ? (
          <button type="button" className="btn btn--accent" onClick={media.fetchNow}>
            Fetch {formatBytes(item.size)} over the direct link
          </button>
        ) : null}

        {media.status === 'error' ? (
          <p style={{ color: 'var(--danger)', fontSize: 13 }}>{media.message}</p>
        ) : null}

        {media.status === 'ready' && item.kind === 'video' ? (
          <video src={media.url} controls autoPlay playsInline />
        ) : null}

        {media.status === 'ready' && item.kind !== 'video' ? (
          <img
            src={media.url}
            alt={item.name ?? ''}
            onLoad={(event) =>
              setDimensions(`${event.currentTarget.naturalWidth}×${event.currentTarget.naturalHeight}`)
            }
          />
        ) : null}

        {index > 0 ? (
          <button
            type="button"
            className="lightbox__nav"
            data-side="prev"
            onClick={() => step(-1)}
            aria-label="Previous"
          >
            <ChevronLeftIcon />
          </button>
        ) : null}
        {index < items.length - 1 ? (
          <button
            type="button"
            className="lightbox__nav"
            data-side="next"
            onClick={() => step(1)}
            aria-label="Next"
          >
            <ChevronRightIcon />
          </button>
        ) : null}
      </div>

      <div className="lightbox__foot">
        {index + 1} / {items.length} · ← → to browse · Esc to close
      </div>
    </div>
  );
}
