import type { Item } from '@filedrop/shared';
import { useEffect, useState } from 'react';
import { transport } from '../net/transport';

/** Above this we do not auto-pull a preview over a metered P2P link. */
const P2P_AUTO_PREVIEW_MAX = 3 * 1024 * 1024;

export type MediaState =
  | { status: 'idle'; url: null }
  | { status: 'loading'; url: null }
  | { status: 'ready'; url: string }
  | { status: 'error'; url: null; message: string }
  /** P2P and the file is too big to pull automatically — needs a tap. */
  | { status: 'needs-fetch'; url: null };

/**
 * Resolves an item to something an <img>/<video> can point at.
 *
 * On the LAN tier that is just a URL. On P2P there is no HTTP origin to hit —
 * the NAS is unreachable, which is the whole reason we are on WebRTC — so the
 * bytes come over the DataChannel and become an object URL. Large files are not
 * pulled automatically there: you are probably on mobile data.
 */
export function useMediaSource(
  item: Item | null,
  variant: 'raw' | 'thumb',
  enabled = true,
): MediaState & { fetchNow: () => void } {
  const [state, setState] = useState<MediaState>({ status: 'idle', url: null });
  const [forced, setForced] = useState(0);

  useEffect(() => {
    if (!item || !enabled) {
      setState({ status: 'idle', url: null });
      return;
    }

    const direct = transport.mediaUrl(item, variant);
    if (direct) {
      setState({ status: 'ready', url: direct });
      return;
    }

    const size = item.size ?? 0;
    if (forced === 0 && variant === 'raw' && size > P2P_AUTO_PREVIEW_MAX) {
      setState({ status: 'needs-fetch', url: null });
      return;
    }
    if (forced === 0 && variant === 'thumb' && size > P2P_AUTO_PREVIEW_MAX) {
      setState({ status: 'needs-fetch', url: null });
      return;
    }

    let objectUrl: string | null = null;
    let cancelled = false;
    setState({ status: 'loading', url: null });

    transport
      .fetchItemBlob(item)
      .then((blob) => {
        if (cancelled) return;
        objectUrl = URL.createObjectURL(blob);
        setState({ status: 'ready', url: objectUrl });
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setState({
          status: 'error',
          url: null,
          message: error instanceof Error ? error.message : 'Preview unavailable',
        });
      });

    return () => {
      cancelled = true;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [item, variant, enabled, forced]);

  return { ...state, fetchNow: () => setForced((n) => n + 1) };
}
