import { create } from 'zustand';
import { transport } from '../net/transport';
import { INITIAL_CONNECTION_STATE, type ConnectionState } from '../net/types';

interface ConnectionStore extends ConnectionState {
  /** True while any bytes are moving; drives the "flowing" indicator. */
  active: boolean;
  panelOpen: boolean;
  setPanelOpen(open: boolean): void;
  setActive(active: boolean): void;
  reconnect(): void;
}

export const useConnection = create<ConnectionStore>((set) => ({
  ...INITIAL_CONNECTION_STATE,
  active: false,
  panelOpen: false,
  setPanelOpen: (panelOpen) => set({ panelOpen }),
  setActive: (active) => set({ active }),
  reconnect: () => {
    void transport.reconnect();
  },
}));

// The manager is the source of truth; the store is just a React-shaped mirror.
transport.subscribeState((state) => useConnection.setState(state));
