import { BUFFER_HIGH_WATER, CHUNK_SIZE } from '@filedrop/shared';
import { TransportError, type TransferGate } from './types';

/**
 * The write side of a chunked transfer. Implemented by the P2P transport over
 * an RTCDataChannel; kept behind an interface so the pump itself stays
 * testable and transport-agnostic.
 */
export interface ChunkSink {
  /** Queue one frame. Must not block. */
  send(chunkIndex: number, payload: Uint8Array): void;
  /** Bytes currently queued in the underlying transport. */
  bufferedAmount(): number;
  /** Resolves when the queue has drained below the low-water mark. */
  whenDrained(): Promise<void>;
  isOpen(): boolean;
}

export interface PumpOptions {
  /** Chunk indices the NAS already has (resume). */
  skip: ReadonlySet<number>;
  gate: TransferGate;
  signal: AbortSignal;
  /** Called after each frame is queued, with the absolute byte count sent. */
  onChunkQueued(chunkIndex: number, bytesQueuedTotal: number): void;
}

/**
 * Read a Blob in CHUNK_SIZE slices and push it into `sink`, respecting
 * backpressure.
 *
 * Two things here are load-bearing and easy to get wrong:
 *
 * 1. **Never read the whole file.** `file.slice(a, b).arrayBuffer()` pulls only
 *    that window off disk. `FileReader.readAsArrayBuffer(file)` on a 10 GB file
 *    allocates 10 GB and kills the tab.
 *
 * 2. **Never outrun the DataChannel.** `dc.send()` always accepts the buffer and
 *    queues it in userspace; the queue is unbounded, so a tight send loop turns
 *    into an unbounded memory allocation that the browser eventually kills. We
 *    stop feeding at BUFFER_HIGH_WATER and wait for the `bufferedamountlow`
 *    event before continuing. Checking *before* the send (rather than after)
 *    keeps the peak at high-water + one chunk.
 */
export async function pumpBlob(file: Blob, sink: ChunkSink, options: PumpOptions): Promise<void> {
  const totalChunks = Math.max(1, Math.ceil(file.size / CHUNK_SIZE));
  let bytesQueued = 0;

  for (let index = 0; index < totalChunks; index += 1) {
    const start = index * CHUNK_SIZE;
    const end = Math.min(start + CHUNK_SIZE, file.size);

    if (options.skip.has(index)) {
      bytesQueued += end - start;
      options.onChunkQueued(index, bytesQueued);
      continue;
    }

    if (options.signal.aborted) throw new TransportError('Transfer cancelled', 'cancelled');
    await options.gate.wait();
    if (options.signal.aborted) throw new TransportError('Transfer cancelled', 'cancelled');

    if (sink.bufferedAmount() >= BUFFER_HIGH_WATER) {
      await sink.whenDrained();
      if (options.signal.aborted) throw new TransportError('Transfer cancelled', 'cancelled');
    }
    if (!sink.isOpen()) throw new TransportError('Data channel closed mid-transfer', 'unreachable');

    const buffer = await file.slice(start, end).arrayBuffer();
    sink.send(index, new Uint8Array(buffer));
    bytesQueued += buffer.byteLength;
    options.onChunkQueued(index, bytesQueued);
  }
}

/** Chunk count for a file of `size` bytes, matching the pump's slicing. */
export function chunkCount(size: number): number {
  return Math.max(1, Math.ceil(size / CHUNK_SIZE));
}
