import { CHUNK_SIZE, type ControlMessage, type Item, type TransportKind } from '@filedrop/shared';
import * as api from '../api';
import { isSignalEnvelope } from '../signaling';
import { TransportError, type ListParams, type ListResult, type TextKind, type Transport, type UploadContext } from '../types';
import { BaseTransport } from './base';

/** Sentinel used to unwind an in-flight XHR when the user hits pause. */
const PAUSED = Symbol('paused');

/**
 * LAN tier — plain HTTP to the NAS.
 *
 * WHY this exists at all when we have WebRTC: on a local network a TCP socket
 * to the NAS is strictly better. No handshake (WebRTC costs 1-3 s of ICE before
 * the first byte moves), no SCTP-over-DTLS overhead, no userspace chunk
 * framing, and the kernel does the flow control. On a 2.5 GbE LAN this is
 * roughly twice the throughput of the DataChannel path for large files.
 *
 * Live updates still need a socket, so we keep a WebSocket on /ws/signal open
 * purely to receive `item-new`/`item-removed` pushes.
 */
export class LanTransport extends BaseTransport implements Transport {
  readonly kind: TransportKind = 'lan-direct';

  private socket: WebSocket | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private reconnectAttempt = 0;
  private stopped = false;

  async start(): Promise<void> {
    this.stopped = false;
    this.patchState({ phase: 'connecting', kind: this.kind, error: null });
    const health = await api.probeHealth(2500);
    if (!health) {
      this.patchState({ phase: 'offline', error: 'The NAS did not answer on the local network.' });
      throw new TransportError('NAS unreachable over HTTP', 'unreachable');
    }
    this.patchState({
      phase: 'online',
      kind: this.kind,
      nasName: health.nasName,
      freeBytes: health.freeBytes,
      path: 'HTTP · local network',
      // There is no separate signaling connection on this tier at all.
      signalingIdle: true,
      note: null,
      error: null,
    });
    this.openSocket();
  }

  stop(): void {
    this.stopped = true;
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.reconnectTimer = null;
    this.socket?.close();
    this.socket = null;
    this.patchState({ phase: 'idle' });
  }

  // -------------------------------------------------------------------------
  // Push socket
  // -------------------------------------------------------------------------

  private openSocket(): void {
    if (this.stopped) return;
    const socket = new WebSocket(api.signalSocketUrl('/ws/signal'));
    this.socket = socket;

    socket.addEventListener('open', () => {
      this.reconnectAttempt = 0;
      this.patchState({ phase: 'online', note: null });
    });
    socket.addEventListener('message', (event) => {
      if (typeof event.data !== 'string') return;
      let parsed: unknown;
      try {
        parsed = JSON.parse(event.data);
      } catch {
        return;
      }
      // The socket is shared with WebRTC signaling; envelopes are not ours here.
      if (isSignalEnvelope(parsed)) return;
      const message = parsed as ControlMessage;
      if (message.type === 'item-new') this.emit({ type: 'item-new', item: message.item });
      else if (message.type === 'item-removed') this.emit({ type: 'item-removed', itemId: message.itemId });
      else if (message.type === 'item-updated') this.emit({ type: 'item-updated', item: message.item });
      else if (message.type === 'ready') {
        this.patchState({ nasName: message.nasName, freeBytes: message.freeBytes });
      }
    });
    socket.addEventListener('close', () => {
      if (this.stopped) return;
      this.socket = null;
      this.patchState({ phase: 'reconnecting', note: 'Live updates reconnecting…' });
      // Exponential backoff capped at 15 s — a NAS reboot should not produce a
      // reconnect storm, but coming back from sleep should recover quickly.
      const delay = Math.min(15_000, 500 * 2 ** this.reconnectAttempt);
      this.reconnectAttempt += 1;
      this.reconnectTimer = setTimeout(() => this.openSocket(), delay);
    });
  }

  // -------------------------------------------------------------------------
  // Library
  // -------------------------------------------------------------------------

  async list(params: ListParams): Promise<ListResult> {
    return api.listItems(params);
  }

  async postText(text: string, kind: TextKind, clientId: string): Promise<Item> {
    const { item } = await api.postText(text, kind, clientId);
    return item;
  }

  async remove(itemId: string): Promise<void> {
    await api.deleteItem(itemId);
  }

  mediaUrl(item: Item, variant: 'raw' | 'thumb'): string | null {
    if (variant === 'thumb' && !item.thumbUrl) {
      // Thumbnails can be off (ENABLE_THUMBNAILS=0 on a low-power NAS). On the
      // LAN that is fine — point the tile at the original and let the browser
      // downscale. A video without a poster has nothing useful to show.
      return item.kind === 'image' ? api.mediaUrl(item.id, 'raw') : null;
    }
    return api.mediaUrl(item.id, variant);
  }

  async fetchItemBlob(item: Item, onProgress?: (bytes: number) => void): Promise<Blob> {
    const res = await fetch(api.mediaUrl(item.id, 'raw'), { cache: 'no-store' });
    if (!res.ok) throw new TransportError(`Download failed (${res.status})`, 'io-error');
    if (!res.body || !onProgress) return res.blob();

    const reader = res.body.getReader();
    const parts: BlobPart[] = [];
    let received = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      parts.push(value);
      received += value.byteLength;
      onProgress(received);
    }
    return new Blob(parts, { type: item.mime ?? 'application/octet-stream' });
  }

  // -------------------------------------------------------------------------
  // Upload
  // -------------------------------------------------------------------------

  /**
   * Two-step, mirroring the DataChannel `upload-init` → `upload-ready` exchange:
   * the NAS gets to dedup by sha256 and to tell us how much of a previous
   * attempt survived before we send a single byte.
   */
  async uploadFile(ctx: UploadContext): Promise<Item> {
    for (;;) {
      const ready = await api.uploadInit(ctx.transferId, ctx.meta);
      ctx.onReady({ haveChunks: ready.haveChunks, skipEntirely: ready.skipEntirely });

      if (ready.skipEntirely) {
        ctx.onProgress(ctx.meta.size);
        if (ready.item) return ready.item;
        return this.awaitPushedItem(ctx.meta.sha256);
      }

      // haveChunks is a set of indices, but HTTP resume is a byte offset, so
      // only the contiguous prefix is usable here. Any holes get re-sent — on a
      // LAN that costs milliseconds and keeps the server side trivial.
      const resumeFromChunk = contiguousPrefix(ready.haveChunks);
      const offset = Math.min(resumeFromChunk * CHUNK_SIZE, ctx.meta.size);

      try {
        return await this.putBody(ctx, offset);
      } catch (error) {
        if (error === PAUSED) {
          await ctx.gate.wait();
          if (ctx.signal.aborted) throw new TransportError('Transfer cancelled', 'cancelled');
          continue; // re-init so the NAS tells us the new resume point
        }
        throw error;
      }
    }
  }

  private putBody(ctx: UploadContext, offset: number): Promise<Item> {
    return new Promise<Item>((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      // Must use apiUrl: standalone UI on :8421 points API at the agent (:8420).
      // A relative path would POST to the static host and hang / fail silently.
      const url = api.apiUrl(
        `/api/upload?transferId=${encodeURIComponent(ctx.transferId)}&offset=${offset}`,
      );
      xhr.open('POST', url, true);
      const token = api.getAuthToken();
      if (token) xhr.setRequestHeader('authorization', `Bearer ${token}`);
      xhr.setRequestHeader('content-type', 'application/octet-stream');
      xhr.responseType = 'json';

      // fetch() gives no upload progress (request streaming is still not
      // broadly available), so the LAN tier uses XHR purely for this event.
      xhr.upload.addEventListener('progress', (event) => {
        ctx.onProgress(offset + event.loaded);
      });

      const cleanup = (): void => {
        unsubscribePause();
        ctx.signal.removeEventListener('abort', onAbort);
      };
      const onAbort = (): void => {
        xhr.abort();
        cleanup();
        reject(new TransportError('Transfer cancelled', 'cancelled'));
      };
      const unsubscribePause = ctx.gate.onChange((paused) => {
        if (!paused) return;
        xhr.abort();
        cleanup();
        reject(PAUSED);
      });
      ctx.signal.addEventListener('abort', onAbort, { once: true });

      xhr.addEventListener('error', () => {
        cleanup();
        reject(new TransportError('Upload connection lost', 'unreachable'));
      });
      xhr.addEventListener('load', () => {
        cleanup();
        if (xhr.status === 401 || xhr.status === 403) {
          reject(new TransportError('Device is no longer paired', 'unauthorized'));
          return;
        }
        if (xhr.status === 507) {
          reject(new TransportError('The NAS is out of space', 'out-of-space'));
          return;
        }
        if (xhr.status < 200 || xhr.status >= 300) {
          const body = xhr.response as { message?: string } | null;
          reject(new TransportError(body?.message ?? `Upload failed (${xhr.status})`, 'io-error'));
          return;
        }
        const body = xhr.response as
          | (Extract<ControlMessage, { type: 'upload-verified' }> | Extract<ControlMessage, { type: 'upload-error' }>)
          | null;
        if (body?.type === 'upload-verified') {
          ctx.onProgress(ctx.meta.size);
          resolve(body.item);
          return;
        }
        if (body?.type === 'upload-error') {
          reject(
            new TransportError(
              body.message,
              body.code === 'out-of-space' ? 'out-of-space'
              : body.code === 'checksum-mismatch' ? 'checksum-mismatch'
              : 'io-error',
            ),
          );
          return;
        }
        reject(new TransportError('The NAS returned an unexpected upload response', 'io-error'));
      });

      xhr.send(ctx.file.slice(offset));
    });
  }

  /**
   * Dedup hit with no inline item: the NAS still created a timeline entry, so
   * wait briefly for the push rather than forcing a full list refresh.
   */
  private awaitPushedItem(sha256: string): Promise<Item> {
    return new Promise<Item>((resolve, reject) => {
      const timer = setTimeout(() => {
        unsubscribe();
        reject(new TransportError('Upload completed but the item never appeared', 'io-error'));
      }, 5000);
      const unsubscribe = this.subscribeEvents((event) => {
        if (event.type === 'item-new' && event.item.sha256 === sha256) {
          clearTimeout(timer);
          unsubscribe();
          resolve(event.item);
        }
      });
    });
  }
}

/** Length of the leading run 0,1,2,… present in `have`. */
export function contiguousPrefix(have: number[]): number {
  if (have.length === 0) return 0;
  const present = new Set(have);
  let index = 0;
  while (present.has(index)) index += 1;
  return index;
}
