/**
 * Hand-rolled 24px stroke icons. Bundled as components rather than pulled from
 * an icon font/CDN — the NAS may have no internet, and a font request that
 * hangs would block first paint.
 */
import type { ReactNode } from 'react';

interface IconProps {
  className?: string;
}

function Svg({ children, className }: IconProps & { children: ReactNode }): JSX.Element {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      {children}
    </svg>
  );
}

