import { CHUNK_SIZE, type FileMeta, type Item } from '@filedrop/shared';
import { newTransferSeq, seqToTransferId } from '../lib/ids';
import { useTransfers, type TransferRecord } from '../state/transfers';
import { hashFile } from './hash';
import { transport } from './transport';
import { TransferGate, TransportError } from './types';

/**
 * Upload engine: hashing, queueing, resume, backpressure-aware progress.
 *
 * It deliberately knows nothing about *how* bytes move — that is the
 * transport's job. What lives here is everything that has to behave the same
 * whether we are on LAN HTTP or a WebRTC DataChannel.
 */

/** How many files move at once. Three keeps a gigabit link saturated without
 *  thrashing the NAS's disk or the DataChannel's send queue. */
const MAX_CONCURRENT = 3;
/** Attempts per file before giving up, for errors that look transient. */
const MAX_ATTEMPTS = 4;
/** Throughput sampling period; also the UI refresh rate for rate/ETA. */
const SAMPLE_MS = 500;
/** EMA weight for the newest sample. Low enough to stop the number flickering. */
const RATE_ALPHA = 0.3;

interface Job {
  id: string;
  seq: number;
  file: File;
  controller: AbortController;
  gate: TransferGate;
  /** Cached across retries so a dropped link does not re-hash a 10 GB file. */
  meta: FileMeta | null;
}

const jobs = new Map<string, Job>();
const queue: string[] = [];
const running = new Set<string>();
const lastSample = new Map<string, { bytes: number; at: number }>();
let sampler: ReturnType<typeof setInterval> | null = null;

let onItemAccepted: ((item: Item) => void) | null = null;

/** The items store registers here so a finished upload lands in the timeline. */
export function setUploadListener(listener: (item: Item) => void): void {
  onItemAccepted = listener;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function enqueueFiles(files: Iterable<File>): string[] {
  const ids: string[] = [];
  for (const file of files) {
    const seq = newTransferSeq();
    const id = seqToTransferId(seq);
    const record: TransferRecord = {
      id,
      seq,
      name: file.name || 'clipboard',
      size: file.size,
      mime: file.type || 'application/octet-stream',
      status: 'queued',
      bytesDone: 0,
      hashedBytes: 0,
      rate: 0,
      etaMs: null,
      resumedFromBytes: 0,
      attempts: 0,
      itemId: null,
      error: null,
      startedAt: Date.now(),
      finishedAt: null,
    };
    useTransfers.getState().add(record);
    jobs.set(id, {
      id,
      seq,
      file,
      controller: new AbortController(),
      gate: new TransferGate(),
      meta: null,
    });
    queue.push(id);
    ids.push(id);
  }
  pump();
  return ids;
}

export function pauseTransfer(id: string): void {
  const job = jobs.get(id);
  if (!job) return;
  job.gate.pause();
  useTransfers.getState().patch(id, { status: 'paused', rate: 0, etaMs: null });
}

export function resumeTransfer(id: string): void {
  const job = jobs.get(id);
  if (!job) return;
  job.gate.resume();
  useTransfers.getState().patch(id, { status: running.has(id) ? 'uploading' : 'queued' });
}

export function cancelTransfer(id: string): void {
  const job = jobs.get(id);
  if (!job) return;
  const queuedIndex = queue.indexOf(id);
  if (queuedIndex >= 0) queue.splice(queuedIndex, 1);
  // Resume first: a paused job is parked inside gate.wait() and would never
  // observe the abort otherwise.
  job.gate.resume();
  job.controller.abort();
  if (!running.has(id)) {
    useTransfers.getState().patch(id, { status: 'cancelled', finishedAt: Date.now(), rate: 0 });
    jobs.delete(id);
  }
}

export function retryTransfer(id: string): void {
  const job = jobs.get(id);
  if (!job || running.has(id) || queue.includes(id)) return;
  job.controller = new AbortController();
  job.gate.resume();
  useTransfers.getState().patch(id, {
    status: 'queued',
    error: null,
    attempts: 0,
    bytesDone: 0,
    rate: 0,
    etaMs: null,
    finishedAt: null,
  });
  queue.push(id);
  pump();
}

/** True when the record still has its File handle and can be retried. */
export function canRetry(id: string): boolean {
  return jobs.has(id);
}

// ---------------------------------------------------------------------------
// Scheduler
// ---------------------------------------------------------------------------

function pump(): void {
  while (running.size < MAX_CONCURRENT && queue.length > 0) {
    const id = queue.shift();
    if (!id) break;
    const job = jobs.get(id);
    if (!job) continue;
    running.add(id);
    void runJob(job).finally(() => {
      running.delete(id);
      lastSample.delete(id);
      stopSamplerIfIdle();
      pump();
    });
  }
  startSampler();
}

async function runJob(job: Job): Promise<void> {
  const patch = (values: Partial<TransferRecord>): void => useTransfers.getState().patch(job.id, values);
  const releaseBusy = transport.acquireBusy();

  try {
    // 1. Hash. Content addressing is what makes dedup and resume possible, so
    //    it has to happen before anything goes on the wire. Streamed in a
    //    worker — see hash.ts for why WebCrypto alone is not enough.
    if (!job.meta) {
      patch({ status: 'preparing', hashedBytes: 0 });
      const sha256 = await hashFile(job.file, {
        onProgress: (bytesHashed) => patch({ hashedBytes: bytesHashed }),
        signal: job.controller.signal,
      });
      job.meta = {
        name: job.file.name || 'clipboard',
        size: job.file.size,
        mime: job.file.type || 'application/octet-stream',
        sha256,
        lastModified: job.file.lastModified || Date.now(),
        chunkSize: CHUNK_SIZE,
      };
    }
    const meta = job.meta;

    // 2. Send, retrying transient link failures. Each attempt re-runs
    //    upload-init, so the NAS reports which chunks it actually committed and
    //    we resume from there rather than re-sending gigabytes.
    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
      patch({ attempts: attempt, status: 'negotiating', error: null });
      try {
        const { item, deduped } = await sendOnce(job, meta, patch);
        useTransfers.getState().patch(job.id, {
          status: deduped ? 'deduped' : 'done',
          bytesDone: meta.size,
          itemId: item.id,
          error: null,
          rate: 0,
          etaMs: null,
          finishedAt: Date.now(),
        });
        onItemAccepted?.(item);
        jobs.delete(job.id);
        return;
      } catch (error) {
        if (job.controller.signal.aborted) throw error;
        const transportError = error instanceof TransportError ? error : null;
        const retryable =
          transportError == null ||
          transportError.code === 'unreachable' ||
          transportError.code === 'io-error';
        if (!retryable || attempt === MAX_ATTEMPTS) throw error;
        patch({ status: 'queued', rate: 0, etaMs: null, error: 'Link dropped — resuming…' });
        await waitForTransport(job, attempt);
      }
    }
  } catch (error) {
    finishWithError(job, error);
  } finally {
    releaseBusy();
  }
}

async function sendOnce(
  job: Job,
  meta: FileMeta,
  patch: (values: Partial<TransferRecord>) => void,
): Promise<{ item: Item; deduped: boolean }> {
  let deduped = false;

  const item = await transport.uploadFile({
    file: job.file,
    meta,
    transferId: job.id,
    transferSeq: job.seq,
    gate: job.gate,
    signal: job.controller.signal,
    onReady: (ready) => {
      if (ready.skipEntirely) {
        deduped = true;
        patch({ status: 'verifying', bytesDone: meta.size, resumedFromBytes: 0 });
        return;
      }
      const resumedBytes = Math.min(meta.size, ready.haveChunks.length * CHUNK_SIZE);
      patch({
        status: job.gate.isPaused ? 'paused' : 'uploading',
        resumedFromBytes: resumedBytes,
        bytesDone: resumedBytes,
      });
      lastSample.set(job.id, { bytes: resumedBytes, at: performance.now() });
    },
    onProgress: (bytesDone) => {
      if (deduped) return;
      if (bytesDone >= meta.size) {
        patch({ bytesDone: meta.size, status: 'verifying', rate: 0, etaMs: null });
      } else {
        patch({ bytesDone, status: job.gate.isPaused ? 'paused' : 'uploading' });
      }
    },
  });

  return { item, deduped };
}

function finishWithError(job: Job, error: unknown): void {
  const cancelled =
    job.controller.signal.aborted ||
    (error instanceof TransportError && error.code === 'cancelled') ||
    (error instanceof DOMException && error.name === 'AbortError');

  const message =
    error instanceof TransportError && error.code === 'out-of-space' ? 'The NAS is out of space'
    : error instanceof TransportError && error.code === 'checksum-mismatch' ?
      'Checksum mismatch — the file did not arrive intact'
    : error instanceof TransportError && error.code === 'unsupported' ? error.message
    : error instanceof Error ? error.message
    : 'Upload failed';

  useTransfers.getState().patch(job.id, {
    status: cancelled ? 'cancelled' : 'error',
    error: cancelled ? null : message,
    rate: 0,
    etaMs: null,
    finishedAt: Date.now(),
  });
  if (cancelled) jobs.delete(job.id);
}

/** Back off, then wait for the manager to report a usable link again. */
function waitForTransport(job: Job, attempt: number): Promise<void> {
  return new Promise<void>((resolve) => {
    let settled = false;
    const finish = (): void => {
      if (settled) return;
      settled = true;
      resolve();
    };
    const delay = Math.min(8000, 500 * 2 ** attempt);
    const timer = setTimeout(() => {
      if (settled) return;
      const unsubscribe = transport.subscribeState((state) => {
        if (state.phase === 'online' || state.phase === 'degraded' || job.controller.signal.aborted) {
          unsubscribe();
          finish();
        }
      });
      // Never wait forever: fall through and let the next attempt fail fast.
      setTimeout(() => {
        unsubscribe();
        finish();
      }, 30_000);
    }, delay);
    job.controller.signal.addEventListener(
      'abort',
      () => {
        clearTimeout(timer);
        finish();
      },
      { once: true },
    );
  });
}

// ---------------------------------------------------------------------------
// Throughput sampling
// ---------------------------------------------------------------------------

/**
 * Rate is smoothed with an EMA rather than reported raw: chunk delivery is
 * bursty (especially over SCTP, where one drain releases several MB at once)
 * and an unsmoothed number is unreadable.
 */
function startSampler(): void {
  if (sampler || running.size === 0) return;
  sampler = setInterval(() => {
    const store = useTransfers.getState();
    const now = performance.now();
    for (const id of running) {
      const record = store.byId[id];
      if (!record) continue;
      if (record.status !== 'uploading') {
        lastSample.set(id, { bytes: record.bytesDone, at: now });
        continue;
      }
      const previous = lastSample.get(id) ?? { bytes: record.bytesDone, at: now };
      const elapsed = (now - previous.at) / 1000;
      if (elapsed <= 0) continue;
      const instant = Math.max(0, (record.bytesDone - previous.bytes) / elapsed);
      const rate = record.rate > 0 ? record.rate * (1 - RATE_ALPHA) + instant * RATE_ALPHA : instant;
      const remaining = Math.max(0, record.size - record.bytesDone);
      store.patch(id, { rate, etaMs: rate > 1024 ? (remaining / rate) * 1000 : null });
      lastSample.set(id, { bytes: record.bytesDone, at: now });
    }
  }, SAMPLE_MS);
}

function stopSamplerIfIdle(): void {
  if (running.size > 0 || !sampler) return;
  clearInterval(sampler);
  sampler = null;
}

// ---------------------------------------------------------------------------
// Helpers used by the UI
// ---------------------------------------------------------------------------

/** Turn a pasted image blob into a File with a sensible name. */
export function fileFromClipboardBlob(blob: Blob, index = 0): File {
  const extension = blob.type.split('/')[1]?.split('+')[0] ?? 'png';
  const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const suffix = index > 0 ? `-${index + 1}` : '';
  return new File([blob], `pasted-${stamp}${suffix}.${extension}`, {
    type: blob.type || 'image/png',
    lastModified: Date.now(),
  });
}
