import { randomId } from '../lib/ids';
import { Sha256, bytesToHex } from './sha256';
import type { HashRequest, HashResponse } from './hash.worker';
// `?worker&inline` embeds the worker in the main bundle and constructs it from
// a blob URL, instead of emitting a second .js file fetched at runtime. That is
// what lets the single-file build work at all — and it also means the worker
// cannot 404 behind a misconfigured base path. The worker is ~3 KB, so the cost
// to the normal builds is negligible.
import HashWorker from './hash.worker?worker&inline';

/** Above this size we stream in a worker; below it WebCrypto one-shot wins. */
const WEBCRYPTO_MAX = 8 * 1024 * 1024;
/** Bytes pulled off disk per read inside the worker. */
const SLICE_SIZE = 4 * 1024 * 1024;

let worker: Worker | null = null;
let workerBroken = false;

function getWorker(): Worker | null {
  if (workerBroken) return null;
  if (worker) return worker;
  try {
    worker = new HashWorker();
    worker.addEventListener('error', () => {
      workerBroken = true;
      worker = null;
    });
    return worker;
  } catch {
    workerBroken = true;
    return null;
  }
}

export interface HashOptions {
  onProgress?: (bytesHashed: number) => void;
  signal?: AbortSignal;
}

/**
 * SubtleCrypto, or null when the browser withholds it.
 *
 * `crypto.subtle` is ONLY exposed in a secure context — HTTPS or localhost. A
 * self-hosted NAS is reached at http://10.0.0.2:8420, which is neither, so the
 * whole API is simply absent and `crypto.subtle.digest(...)` throws
 * "Cannot read properties of undefined (reading 'digest')".
 *
 * That would block every upload, because the SHA-256 is computed before any
 * bytes go out (it is the identity the NAS dedups and resumes on). Note that
 * `crypto.getRandomValues` is NOT restricted this way — only `subtle` is.
 */
function getSubtle(): SubtleCrypto | null {
  return typeof crypto !== 'undefined' && crypto.subtle ? crypto.subtle : null;
}

/** True when this page can use native WebCrypto digests. */
export function hasNativeDigest(): boolean {
  return getSubtle() !== null;
}

/**
 * SHA-256 of a short string, lowercase hex.
 *
 * Used by the authorisation flow to commit to a secret without transmitting
 * it: the waiting device registers `sha256(secret)` over signaling and puts the
 * secret itself only in the QR, so anyone reading the channel learns nothing
 * that lets them impersonate a scan.
 *
 * Goes through `getSubtle()` for the same reason `hashFile` does — the NAS is
 * reached at `http://10.0.0.2:8420`, which is not a secure context, so
 * `crypto.subtle` is simply absent there and calling it directly would throw.
 * The input is a few dozen bytes, so the pure-JS fallback is instant and there
 * is no need to involve the worker.
 */
export async function sha256Text(text: string): Promise<string> {
  const bytes = new TextEncoder().encode(text);
  const subtle = getSubtle();
  if (subtle) return bytesToHex(await subtle.digest('SHA-256', bytes));
  return new Sha256().update(bytes).digestHex();
}

/**
 * Whole-file SHA-256, lowercase hex — the identity the NAS dedups and resumes
 * on, so it has to be computed before a single byte goes out.
 *
 * Small files take the native WebCrypto path when it exists. Large ones — and
 * everything on plain HTTP, where `subtle` is unavailable — go to a worker
 * running an incremental implementation. `crypto.subtle.digest` needs the whole
 * message in memory anyway, and a 10 GB ArrayBuffer is not a thing a tab
 * survives.
 */
export async function hashFile(file: Blob, options: HashOptions = {}): Promise<string> {
  const subtle = getSubtle();

  if (subtle && file.size <= WEBCRYPTO_MAX) {
    const buffer = await file.arrayBuffer();
    options.onProgress?.(file.size);
    const digest = await subtle.digest('SHA-256', buffer);
    return bytesToHex(digest);
  }

  // No native digest: fall through to the worker even for small files, so the
  // pure-JS hash stays off the main thread and the UI keeps painting.
  const w = getWorker();
  if (!w) return hashOnMainThread(file, options);

  const id = randomId('h');
  return new Promise<string>((resolve, reject) => {
    const onMessage = (event: MessageEvent<HashResponse>): void => {
      const data = event.data;
      if (data.id !== id) return;
      if (data.type === 'progress') {
        options.onProgress?.(data.bytesHashed);
        return;
      }
      cleanup();
      if (data.type === 'done') resolve(data.sha256);
      else reject(new Error(data.message));
    };
    const onAbort = (): void => {
      cleanup();
      // The worker finishes the file it started; we simply stop listening. The
      // alternative — terminating the worker — would cost a fresh spin-up for
      // the next file, which is worse than a few wasted CPU-seconds.
      reject(new DOMException('Hashing cancelled', 'AbortError'));
    };
    const cleanup = (): void => {
      w.removeEventListener('message', onMessage);
      options.signal?.removeEventListener('abort', onAbort);
    };

    w.addEventListener('message', onMessage);
    options.signal?.addEventListener('abort', onAbort, { once: true });
    const request: HashRequest = { id, file, sliceSize: SLICE_SIZE };
    w.postMessage(request);
  });
}

/** Fallback for environments where module workers are unavailable. */
async function hashOnMainThread(file: Blob, options: HashOptions): Promise<string> {
  const hasher = new Sha256();
  let offset = 0;
  while (offset < file.size) {
    if (options.signal?.aborted) throw new DOMException('Hashing cancelled', 'AbortError');
    const end = Math.min(offset + SLICE_SIZE, file.size);
    const buffer = await file.slice(offset, end).arrayBuffer();
    hasher.update(new Uint8Array(buffer));
    offset = end;
    options.onProgress?.(offset);
    // Yield so the UI can paint between slices.
    await new Promise((resolve) => setTimeout(resolve, 0));
  }
  return hasher.digestHex();
}
