import type { Item } from '@filedrop/shared';
import { transport } from '../net/transport';
import { toast } from '../state/toasts';

function trigger(href: string, filename: string, revoke: boolean): void {
  const anchor = document.createElement('a');
  anchor.href = href;
  anchor.download = filename;
  anchor.rel = 'noopener';
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  // Revoking immediately can cancel the download in Safari; one tick is enough.
  if (revoke) setTimeout(() => URL.revokeObjectURL(href), 30_000);
}

/**
 * Save an item locally. On the LAN tier this is a normal browser download
 * straight from the NAS (streamed, resumable, no memory cost). Over P2P the
 * bytes have to come through the DataChannel first, so they are assembled into
 * a Blob and handed to the browser as an object URL.
 */
export async function downloadItem(item: Item): Promise<void> {
  const filename = item.name ?? `filedrop-${item.id}`;
  const direct = transport.mediaUrl(item, 'raw');
  if (direct) {
    trigger(direct, filename, false);
    return;
  }

  toast.info(`Pulling ${filename} over the direct link…`);
  try {
    const blob = await transport.fetchItemBlob(item);
    trigger(URL.createObjectURL(blob), filename, true);
  } catch (error) {
    toast.error(error instanceof Error ? error.message : 'Download failed');
  }
}
